INSERT INTO `character_attacks` VALUES (3,4,'Besta Poderosa',NULL,NULL,'dexterity',1,0,'1d10','piercing','[\"dexterity\"]',0,NULL,NULL,NULL,0,0,'{\"range\": \"120/300ft\", \"masteries\": [\"Push\"], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1787806913102-8y7dtx\", \"type\": \"piercing\", \"bonus\": 0, \"abilities\": [\"dexterity\"], \"expression\": \"1d10\"}]}','2026-08-25 21:22:16','2026-08-30 09:06:46'),(4,4,'Cursiva',NULL,NULL,'dexterity',1,2,'1d8','piercing','[\"dexterity\"]',2,NULL,NULL,NULL,1,0,'{\"range\": \"5ft\", \"masteries\": [\"Nick\"], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1787772543515-bfrasi\", \"type\": \"piercing\", \"bonus\": 2, \"abilities\": [\"dexterity\"], \"expression\": \"1d8\"}, {\"id\": \"damage-1787772564882-g4ylrw\", \"type\": \"radiant\", \"bonus\": 0, \"abilities\": [], \"expression\": \"1d8\"}, {\"id\": \"damage-1787772565274-k8wm22\", \"type\": \"acid\", \"bonus\": 0, \"abilities\": [], \"expression\": \"2d4\"}]}','2026-08-26 22:28:51','2026-08-26 22:29:37'),(5,8,'Insensatez','Insensatez - Desvantagem','Se você acertar uma criatura com esta arma, ela terá Desvantagem na próxima jogada de ataque que fizer antes do início do seu próximo turno.','dexterity',1,3,'1d10','force','[\"dexterity\"]',5,NULL,NULL,NULL,1,0,'{\"range\": \"100/400ft\", \"masteries\": [\"Sap\"], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1787852799321-is9f0z\", \"type\": \"force\", \"bonus\": 5, \"abilities\": [\"dexterity\"], \"expression\": \"1d10\"}, {\"id\": \"damage-1787852820536-tsdrts\", \"type\": \"force\", \"bonus\": 0, \"abilities\": [], \"expression\": \"2d6\"}, {\"id\": \"damage-1787854102201-4lzwhs\", \"type\": \"fire\", \"bonus\": 0, \"abilities\": [], \"expression\": \"1d8\"}]}','2026-08-27 20:45:59','2026-08-27 21:09:01'),(6,8,'Besta Elegante',NULL,NULL,'dexterity',1,2,'1d8','piercing','[\"dexterity\"]',4,NULL,NULL,NULL,1,0,'{\"range\": \"80/320ft\", \"masteries\": [\"Slow\"], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1787853253828-bdtajg\", \"type\": \"piercing\", \"bonus\": 4, \"abilities\": [\"dexterity\"], \"expression\": \"1d8\"}]}','2026-08-27 20:52:59','2026-08-27 20:58:06'),(8,8,'Adaga Psíquica','Ataque Extra - Ação Bônus','Após atacar com a lâmina no seu turno, você pode realizar um ataque corpo a corpo ou à distância com uma segunda lâmina psíquica como uma Ação Bônus no mesmo turno, caso sua outra mão esteja livre para criá-la. O dado de dano deste ataque bônus é 2d4 em vez de 2d6 .','dexterity',1,2,'2d6','psychic','[\"dexterity\"]',4,NULL,NULL,NULL,1,0,'{\"range\": \"60/120ft\", \"masteries\": [\"Vex\"], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1787853497730-12kpux\", \"type\": \"psychic\", \"bonus\": 4, \"abilities\": [\"dexterity\"], \"expression\": \"2d6\"}]}','2026-08-27 21:03:47','2026-08-28 03:18:43'),(9,8,'Vocal de Fogo','Chamas Vivas','Ao atingir um alvo, ele deve realizar um teste de resistência de Destreza (CD 15). Em caso de falha, a criatura fica em chamas, sofrendo 1d6 de dano de fogo no início de cada um de seus turnos. A criatura pode usar uma ação para apagar as chamas.','dexterity',1,2,'2d6','fire','[\"dexterity\"]',2,NULL,NULL,NULL,1,0,'{\"range\": \"10ft\", \"masteries\": [\"Vex\"], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1787853877533-714tu4\", \"type\": \"fire\", \"bonus\": 2, \"abilities\": [\"dexterity\"], \"expression\": \"2d6\"}]}','2026-08-27 21:07:04','2026-08-27 21:07:04'),(10,8,'Ataque Furtivo',NULL,NULL,NULL,0,0,'10d6',NULL,'[]',0,NULL,NULL,NULL,1,0,'{\"range\": null, \"masteries\": [], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1787854191986-7ykcax\", \"type\": null, \"bonus\": 0, \"abilities\": [], \"expression\": \"10d6\"}]}','2026-08-27 21:09:41','2026-08-28 01:08:48'),(11,12,'Cajado',NULL,NULL,'dexterity',1,1,'1da10','bludgeoning','[\"dexterity\"]',0,NULL,NULL,NULL,1,0,'{\"range\": \"5ft\", \"masteries\": [\"Topple\"], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1788034191568-cheh6d\", \"type\": \"bludgeoning\", \"bonus\": 0, \"abilities\": [\"dexterity\"], \"expression\": \"1da10\"}]}','2026-08-29 23:10:33','2026-08-29 23:12:34'),(12,12,'Ataque Desarmado',NULL,NULL,'dexterity',1,0,'1d10','bludgeoning','[\"dexterity\"]',0,NULL,NULL,NULL,1,0,'{\"range\": \"5ft\", \"masteries\": [], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1788034265988-pobqkl\", \"type\": \"bludgeoning\", \"bonus\": 0, \"abilities\": [\"dexterity\"], \"expression\": \"1d10\"}]}','2026-08-29 23:11:44','2026-08-29 23:12:28'),(13,12,'Mão do Mal','Mão da Perdição','Quando você usa Mão da Perdição em uma criatura, você também pode infligir a ela a condição Envenenada até o final do seu próximo turno.','dexterity',1,0,'1d10','bludgeoning','[\"dexterity\"]',0,NULL,NULL,NULL,1,0,'{\"range\": \"5ft\", \"masteries\": [], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1788034371401-bimoxq\", \"type\": \"bludgeoning\", \"bonus\": 0, \"abilities\": [\"dexterity\"], \"expression\": \"1d10\"}, {\"id\": \"damage-1788034417463-nqzjcx\", \"type\": \"necrotic\", \"bonus\": 0, \"abilities\": [], \"expression\": \"1d10\"}]}','2026-08-29 23:12:14','2026-08-29 23:15:05'),(14,12,'Mão da Cura','Mão da Cura','Ao usar Mão da Cura, você também pode remover uma das seguintes condições da criatura que você cura: Cegueira , Surdez , Paralisia , Envenenamento ou Atordoamento .',NULL,0,0,'1d10',NULL,'[\"wisdom\"]',0,NULL,NULL,NULL,1,0,'{\"range\": \"5ft\", \"masteries\": [], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1788034522791-0ku18u\", \"type\": null, \"bonus\": 0, \"abilities\": [\"wisdom\"], \"expression\": \"1d10\"}]}','2026-08-29 23:16:23','2026-08-29 23:16:23'),(15,9,'Capim',NULL,NULL,'dexterity',1,3,'2d10','bludgeoning','[\"dexterity\"]',3,NULL,NULL,NULL,1,0,'{\"range\": \"15ft\", \"masteries\": [\"Cleave\", \"Graze\", \"Nick\", \"Push\", \"Sap\", \"Slow\", \"Topple\", \"Vex\"], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1788043049098-v01lnq\", \"type\": \"bludgeoning\", \"bonus\": 3, \"abilities\": [\"dexterity\"], \"expression\": \"2d10\"}]}','2026-08-30 01:39:35','2026-08-30 01:39:35'),(17,9,'Ataque Primordial Aprimorada','1 vez por turno depois do primeiro ataque','Uma vez em cada um dos seus turnos, ao atingir uma criatura com uma jogada de ataque usando uma arma ou um ataque da forma Animal em Forma Selvagem, pode causar 2d8 pontos de dano Elétrico, Gélido, Ígneo, Trovejante ou Impacto. (à sua escolha quando você atinge) adicional ao alvo.',NULL,0,0,'2d8','bludgeoning','[]',0,NULL,NULL,NULL,1,0,'{\"range\": null, \"masteries\": [], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1788043301747-okfg1l\", \"type\": \"bludgeoning\", \"bonus\": 0, \"abilities\": [], \"expression\": \"2d8\"}]}','2026-08-30 01:46:30','2026-08-30 01:49:35'),(18,9,'Radiância Lunar','1 vez por turno depois do primeiro ataque enquanto na Forma Selvagem','Uma vez por turno, você pode causar 2d10 pontos de dano Radiante adicional a um alvo que você acerta com o ataque da Forma Selvagem.',NULL,0,0,'2d10','bludgeoning','[]',0,NULL,NULL,NULL,1,0,'{\"range\": null, \"masteries\": [], \"counter_mode\": \"spend\", \"damage_parts\": [{\"id\": \"damage-1788043622275-lmyadn\", \"type\": \"bludgeoning\", \"bonus\": 0, \"abilities\": [], \"expression\": \"2d10\"}]}','2026-08-30 01:49:18','2026-08-30 01:49:18'),(19,11,'Yamato',NULL,NULL,'dexterity',1,3,NULL,NULL,'[]',0,NULL,NULL,NULL,1,0,'{\"range\": null, \"masteries\": [\"Push\", \"Sap\", \"Slow\"], \"counter_mode\": \"spend\", \"damage_parts\": []}','2026-09-01 07:38:08','2026-09-01 07:38:08');
