INSERT INTO `character_features` VALUES (1,4,'Canalizar Divindade (Duplicidade)','class_feature','Clérigo',3,'-Feitiços podem ser conjurador através da duplicidade.\n     -Estar a até 5ft da duplicidade te da vantagem nos testes de ataque.\n     -Mover ela é uma Ação Bônus\n     -Quando você move ou conjura a Duplicidade, você pode trocar de lugar com ela.',4,4,'long_rest','{\"column\": \"left\", \"activation\": \"bonus_action\", \"quick_text\": \"Conjura uma segunda Liana em até 30ft, podendo trocar de lugar com ela usando a mesma Ação Bônus, usada para conjurar.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-26 23:33:58','2026-08-28 20:04:02'),(2,7,'Resiliência Construída','class_feature','Warforged',NULL,'Você foi criado para ter uma fortitude notável, representada pelos seguintes benefícios:\n- Você tem vantagem em testes de resistência contra envenenamento e tem resistência a dano de veneno.\n- Você não precisa comer, beber ou respirar.\n- Você é imune a doenças.\n- Você não precisa dormir, e magia não pode fazer você dormir.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Resistencia a Veneno, Imune a Doenças.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 02:22:52','2026-08-27 02:22:52'),(3,7,'Descanso da Sentinela','class_feature','Warforged',NULL,'Quando você faz um descanso longo, você deve passar pelo menos seis horas em um estado inativo e imóvel, em vez de dormir. Neste estado, você parece inerte, mas isso não o deixa inconsciente, e você pode ver e ouvir normalmente.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Não fica inconsciente durante um Descanso Longo.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 02:24:29','2026-08-27 02:24:29'),(4,7,'Proteção Integrada','class_feature','Warforged',NULL,'Seu corpo tem camadas defensivas embutidas, que podem ser aprimoradas com armadura:\n- Você ganha um bônus de +1 na Classe de Armadura.\n- Você pode vestir apenas armaduras com as quais você tem proficiência. Para vestir uma armadura que não seja um escudo, você deve incorporá-la ao seu corpo ao longo de 1 hora, durante a qual você permanece em contato com a armadura. Para tirar a armadura, você deve gastar 1 hora removendo-a. Você pode descansar enquanto veste ou tira a armadura dessa forma.\n- Enquanto você viver, a armadura incorporada ao seu corpo não poderá ser removida contra sua vontade.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"+1 na Classe de Armadura.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 02:25:29','2026-08-27 02:25:29'),(5,7,'Design especializado','class_feature','Warforged',1,'Você ganha uma proficiência em perícia e uma proficiência em ferramenta de sua escolha.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Proficiência em 1 pericias e 1 ferramenta a sua escolha (Atuação e Ferramentas de Tecelão)\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 02:26:50','2026-08-27 02:45:10'),(6,7,'Inspiração Bardida','class_feature','Bardo',NULL,'Você pode inspirar sobrenaturalmente outros por meio de palavras, música ou dança. Essa inspiração é representada pelo seu dado de Inspiração Bárdica, que é um d6 .\n\nUsando Inspiração Bárdica. Como uma Ação Bônus , você pode inspirar outra criatura a até 60 pés de você que pode ver ou ouvir você. Aquela criatura ganha um dos seus dados de Inspiração Bárdica. Uma criatura pode ter apenas um dado de Inspiração Bárdica por vez.\n\nUma vez dentro da próxima hora quando a criatura falha em um Teste D20 , a criatura pode rolar o dado de Inspiração Bárdica e adicionar o número rolado ao d20 , potencialmente transformando a falha em um sucesso. Um dado de Inspiração Bárdica é gasto quando é rolado.\n\nNúmero de Usos. Você pode conferir um dado de Inspiração Bárdica um número de vezes igual ao seu modificador de Carisma (mínimo de uma vez), e você recupera todos os usos gastos quando termina um Descanso Longo .\n\nEm Níveis Mais Altos. Seu dado de Inspiração Bárdica muda quando você alcança certos níveis de Bardo, como mostrado na coluna Dado Bárdico da tabela de Características do Bardo. O dado se torna um d8 no nível 5, um d10 no nível 10 e um d12 no nível 15.',6,6,'short_rest','{\"column\": \"left\", \"activation\": \"bonus_action\", \"quick_text\": \"Usa Ação Bônus para inspirar um Aliado dentro de 60ft.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 02:29:41','2026-08-27 02:29:44'),(7,7,'Expecialização','class_feature','Bardo',2,'Você ganha Expertise em duas de suas proficiências de perícia de sua escolha. Performance e Persuasão são recomendadas se você tiver proficiência nelas.\n\nNo nível 9 de Bardo, você ganha Perícia em mais duas de suas proficiências de perícia de sua escolha.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Expertise (Percepção, Persuasão, acrobacia, Arcanismo)\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 02:44:55','2026-08-27 03:35:39'),(8,7,'Pau para Toda Obra','class_feature','Bardo',2,'Você pode adicionar metade do seu Bônus de Proficiência (arredondado para baixo) a qualquer teste de habilidade que fizer que use uma proficiência de perícia que você não tenha e que não use seu Bônus de Proficiência .\n\nPor exemplo, se você fizer um teste de Força ( Atletismo ) e não tiver proficiência em Atletismo , você pode adicionar metade do seu Bônus de Proficiência ao teste.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Você adiciona metade do seu bônus de proficiência em todas pericias que não tem proficiência.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 03:35:26','2026-08-27 03:35:26'),(9,7,'FootWork Deslumbrante','class_feature','Subclasse: Faculdade da Dança',3,'Enquanto você não estiver usando armadura ou empunhando um Escudo , você ganha os seguintes benefícios.\n\nVirtuoso da dança. Você tem vantagem em qualquer teste de Carisma ( Apresentação ) que fizer que envolva dança.\n\nDefesa sem armadura. Sua Classe de Armadura base é igual a 10 mais seus modificadores de Destreza e Carisma.\n\nAtaques Ágeis. Quando você gasta um uso de sua Inspiração Bárdica como parte de uma ação, uma Ação Bônus ou uma Reação , você pode fazer um Ataque Desarmado como parte dessa ação, Ação Bônus ou Reação .\n\nDano de Bardo. Você pode usar Destreza em vez de Força para as jogadas de ataque dos seus Ataques Desarmados. Quando você causa dano com um Ataque Desarmado , você pode causar dano de Concussão igual a uma jogada do seu dado de Inspiração de Bardo mais seu modificador de Destreza, em vez do dano normal do ataque. Esta jogada não gasta o dado.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:02:28','2026-08-27 04:02:28'),(10,7,'Movimento Inspirador','class_feature','Subclasse: Faculdade da Dança',3,'Quando um inimigo que você pode ver termina seu turno a até 5 pés de você, você pode fazer uma Reação e gastar um uso de sua Inspiração Bárdica para mover até metade de sua Velocidade . Então, um aliado de sua escolha a até 30 pés de você também pode mover até metade de sua Velocidade usando sua Reação .\n\nNenhum movimento deste recurso provoca Ataques de Oportunidade.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"reaction\", \"quick_text\": \"Quando uma criatura termina seu turno a 5ft de você.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:12:01','2026-08-27 04:12:01'),(11,7,'Trabalho de Pés em Tandem','class_feature','Subclasse: Faculdade de Dança',6,'Quando você rola Iniciativa , você pode gastar um uso de sua Inspiração Bárdica se você não tiver a condição Incapacitado . Quando você fizer isso, role seu dado de Inspiração Bárdica; você e cada aliado a até 30 pés de você que pode ver ou ouvir você ganha um bônus de Iniciativa igual ao número rolado.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Quando rolar Iniciativa pode usa sua Inspiração Bárdica para dar um bônus para todos os usuários +1d12 para todos em 30ft .\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:38:36','2026-08-27 04:38:36'),(12,7,'Fonte de Inspiração','class_feature',NULL,5,'Agora você recupera todos os seus usos gastos de Inspiração Bárdica quando termina um Descanso Curto ou Longo .\n\nAlém disso, você pode gastar um espaço de magia (nenhuma ação necessária) para recuperar um uso gasto de Inspiração Bárdica.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Agora você recupera todos os seus usos gastos de Inspiração Bárdica quando termina um Descanso Curto ou Longo .\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:40:50','2026-08-27 04:52:54'),(13,7,'Contra-Feitiço','class_feature','Bardo',10,'Você pode usar notas musicais ou palavras de poder para interromper efeitos de influência mental. Se você ou uma criatura a até 30 pés de você falhar em um teste de resistência contra um efeito que aplique a condição Encantado ou Amedrontado , você pode usar uma Reação para fazer com que o teste seja refeito, e o novo teste tem Vantagem',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"reaction\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:47:37','2026-08-27 04:47:37'),(14,7,'Liderando Evasão','class_feature','Subclasse: Faculdade da Dança',14,'Quando você é afetado por um efeito que permite fazer um teste de resistência de Destreza para sofrer apenas metade do dano, você não sofre dano algum se for bem-sucedido no teste e sofre apenas metade do dano se falhar. Se alguma criatura a até 1,5 metro de você estiver fazendo o mesmo teste de resistência de Destreza, você pode compartilhar esse benefício com ela para esse teste.\n\nVocê não pode usar este recurso se estiver incapacitado .',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:48:28','2026-08-27 04:48:28'),(15,7,'Inspiração Superior','class_feature','Bardo',18,'Ao rolar a Iniciativa , você recupera os usos gastos de Inspiração Bárdica até ter dois, caso tenha menos que isso.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Ao rolar a Iniciativa , você recupera os usos gastos de Inspiração Bárdica até ter dois, caso tenha menos que isso.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:51:24','2026-08-27 04:54:28'),(16,7,'Bênção de Revogação de Feitiços','class_feature','Bardo',19,'Aumento de Pontuação de Habilidade. Aumente sua Carisma em 1, até um máximo de 30.\n\nConjuração Livre. Sempre que conjurar uma magia com um espaço de magia de nível 1-4, role 1d4 . Se o número que você rolar for o mesmo que o nível do espaço, o espaço não será gasto.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:52:44','2026-08-27 04:53:12'),(17,7,'Magnum Opus','class_feature','Bardo',20,'Você despertou o seu Magnum Opus. A magia da arte que habita dentro de você explodiu em algo grandioso e magnífico. Você é a encarnação da festa; continue inspirando todos aqueles que precisam acreditar em si mesmos para alcançar os seus objetivos.\n\n**Aumento de atributo (CAR)**\nAumente sua Constituição, Carisma ou Destreza em +1.\nSeu máximo para esse atributo passa a ser 30.\n\n- **Coreografias De Combate 6/6**\n    \n    Você aprendeu a aplicar movimentos unicos em seus golpes, o permitindo mostrar ao mundo como que se faz.\n    Você possui um numero de Coreografias de Combate igual ao seu modificador de Carisma (Mínimo de 1). Sempre que você acertar uma criatura com um Ataque Desarmado usando as suas pernas, você pode gastar um uso de Coreografia de Combate para realizar um dos seguintes movimentos de dança.\n    Caso uma coreografia exija um Salvamento, a CD é (8 + Proficiencia + Carisma). Por fim, Você recupera todos os usos gastos em um descanso Curto ou Longo.\n    \n    - **Moinho**\n        \n        Ao acertar uma criatura com um Ataque Desarmado, você pode girar rente ao chão, transformando seu corpo em um redemoinho de chutes. Realize um Ataque Desarmado contra cada criatura à sua escolha em um raio de 5 ft. Em um acerto, o alvo sofre o dano normal. Além disso, se o alvo for Grande ou menor deve realizar um Salvamento de Força. Em caso de falha, o alvo cai Deitado (Prone). (Esse movimento, só pode ser usado uma vez por turno)\n        \n    - **Mortal**\n        \n        Ao acertar uma criatura com um Ataque Desarmado, você pode realizar um segundo golpe imediato contra a mesma criatura. Se acertar, você usa o impacto para se impulsionar em um mortal acrobático, movendo-se 15 ft para trás. Este\n        movimento é tão fluido que não provoca ataques de oportunidade (Esse movimento só pode ser usado uma vez por turno).\n        \n    - **Set-Up**\n        \n        Ao acertar uma criatura com um Ataque Desarmado, você lança passos rápidos e provocativos, acumulando momento e hype para o seu próximo golpe. Realize um teste de Performance e anote o valor total. O seu próximo Ataque Desarmado que acertar um alvo dentro do próximo minuto causará um dano extra igual à metade do valor tirado no teste (arredondado para baixo). (Este movimento só pode ser usado uma vez por turno).\n        \n    - **Throwout-Lindy Hop**\n        \n        Ao Acertar uma criatura com um Ataque Desarmado, você aproveita o momentum do impacto para conduzir um aliado a até 5ft de você em um passo de dança rodopiante, lançando-o para fora da zona de perigo. Um aliado voluntário a até 5 ft de você é girado e lançado, movendo-se 20 ft em uma direção à escolha dele. Esse movimento não provoca ataques de oportunidade. Além disso, **Role um de seus Dados de Inspiração Bárdica** (sem gastar o dado da sua reserva de Inspiração). **O aliado adiciona o valor rolado à sua Classe de Armadura** (CA) até o início do próximo turno dele.\n        \n    - **Finalização**\n        \n        Ao Acertar uma criatura com um Ataque Desarmado, você pode ativar esse movimento de dança. (Este movimento de dança só pode ser usado se você já tiver utilizado outro movimento de dança no seu turno). Ao finalizar seu combo, você assume uma pose estática (Baby Freeze, Airchair ou Hollowback) que trava a mente do seu adversário. Escolha uma criatura que você atingiu com um Ataque Desarmado neste turno; ela deve realizar um **Salvamento de Sabedoria.** Em caso de falha, o alvo fica **Atordoado** até o final do próximo turno dele.\n        \n- **Rei da Festa**\n    \n    Você é uma máquina de dança e música (literalmente), sabendo qual música é a certa, na hora certa. Está na hora de encarnar o Rei dessa festa e botar para quebrar.\n    No início do seu turno durante um combate, você pode gastar um uso de Inspiração Bárdica para começar a se concentrar em uma performance (como se estivesse se concentrando em um feitiço). Durante os próximos 10 Minutos, você emana uma Aura de musica e dança de 30 ft. No início de cada um de seus turnos, você pode\n    mudar o estilo da dança e musica, alterando os benefícios para todos os aliados na área: (Os aliados devem ser capazes de ouvir a musica ou ver a coreografia para ganhar os beneficios. Um ser inconciente ou cego e surdo, não ganha os beneficios).\n    \n    - **Discoteca**\n        \n        Você emana uma luz cromática pulsante e espectros ilusórios que aparecem dançando ao seu redor. Todas as criaturas aliadas na área ganham **+2 na CA**. Além disso, cada aliado, uma vez por rodada, quando for alvo de um ataque, pode interpor uma das ilusões: **role 1d6; em um resultado 5 ou 6, o ataque atinge a ilusão e erra o aliado automaticamente.** Este efeito e o bônus na CA é ignorado se o atacante possuir Visão Verdadeira ou conseguir discernir as ilusões.\n        \n    - **Bossa Nova**\n        \n        Um som sereno de violões e saxofones flutua pela área, acompanhado por uma dança contemporânea de movimentos fluidos e relaxantes. O ritmo desacelera a adrenalina do combate, permitindo que o corpo se cure sob a calma da melodia. No início do turno de cada aliado dentro da área, ele pode “curtir a vibe” da música; ao fazer isso, ele recupera 3d6 PV imediatamente. Um ser inconsciente não pode recuperar pontos de vida por meio dessa habilidade.\n        \n    - **Heavy Metal**\n        \n        Uma música agressiva com guitarras distorcidas e bateria frenética ecoa pela área, acompanhada por uma dança de saltos, headbangs e um jogo de corpo\n        vigoroso. A pura energia de um mosh-pit incita uma fúria nos combatentes. Todas as criaturas aliadas dentro da área somam o seu modificador de Carisma nas rolagens de dano de todos os seus ataques (armados, desarmados ou mágicos).\n        \n- Hip-Hop\n        Batidas eletrônicas, teclados vibrantes e o som icônico de discos de vinil sendo riscados (scratching) preenchem o ar, ditando movimentos erráticos, ágeis e imprevisíveis. Todos os aliados na área ganham +20ft de movimento não provocam ataques de oportunidade de inimigos. Além disso, você ganha uma reação especial chamada Som na Caixa, enquanto essa auranestiver ativa. \n        \n        Som Na Caixa: Sempre que um aliado na área sofrer dano, você pode usar sua Reação para “riscar” um disco de vinil invisível no ar. fazer isso preenche o ar com um som poderoso, criando uma onda de choque que amortece o impacto, reduzindo o dano sofrido pelo aliado em (5d6).\n        \n- Musica Tema\n        A música e a coreografia se transformam no tema pessoal de um de seus companheiros, ressoando com a essência e a história dele.\n        Cada aliado pode escolher uma música tema para seu personagem (Você deve saber qual é, antes de ativar essa aura). Ao ativar esta aura, você escolhe qual música tema está tocando. Enquanto o respectivo personagem estiver dentro da área da aura e sua música favorita estiver tocando, ele recebe os seguintes efeitos:\n        \nEssa é a minha música: O aliado ganha um número de Pontos de Vida Temporários igual ao seu nível no início de cada um dos turnos dele. (Esses pontos são perdidos caso a sua musica tema não esteja mais tocando)\n        \nProtagonismo Momentaneo: O aliado adiciona 1d8 a todos os testes de d20 (ataques, salvamentos e testes de atributo) que realizar. Além disso, se ele for reduzido a 0 PV enquanto sua música toca, o aliado cai para 1 PV em vez de 0, e a música termina abruptamente (encerrando a aura).',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 04:59:10','2026-08-27 04:59:10'),(18,4,'Recuperar o Folego/Mente Tatica','class_feature','Guerreiro',1,'Recuperar o Folego. Usando uma Ação Bônus, você pode recuperar 1d10+2 pontos de vida. \nMente Tática. Ao falha em um teste, você pode gastar 1d10 para adicionar no teste, se falhar não gasta o dado.',2,2,'short_rest','{\"column\": \"right\", \"activation\": \"bonus_action\", \"quick_text\": \"1d10+2 de pontos de vida. Ou +1d10 no teste que você falhou.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 08:27:19','2026-08-28 20:03:44'),(19,4,'Surto De Ação','class_feature','Guerreiro',2,'No seu turno, você pode escolher ganhar uma ação padrão adicional, essa ação não pode ser usada para usar a Ação Mágica.',1,1,'short_rest','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Ganha uma Ação Extra, exceto ações mágicas\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 08:29:22','2026-08-28 20:03:37'),(20,4,'Intervenção Divina','class_feature','Clérigo',10,'Lista De Feitiços que são bons para usar com a Intervenção \n - \n -\n -',1,1,'long_rest','{\"column\": \"left\", \"activation\": \"action\", \"quick_text\": \"Conjura qualquer feitiço de até 5º Nível sem gastar slot e usando uma Ação.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 08:31:30','2026-08-31 09:10:29'),(24,8,'Ataque Furtivo','class_feature','Ladino',1,'Você sabe como atacar sutilmente e explorar a distração de um inimigo. Uma vez por turno, você pode causar 1d6 de dano extra a uma criatura atingida em uma jogada de ataque, caso tenha vantagem na jogada e o ataque utilize uma arma de Acuidade ou de Ataque à Distância. O tipo do dano extra é o mesmo da arma.\n\nVocê não precisa de Vantagem na jogada de ataque se pelo menos um de seus aliados estiver a 1,5 metro do alvo, o aliado não estiver com a condição Incapacitado e você não tiver Desvantagem na jogada de ataque.\n\nO dano extra aumenta à medida que você sobe de nível como Ladino, conforme mostrado na coluna Ataque Furtivo da tabela de Características do Ladino.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Uma vez por turno 10d6 de dano extra.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 21:16:14','2026-08-27 21:16:28'),(25,8,'Ação Astuta','class_feature','Ladino',2,'Sua agilidade e raciocínio rápido permitem que você se mova e aja com rapidez. Em seu turno, você pode realizar uma das seguintes ações como Ação Bônus : Disparar , Desengajar ou Esconder-se .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"bonus_action\", \"quick_text\": \"Pode usar com uma ação Bônus: Disparar, Desengajar ou Esconder-se.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 21:18:20','2026-08-27 21:18:20'),(26,8,'Poder Psiônico','class_feature','Ladino - Soulknife',3,'Você abriga uma fonte de energia psíquica dentro de si. Ela é representada pelos seus Dados de Energia Psiônica, que alimentam certos poderes que você possui desta subclasse. A tabela de Dados de Energia da Lâmina da Alma mostra a quantidade desses dados que você possui ao atingir certos níveis de Ladino, bem como o tamanho de cada dado.\n\nDados de Energia Soulknife\nNível de Ladino	Tamanho da matriz	Número\n            3                                D6                  	 4\n            5	                              D8	                     6\n            9	                              D8	                     8\n            11	                              D10	                 8\n            13	                          D10	                10\n            17	                          D12	                 12\nQuaisquer características desta subclasse que utilizem um Dado de Energia Psiônica usam apenas os dados desta subclasse. Alguns de seus poderes consomem um Dado de Energia Psiônica, conforme especificado na descrição do poder, e você não poderá usar um poder se ele exigir o uso de um dado quando todos os seus Dados de Energia Psiônica estiverem esgotados.\n\nVocê recupera um dos seus Dados de Energia Psiônica gastos ao terminar um Descanso Curto e recupera todos eles ao terminar um Descanso Longo .',12,12,'long_rest','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Ao finalizar um Descanso Curto recupera 1 ponto, ao finalizar um descanso longo recupera tudo.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 21:23:28','2026-08-30 02:29:47'),(27,8,'Habilidade Psiônica Aprimorada','class_feature','Ladino - Soulknife',3,'Se você falhar em um teste de habilidade usando uma perícia ou ferramenta na qual você possui proficiência, você pode rolar um Dado de Energia Psiônica e adicionar o número rolado ao teste, potencialmente transformando a falha em sucesso. O dado é gasto apenas se a rolagem for bem-sucedida.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Gastando 1 Ponto Psi, adiciona 1d12 em um teste de habilidade que você tenha proficiência\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-27 21:28:48','2026-08-27 21:28:48'),(28,8,'Sussurros Psíquicos','class_feature','Ladino - Soulknife',3,'Você pode estabelecer comunicação telepática entre si e outros. Como uma ação de Magia , escolha uma ou mais criaturas que você possa ver, até um número de criaturas igual ao seu Bônus de Proficiência , e então role um Dado de Energia Psiônica. Por um número de horas igual ao número rolado, as criaturas escolhidas podem falar telepaticamente com você, e você pode falar telepaticamente com elas. Para enviar ou receber uma mensagem (nenhuma ação necessária), você e a outra criatura devem estar a até 1,6 km de distância um do outro. Uma criatura pode encerrar a conexão telepática a qualquer momento (nenhuma ação necessária).\n    \n    Na primeira vez que usar este poder após cada Descanso Longo , você não gasta o Dado de Energia Psiônica. Todas as outras vezes que usar o poder, você gasta o dado.',1,1,'long_rest','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Usando uma Ação você pode conectar 6 pessoas, durante 1d12 horas você e as outras pessoas poder se comunicar telepaticamente.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 01:15:24','2026-08-29 00:34:44'),(29,8,'Mira Firme','class_feature','Ladino',3,'Como uma Ação Bônus , você concede a si mesmo Vantagem na sua próxima jogada de ataque no turno atual. Você só pode usar essa habilidade se não tiver se movido durante este turno e, após usá-la, sua Velocidade será 0 até o final do turno atual.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"bonus_action\", \"quick_text\": \"Usar uma Ação Bônus para ter Vantagem no próximo ataque no turno atual, só poderá usar essa habilidade se não tiver se movido, após isso seu movimento vira 0.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 01:24:35','2026-08-28 01:24:35'),(30,8,'Proporção 7:3','class_feature','Talento',NULL,'Você treina sua visão para enxergar pontos de ruptura na anatomia dos seus inimigos. Ao focar em uma razão específica de 7 para 3, você é capaz de transformar um golpe comum em um critico devastador. 7:3. Sempre que for realizar um teste de ataque contra uma criatura, você pode gastar um uso desta técnica para buscar o ponto de proporção. Caso o ataque acerte o alvo, role 1d10 imediatamente: Se o resultado no d10 for 3 ou 7, o ponto fraco é atingido e o alvo recebe um dano extra do mesmo tipo da arma, o dano é 3d4 se cair ( 3 ) e 7d4 se cair ( 7 ).\nVocê pode utilizar esta habilidade um número de vezes igual ao seu modificador de Força ou Destreza (Sua Escolha). Você recupera todos os usos após um descanso curto ou longo.',6,6,'short_rest','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Ao acertar o um ataque você pode gastar uma carga e rolar 1d10, caso o resultado seja 3 você adiciona 3d4 de dano extra ao ataque, caso o resultado seja 7 você adiciona 7d4 de dano\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 01:34:04','2026-08-30 02:43:47'),(31,4,'Healer','feat','Origem',1,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Cura 1d8+5 por uso do Kit Medico. E nunca pode rolar 1 no dado de cura.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 20:23:16','2026-08-28 20:23:16'),(32,4,'Resiliente','feat','Talento',4,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"+1 em Con. Ganha proficiência em Salvamentos de Proficiência.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 20:24:47','2026-08-28 20:24:47'),(33,4,'Conjurador De Guerra','feat','Talento',8,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Vantagem em Salvamentos de Concentração. Ataque de oportunidade pode conjurar feitiço\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 20:26:10','2026-08-28 20:26:33'),(34,4,'Visão No Escuro Aumentada','species_trait','Elfa (Drow)',1,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"120ft de visão no escuro\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 20:42:57','2026-08-28 20:42:57'),(35,4,'Transe','species_trait','Elfa (Drow)',1,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Não pode ser posta para dormir, e o descanso longo dura 4h\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 20:43:30','2026-08-28 20:43:30'),(36,4,'Fada','species_trait','Elfa (Drow)',1,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Possui vantagem contra Charmed\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 20:43:51','2026-08-28 20:43:51'),(40,4,'Escudos','armor_training',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 21:18:50','2026-08-28 21:18:50'),(41,4,'Armaduras Leves','armor_training',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 21:18:52','2026-08-28 21:18:52'),(42,4,'Armaduras Médias','armor_training',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 21:18:52','2026-08-28 21:18:52'),(43,4,'Armas Simples','weapon_training',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 21:18:55','2026-08-28 21:18:55'),(44,4,'Armas Marciais','weapon_training',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 21:18:56','2026-08-28 21:18:56'),(46,4,'Comum','language',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 21:19:48','2026-08-28 21:19:48'),(47,4,'Élfico','language',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 21:19:49','2026-08-28 21:19:49'),(48,4,'Gnômico','language',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-28 21:19:51','2026-08-28 21:19:51'),(49,4,'Kit de Herbalismo','tool_proficiency',NULL,15,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": \"wisdom\", \"recovery_custom\": null}','2026-08-28 21:29:47','2026-08-28 21:29:47'),(50,8,'Armaduras Leves','armor_training',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 00:32:31','2026-08-29 00:32:31'),(51,8,'Armas Simples','weapon_training',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 00:32:32','2026-08-29 00:32:32'),(52,8,'Ferramentas de Ladrão','tool_proficiency',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": \"dexterity\", \"recovery_custom\": null}','2026-08-29 00:32:35','2026-08-29 00:32:35'),(53,8,'Comum','language',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 00:32:56','2026-08-29 00:32:56'),(54,8,'Infernal','language',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 00:32:57','2026-08-29 00:32:57'),(55,8,'Abissal','language',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 00:32:59','2026-08-29 00:32:59'),(56,8,'Proporção 7:3','feat','Ladino - Talento',4,'Você treina sua visão para enxergar pontos de ruptura na anatomia dos seus inimigos. Ao focar em uma razão específica de 7 para 3, você é capaz de transformar um golpe comum em um critico devastador. 7:3. Sempre que for realizar um teste de ataque contra uma criatura, você pode gastar um uso desta técnica para buscar o ponto de proporção. Caso o ataque acerte o alvo, role 1d10 imediatamente: Se o resultado no d10 for 3 ou 7, o ponto fraco é atingido e o alvo recebe um dano extra do mesmo tipo da arma, o dano é 3d4 se cair ( 3 ) e 7d4 se cair ( 7 ).\nVocê pode utilizar esta habilidade um número de vezes igual ao seu modificador de Força ou Destreza (Sua Escolha). Você recupera todos os usos após um descanso curto ou longo.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-29 22:27:48','2026-08-30 02:22:40'),(57,12,'Armas Simples','weapon_training',NULL,12,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 22:38:14','2026-08-29 22:38:14'),(58,12,'Armas Marciais com Leve','weapon_training',NULL,12,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 22:38:35','2026-08-29 22:38:35'),(59,12,'Kit de Herbalismo','tool_proficiency',NULL,12,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": \"wisdom\", \"recovery_custom\": null}','2026-08-29 23:17:14','2026-08-29 23:17:14'),(60,12,'Comum','language',NULL,12,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 23:17:51','2026-08-29 23:17:51'),(61,12,'Abissal','language',NULL,12,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 23:17:54','2026-08-29 23:17:54'),(62,12,'Celestial','language',NULL,12,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 23:17:56','2026-08-29 23:17:56'),(63,12,'Gith','language',NULL,12,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-29 23:18:11','2026-08-29 23:18:11'),(64,12,'Garras de Gato','species_trait','Tabaxi',NULL,'Você pode usar suas garras para desferir golpes desarmados. Ao acertá-las, o golpe causa 1d6 + seu modificador de Força de dano cortante, em vez do dano contundente normal de um golpe desarmado.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Golpes desarmados podem causar 1d6+FOR de dano cortante.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:11:52','2026-08-30 00:11:52'),(65,12,'Talento do Gato','species_trait','Tabaxi',NULL,'Você é proficiente nas perícias Percepção e Furtividade .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:12:29','2026-08-30 00:12:29'),(66,12,'Artes Marciais','class_feature','Monge',1,'Sua prática de artes marciais lhe proporciona domínio de estilos de combate que utilizam seu Ataque Desarmado e suas armas de Monge, que são as seguintes:\n\nArmas de combate corpo a corpo simples\nArmas marciais de combate corpo a corpo que possuem a propriedade Leve\nVocê recebe os seguintes benefícios enquanto estiver desarmado ou empunhando apenas armas de Monge e não estiver usando armadura ou escudo.\n\nAtaque Desarmado Bônus. Você pode realizar um Ataque Desarmado como uma Ação Bônus .\n\nDado de Artes Marciais. Você pode rolar 1d6 em vez do dano normal do seu Ataque Desarmado ou das suas armas de Monge. Este dado muda conforme você sobe de nível como Monge, conforme mostrado na coluna Artes Marciais da tabela de Características do Monge.\n\nAtaques Destros. Você pode usar seu modificador de Destreza em vez do seu modificador de Força para as jogadas de ataque e dano de seus Ataques Desarmados e armas de Monge. Além disso, quando você usa a opção Agarrar ou Empurrar do seu Ataque Desarmado , você pode usar seu modificador de Destreza em vez do seu modificador de Força para determinar a CD do teste de resistência.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:21:43','2026-08-30 00:22:28'),(67,12,'Visão no Escuro','species_trait','Tabaxi',NULL,'Você consegue enxergar na penumbra a até 18 metros de distância como se fosse luz forte, e na escuridão como se fosse luz fraca. Você distingue cores nessa escuridão apenas como tons de cinza.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"60ft de visão no escuro.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:39:47','2026-08-30 00:39:47'),(68,12,'Agilidade Felina','species_trait','Tabaxi',NULL,'Seus reflexos e agilidade permitem que você se mova com uma explosão de velocidade. Ao se mover no seu turno em combate, você pode dobrar sua velocidade até o final do turno. Depois de usar esta característica, você não poderá usá-la novamente até se mover 0 pés em um dos seus turnos.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Por um turno você dobra sua velocidade até o final. Só poderá usar de novo se não se mover no seu turno.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:42:01','2026-08-30 00:42:01'),(69,12,'Conto do Velho Gato','species_trait','Tabaxi',NULL,'A sabedoria de um andarilho experiente pode mudar o destino de seus companheiros. 3 vezes por dia, você pode usar sua reação para permitir que uma criatura que você possa ver re-role um teste de d20 que ela acabou de realizar. A criatura deve ser capaz de te ouvir para receber a sua sabedoria.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Caso um aliado que você consiga ver falhe em um teste de d20, você pode usar reação para que mesmo possa re-rolar o d20.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:44:49','2026-08-30 00:44:49'),(70,12,'Iniciado em Magia','feat','Background',1,'Você obtém os seguintes benefícios.\n\nDois truques. Você aprende dois truques à sua escolha da lista de magias de Clérigo , Druida ou Mago . Inteligência, Sabedoria ou Carisma é sua habilidade de conjuração para as magias deste talento (escolha ao selecionar este talento).\n\nMagia de Nível 1. Escolha uma magia de nível 1 da mesma lista que você selecionou para os truques deste talento. Você sempre terá essa magia preparada. Você pode conjurá-la uma vez sem usar um espaço de magia e recupera a capacidade de conjurá-la dessa forma ao terminar um Descanso Longo . Você também pode conjurar a magia usando quaisquer espaços de magia que possuir.\n\nTroca de Magia. Sempre que você subir de nível, poderá substituir uma das magias escolhidas para este talento por uma magia diferente do mesmo nível, selecionada da lista de magias escolhida.\n\nRepetível. Você pode escolher este talento mais de uma vez, mas deve selecionar uma lista de magias diferente a cada vez.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:51:40','2026-08-30 00:51:40'),(71,12,'Telecinético','feat','Talento Nível 8',8,'Telecinese Menor\n        Você aprende a magia Mão Mágica . Você pode conjurá-la sem componentes Verbais ou Somáticos, pode tornar a mão espectral invisível , e seu alcance e a distância que ela pode atingir de você aumentam em 9 metros quando você a conjura. A habilidade de conjuração da magia é a habilidade aumentada por este talento.\n        \nEmpurrão Telecinético\n        Como uma Ação Bônus, você pode empurrar telecineticamente uma criatura que você possa ver a até 9 metros de você. Ao fazer isso, o alvo deve ser bem-sucedido em um teste de resistência de Força (CD 8 mais o modificador de habilidade do valor aumentado por este talento e seu Bônus de Proficiência) ou será movido 1,5 metro em sua direção ou para longe de você.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:56:54','2026-08-30 00:56:54'),(72,12,'Mergulhador','feat','Talento Nível 12',12,'Você passou por um treinamento subaquático extensivo. Você obtém os seguintes benefícios:\n    - Aumente sua pontuação de Constituição em 1, até um máximo de 20.\n    - Você ganha uma velocidade de nado igual ao dobro do seu valor de Constituição (arredondado para o 1,5 metro mais próximo). Se você já tiver uma velocidade de nado, ela aumenta em 3 metros.\n    - Você triplica seu modificador de Constituição ao calcular por quanto tempo consegue prender a respiração.\n    -  Você ganha resistência a dano de frio.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 00:59:37','2026-08-30 00:59:37'),(74,12,'Foco do Monge','class_feature','Monge',2,'Seu foco e treinamento marcial permitem que você canalize uma fonte extraordinária de energia dentro de si. Essa energia é representada por Pontos de Foco. Seu nível de Monge determina a quantidade de pontos que você possui, conforme mostrado na coluna Pontos de Foco da tabela de Características do Monge.\n\nVocê pode usar esses pontos para aprimorar ou potencializar certas habilidades de Monge. Você começa conhecendo três dessas habilidades: Rajada de Golpes, Defesa Paciente e Passo do Vento, cada uma detalhada abaixo.\n\nAo gastar um Ponto de Foco, ele ficará indisponível até que você termine um Descanso Curto ou Longo , ao final do qual você recupera todos os pontos gastos.\n\nAlgumas habilidades que usam Pontos de Foco exigem que seu alvo faça um teste de resistência. A CD do teste é igual a 8 mais seu modificador de Sabedoria e seu Bônus de Proficiência .\n\n- Rajada de Golpes\n    \n    Você pode gastar 1 Ponto de Foco para realizar dois Ataques Desarmados como uma Ação Bônus .\n    \n- Defesa Paciente\n    \n    Você pode realizar a ação Desengajar como uma Ação Bônus . Alternativamente, você pode gastar 1 Ponto de Foco para realizar as ações Desengajar e Esquivar como uma Ação Bônus .\n    \n- Passo do Vento\n    \n    Você pode realizar a ação de Disparar como uma Ação Bônus . Alternativamente, você pode gastar 1 Ponto de Foco para realizar as ações de Desengajar e Disparar como uma Ação Bônus , e sua distância de salto será dobrada no turno.',12,12,'short_rest','{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 01:26:22','2026-08-30 01:26:22'),(76,12,'Metabolismo Estranho','class_feature','Monge',2,'Ao rolar Iniciativa , você pode recuperar todos os Pontos de Foco gastos. Ao fazer isso, role seu dado de Artes Marciais e recupere uma quantidade de Pontos de Vida igual ao seu nível de Monge mais o número rolado.\n    \n    Depois de usar esse recurso, você não poderá usá-lo novamente até terminar um Descanso Longo .',1,1,'long_rest','{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Uma vez por Descanso Longo, ao rolar iniciativa você recupera todos os pontos de foco, e recupera o seu dado marcial em pontos de vida.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 01:32:52','2026-08-30 02:02:46'),(77,12,'Mão do Mal','class_feature','Monge - SubClasse',3,'Uma vez por turno, quando você atinge uma criatura com um Ataque Desarmado e causa dano, você pode gastar 1 Ponto de Foco para causar dano Necrótico extra igual a uma jogada do seu dado de Artes Marciais mais seu modificador de Sabedoria.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"special\", \"quick_text\": \"Uma vez por tuno ao acertar um ataque desarmado e causar dano, gastando 1 ponto de foco você causa dano necrótico extra igual ao seu dado marcial mais modificador de Sabedoria.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 01:39:55','2026-08-30 01:39:55'),(78,12,'Mão da Cura','class_feature','Monge - SubClasse',3,'Como uma ação de Magia , você pode gastar 1 Ponto de Foco para tocar uma criatura e restaurar uma quantidade de Pontos de Vida igual a uma jogada do seu dado de Artes Marciais mais o seu modificador de Sabedoria. Ao usar sua Rajada de Golpes, você pode substituir um dos Ataques Desarmados por um uso desta habilidade sem gastar um Ponto de Foco para a cura.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"action\", \"quick_text\": \"Com uma Ação e gastando 1 ponto de foco, você tocar uma criatura e restaurar pontos de vida igual ao seu dado marcial mais seu modificador de sabedoria.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 01:43:49','2026-08-30 01:43:49'),(79,12,'Implementos de Misericórdia','class_feature','Monge - SubClasse',3,'Você ganha proficiência nas habilidades de Intuição e Medicina e proficiência no Kit de Herbalismo .',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Proficiência em Medicina, Intuição e em Kit de Herbalismo\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 01:45:27','2026-08-30 01:45:27'),(80,12,'Desviar Ataques','class_feature','Monge',2,'Quando uma jogada de ataque atinge você e o dano inclui dano de Concussão, Perfuração ou Corte, você pode realizar uma Reação para reduzir o dano total do ataque contra você. A redução é igual a 1d10 mais seu modificador de Destreza e nível de Monge.\n    \n    Se você reduzir o dano a 0, poderá gastar 1 Ponto de Foco para redirecionar parte da força do ataque. Se fizer isso, escolha uma criatura que você possa ver a até 1,5 metro de você, se o ataque for corpo a corpo, ou uma criatura que você possa ver a até 18 metros de você, mas que não esteja atrás de Cobertura Total , se o ataque for à distância. Essa criatura deve ser bem-sucedida em um teste de resistência de Destreza ou sofrer dano igual a duas jogadas do seu dado de Artes Marciais mais o seu modificador de Destreza. O dano é do mesmo tipo causado pelo ataque.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"reaction\", \"quick_text\": \"Qualquer dano Perfurante, Cortante ou impacto, você pode usar uma reação para reduzir o dano em 17+1d10. Caso o dano seja reduzido a 0 você pode gastar 1 ponto para redireciona-lo.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 01:49:33','2026-08-30 01:49:33'),(81,9,'Druídico','class_feature','Druida',1,'Você domina Druídico, o idioma secreto dos Druidas.\nAo aprender esse idioma antigo, você também adquiriu a habilidade mágica de se comunicar com animais; você sempre tem a magia Falar com Animais preparada.\n\nVocê pode usar Druídico para deixar mensagens ocultas. Você e outros que conhecem Druídico identificam automaticamente tal mensagem. Outros podem perceber a presença da mensagem com um teste de Inteligência (Investigação) CD 15, mas não podem decifrá-la sem magia.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Aprende Druídico, a linguagem secreta dos Druidas\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 01:58:01','2026-08-30 02:36:41'),(82,12,'Queda Lenta','class_feature','Monge',4,'Você pode realizar uma Reação ao cair para reduzir qualquer dano sofrido na queda em uma quantidade igual a cinco vezes seu nível de Monge.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"reaction\", \"quick_text\": \"Ao cair de uma grande altura você pode gastar reação para reduzir o dano de queda, a redução e igual a cinco vezes o seu nível de monge(Atual: 60)\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 01:59:35','2026-08-30 01:59:35'),(83,12,'Golpe Estonteante','class_feature','Monge',5,'Uma vez por turno, quando você acertar uma criatura com uma arma de Monge ou um Ataque Desarmado , você pode gastar 1 Ponto de Foco para tentar um golpe atordoante. O alvo deve fazer um teste de resistência de Constituição. Se falhar, o alvo fica Atordoado até o início do seu próximo turno. Se for bem-sucedido, a Velocidade do alvo é reduzida à metade até o início do seu próximo turno, e a próxima jogada de ataque feita contra o alvo antes disso terá Vantagem .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Ao acertar uma criatura com um ataque desarmado você pode gastar 1 ponto de foco para tentar atordoar o alvo, o mesmo deve fazer um teste de constituição (CD: 17).\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:02:13','2026-08-30 02:02:13'),(84,12,'Toque do Médico','class_feature','Monge - SubClasse',6,'Suas habilidades de Mão do Dano e Mão da Cura melhoram, conforme detalhado abaixo.\n\nMão da Perdição. Quando você usa Mão da Perdição em uma criatura, você também pode infligir a ela a condição Envenenada até o final do seu próximo turno.\n\nMão da Cura. Ao usar Mão da Cura, você também pode remover uma das seguintes condições da criatura que você cura:',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Quando usar mão do mal o alvo fica envenenado. Quando usar a mão da cura você as seguintes condições: Cegueira, Surdez, Paralisia, Envenenamento ou Atordoamento.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:04:42','2026-08-30 02:06:10'),(85,12,'Evasão','class_feature','Monge',7,'Quando você é afetado por um efeito que permite fazer um teste de resistência de Destreza para sofrer apenas metade do dano, você não sofre dano algum se for bem-sucedido no teste e sofre apenas metade do dano se falhar.\n\nVocê não se beneficia deste recurso se estiver com a condição de Incapacitado .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:07:36','2026-08-30 02:07:36'),(86,12,'Foco Aguçado','class_feature','Monge',10,'Suas habilidades Rajada de Golpes, Defesa Paciente e Passo do Vento recebem os seguintes benefícios.\n\nRajada de Golpes. Você pode gastar 1 Ponto de Foco para usar Rajada de Golpes e realizar três Ataques Desarmados em vez de dois.\n\nDefesa Paciente. Ao gastar um Ponto de Foco para usar Defesa Paciente, você ganha um número de Pontos de Vida Temporários igual a duas rolagens do seu dado de Artes Marciais.\n\nPasso do Vento. Quando você gasta um Ponto de Foco para usar Passo do Vento, você pode escolher uma criatura voluntária a até 1,5 metro de você que seja Grande ou menor. Você move a criatura com você até o final do seu turno. O movimento da criatura não provoca Ataques de Oportunidade .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:08:31','2026-08-30 02:08:31'),(87,12,'Autorresturação','class_feature',NULL,10,'Através da pura força de vontade, você pode remover uma das seguintes condições de si mesmo ao final de cada um dos seus turnos: Enfeitiçado , Assustado ou Envenenado .\n\nAlém disso, ficar sem comer e beber não causa níveis de exaustão .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:08:51','2026-08-30 02:09:25'),(88,12,'Rajada de Cura e Dano','class_feature','Monge - SubClasse',11,'Ao usar Rajada de Golpes, você pode substituir cada um dos Ataques Desarmados por uma utilização de Mão da Cura sem gastar Pontos de Foco para a cura.\n\nAlém disso, quando você realiza um Ataque Desarmado com Rajada de Golpes e causa dano, você pode usar Mão da Dor com esse ataque sem gastar um Ponto de Foco para Mão da Dor. Você ainda só pode usar Mão da Dor uma vez por turno.\n\nVocê pode usar esses benefícios um número total de vezes igual ao seu modificador de Sabedoria (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um Descanso Longo .',5,5,'long_rest','{\"column\": \"right\", \"activation\": \"bonus_action\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:11:36','2026-08-30 02:11:36'),(89,12,'Ventos da Agilidade','class_feature','Medalhão do Andarilho',NULL,'Enquanto estiver sintonizado com este medalhão, você pode gastar 1 carga como uma ação bônus para ativar os Ventos da Agilidade. Por 1 minuto, você recebe os seguintes benefícios:\n\n- Vantagem em todos os testes de Destreza.\n- Vantagem em salvamentos de Destreza.\n- Seu deslocamento aumenta em (15ft)\n\nO medalhão possui 3 cargas, e recupera todas as cargas ao amanhecer.',3,3,'dawn','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:12:54','2026-08-30 02:12:54'),(90,12,'Conto do Velho Gato','class_feature','Tabaxi',NULL,'A sabedoria de um andarilho experiente pode mudar o destino de seus companheiros. 3 vezes por dia, você pode usar sua reação para permitir que uma criatura que você possa ver re-role um teste de d20 que ela acabou de realizar. A criatura deve ser capaz de te ouvir para receber a sua sabedoria.',3,3,'day','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:14:32','2026-08-30 02:14:32'),(91,9,'Ordem Primal','class_feature','Druida',1,'Você se dedicou a uma das seguintes funções sagradas à sua escolha.\n\nProtetor: Treinado para a batalha, você adquire proficiência com armas Marciais e treinamento com armadura Média.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Ganham proficiência em armas Marciais e armadura Medias\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:14:54','2026-08-30 02:36:47'),(92,8,'Visão no Escuro','species_trait','Tiefling',NULL,'Graças à sua herança infernal, você tem uma visão superior em condições de pouca luz e penumbra. Você consegue enxergar em ambientes com pouca luz a até 18 metros de distância como se fosse luz forte, e na escuridão como se fosse penumbra. Você não consegue discernir cores na escuridão, apenas tons de cinza.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:19:23','2026-08-30 02:19:23'),(93,8,'Resistência Infernal','species_trait','Tiefling',NULL,'Você tem resistência a dano de fogo.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:19:49','2026-08-30 02:19:49'),(94,8,'Fogo do Inferno','species_trait','Tiefling',NULL,'Você conhece o truque de taumaturgia . Ao atingir o 3º nível, você pode conjurar a magia Mãos Flamejantes uma vez por dia como uma magia de 2º nível; você precisa terminar um descanso longo para conjurar a magia novamente usando esta característica. Ao atingir o 5º nível, você também pode conjurar a magia Escuridão ; você precisa terminar um descanso longo para conjurar a magia novamente usando esta característica. Carisma é sua habilidade de conjuração para essas magias.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:20:33','2026-08-30 02:20:33'),(95,9,'Companheiro Selvagem','class_feature','Druida',2,'Você pode invocar um espírito da natureza que assume a forma de um animal para auxiliá-lo. Como uma ação Usar Magia, você pode gastar um espaço de magia ou um uso de Forma Selvagem para conjurar a magia Conjurar Familiar sem componentes Materiais.\n\nAo conjurar a magia deste modo, o familiar é uma criatura Feérica e desaparece ao completar um Descanso Longo.',1,1,'long_rest','{\"column\": \"left\", \"activation\": \"action\", \"quick_text\": \"Pode usar Conjurar Familiar sem usar componente Materiais\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:21:42','2026-08-30 06:29:02'),(96,8,'Alerta','feat','Origem',1,'Proficiência em Iniciativa. Ao rolar Iniciativa, você pode adicionar seu Bônus de Proficiência ao resultado.\n    \nTroca de Iniciativa. Imediatamente após rolar Iniciativa, você pode trocar sua Iniciativa pela Iniciativa de um aliado disposto no mesmo combate. Você não pode fazer essa troca se você ou o aliado estiver na condição Incapacitado .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:22:25','2026-08-30 02:22:34'),(97,8,'Chamas em Flagelo','feat','Talento',10,'Você aprende a invocar o fogo do inferno para servir aos seus comandos. Você ganha os seguintes benefícios:\n    \n    - Aumente sua Inteligência ou Carisma em 1, até um máximo de 20.\n    - Quando você rola dano de fogo para uma magia que você conjura, você pode rolar novamente qualquer resultado de 1 nos dados de dano de fogo, mas você deve usar o novo resultado, mesmo que seja outro 1.\n    - Sempre que conjurar uma magia que cause dano de fogo, você pode fazer com que chamas o envolvam até o final do seu próximo turno. As chamas não causam dano a você nem aos seus pertences e emitem luz brilhante por até 9 metros e luz fraca por mais 9 metros. Enquanto as chamas estiverem presentes, qualquer criatura a até 1,5 metro de você que o atingir com um ataque corpo a corpo sofre 1d4 de dano de fogo.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:23:22','2026-08-30 02:26:38'),(98,8,'Constituição Infernal','feat','Talento',12,'O sangue demoníaco corre forte em suas veias, desbloqueando uma resiliência semelhante à possuída por alguns demônios. Você obtém os seguintes benefícios:\n    \n    - Aumente sua pontuação de Constituição em 1, até um máximo de 20.\n    - Você possui resistência a danos causados por frio e veneno.\n    - Você tem vantagem em testes de resistência contra envenenamento.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:24:53','2026-08-30 02:26:44'),(99,8,'Herói de Ferro','feat','Talento',16,'Aumento de Atributo. Aumente sua Força ou Destreza em 1, até um máximo de 20.\n    \nDeterminação do Oprimido. Quando você for atacado por uma criatura com um ND (Nível de Desafio) maior que o seu nível, você recebe um bônus de +2 na sua Classe de Armadura para esse ataque.\n    \nGolpe Vingativo. Você tem vantagem nas jogadas de ataque contra qualquer criatura que tenha reduzido os Pontos de Vida de um de seus aliados a 0 desde o final do seu último turno.\n    \n Intervenção Heroica. Quando um inimigo que você pode ver realiza uma Ação Lendária, você pode usar uma Reação para intervir, impedindo que a Ação Lendária aconteça. Você pode usar essa Reação um número de vezes igual ao seu Bônus de Proficiência e recupera todos os usos gastos ao terminar um Descanso Curto ou Longo.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:26:15','2026-08-30 02:26:49'),(100,9,'Forma Selvagem','class_feature','Druida',2,'O poder da natureza permite que você assuma a forma de um animal. Como uma Ação Bônus, você multimorfa para uma forma Animal que você aprendeu com esta característica (veja “Formas Conhecidas”, abaixo). Você fica nessa forma por um número de horas igual à metade do seu nível de Druida, até usar Forma Selvagem novamente, ter a condição Incapacitado ou morrer. Você também pode sair da forma antes como uma Ação Bônus.\n\nQuantidade de Usos. Você pode usar Forma Selvagem duas vezes. Você recupera um uso gasto ao completar um Descanso Curto e restaura todos os usos gastos ao completar um Descanso Longo. Você adquire usos adicionais ao atingir determinados níveis de Druida, conforme mostrado na coluna Forma Selvagem da tabela Características de Druida.\n\nFormas Conhecidas. Você conhece quatro formas Animais com esta característica, escolhidas entre os blocos de estatísticas de Fera com um Nível de Desafio máximo de 1/4 e que não possuem um Deslocamento de Voo (veja o apêndice B para opções de bloco de estatísticas). Aranha, Cavalo de Montaria, Lobo e Rato são recomendadas. Sempre que completar um Descanso Longo, você pode substituir uma de suas formas conhecidas por outra forma permitida. Ao atingir certos níveis de Druida, o número de formas conhecidas e o Nível de Desafio máximo dessas formas aumenta, conforme mostrado na tabela Formas de Feras. Além disso, a partir do nível 8, você pode adotar uma forma com Deslocamento de Voo. Ao escolher formas conhecidas, você pode procurar no Livro dos Monstros ou em outro lugar por Feras elegíveis se o Mestre permitir.\n\nRegras Enquanto Multimorfado. Enquanto estiver em uma forma, você mantém sua personalidade, memórias e capacidade de falar, e as seguintes regras se aplicam:\n\nPontos de Vida Temporários. Ao assumir uma Forma Selvagem, você adquire um número de Pontos de Vida Temporários igual ao seu nível de Druida.\n\nEstatísticas de Jogo. Suas estatísticas de jogo são substituídas pelo bloco de estatísticas da Fera, mas você mantém seu tipo de criatura, Pontos de Vida, Dados de Vida, valores de Inteligência, Sabedoria e Carisma, características de classe, idiomas e talentos. Você também mantém suas proficiências em perícia e salvaguarda e usa seu Bônus de Proficiência para elas, além de adquirir as proficiências da criatura. Se uma perícia ou modificador de salvaguarda no bloco de estatísticas da Fera for maior que o seu, use o do bloco de estatísticas.\n\nSem Conjuração. Você não pode conjurar magias, mas a multimorfia não quebra sua Concentração ou interfere em uma magia que você já conjurou. \n\nObjetos. Sua capacidade de manipular objetos é determinada pelos membros da forma, e não pelos seus. Além disso, você escolhe se seu equipamento cai em seu espaço, se funde em sua nova forma ou se é usado por ela. O equipamento vestido funciona normalmente, mas o Mestre decide se é compatível para a nova forma usar um equipamento com base no tamanho e forma da criatura. Seu equipamento não muda de tamanho ou forma para corresponder à nova forma, e qualquer equipamento que a nova forma não possa usar deve cair no chão ou se fundir com a forma. O equipamento que se funde com a forma não tem efeito enquanto você estiver nessa forma.\n\nAo escolher a subclasse da Lua, você adiciona esses efeitos em sua Forma Selvagem:\n\nNível de Desafio. O Nível de Desafio máximo para a forma é igual ao seu nível de Druida dividido por 3 (arredondado para baixo).\n\nClasse de Armadura. Até sair da forma, sua CA passa a ser 13 + seu modificador de Sabedoria, se esse valor for maior que a CA da Fera.\n\nPontos de Vida Temporários. Você adquire um número de Pontos de Vida Temporários igual a três vezes o seu nível de Druida.\n\nNo nível 6 você adiciona essas habilidades a Forma Selvagem:\n\nRadiância Lunar. Cada um de seus ataques na Forma Selvagem pode causar seu tipo de dano normal ou dano Radiante. Você escolhe cada vez que acerta com esses ataques.\n\nVigor Aumentado. Você pode adicionar seu modificador de Sabedoria às suas salvaguardas de Constituição.\n\nNo nível 14 sua Radiância Lunar recebe um aprimoramento:\n\nRadiância Lunar Aprimorada. Uma vez por turno, você pode causar 2d10 pontos de dano Radiante adicional a um alvo que você acerta com o ataque da Forma Selvagem.',4,4,'long_rest','{\"column\": \"right\", \"activation\": \"bonus_action\", \"quick_text\": \"Muda de forma para a de um animal, Formas mais complexas gastam 2 usos.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:27:59','2026-08-30 06:28:38'),(101,8,'Dádiva da Habilidade','feat','Dádiva Divina',19,'Você obtém os seguintes benefícios.\n\nAumento de Atributo. Aumente um atributo à sua escolha em 1 ponto, até um máximo de 30.\n\nVersátil. Você adquire proficiência em todas as habilidades.\n\nEspecialização. Escolha uma habilidade na qual você não possui especialização . Você adquire especialização nessa habilidade.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:29:03','2026-08-30 02:29:03'),(102,8,'Golpe Astuto','class_feature','Ladino',5,'Você desenvolveu maneiras astutas de usar seu Ataque Furtivo. Quando você causa dano com um Ataque Furtivo, pode adicionar um dos seguintes efeitos de Golpe Astuto. Cada efeito tem um custo em dados, que é o número de dados de dano do Ataque Furtivo que você deve abrir mão para adicionar o efeito. Você remove o dado antes de rolar, e o efeito ocorre imediatamente após o dano do ataque ser causado. Por exemplo, se você adicionar o efeito Veneno, remova 1d6 do dano do Ataque Furtivo antes de rolar.\n\nSe o efeito de Golpe Astuto exigir um teste de resistência, a CD será igual a 8 mais seu modificador de Destreza e Bônus de Proficiência .\n\nVeneno (Custo: 1d6). Você adiciona uma toxina ao seu ataque, forçando o alvo a fazer um teste de resistência de Constituição. Em caso de falha, o alvo fica Envenenado por 1 minuto. Ao final de cada um de seus turnos, o alvo Envenenado repete o teste, encerrando o efeito sobre si mesmo em caso de sucesso.\n\nPara usar esse efeito, você precisa ter um kit de envenenamento consigo.\n\nDerrubada (Custo: 1d6). Se o alvo for Grande ou menor, ele deve ser bem-sucedido em um teste de resistência de Destreza ou ficará caído .\n\nRetirada (Custo: 1d6). Imediatamente após o ataque, você se move até metade do seu Deslocamento sem provocar Ataques de Oportunidade .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Veneno (Custo: 1d6)(Constituição)(Precisa de Kit de Veneno); Derrubada (Custo: 1d6)(Destreza); Retirada (Custo: 1d6); CD: 20\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:32:16','2026-08-30 02:48:49'),(103,8,'Esquiva Sobrenatural','class_feature','Ladino',5,'Quando um atacante que você pode ver acerta você com uma jogada de ataque, você pode usar uma Reação para reduzir o dano do ataque pela metade (arredondando para baixo).',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"reaction\", \"quick_text\": \"Ao ser acertado por um ataque que você pode ver, você pode gastar sua reação para reduzir o dano pela metade (Arredondando para Baixo).\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:35:27','2026-08-30 02:35:27'),(104,8,'Evasão','class_feature','Ladino',6,'Você pode se esquivar agilmente de certos perigos. Quando você é afetado por um efeito que permite fazer um teste de resistência de Destreza para sofrer apenas metade do dano, você não sofre dano algum se for bem-sucedido no teste e sofre apenas metade do dano se falhar. Você não pode usar esta habilidade se estiver incapacitado .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Caso seja submetido a um teste de salvaguarda de destreza que cause dano, em caso de falha no teste você recebe apenas metade do dano, em caso de sucesso não recebe dano.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:37:26','2026-08-30 02:37:26'),(105,8,'Talento Confiável','class_feature','Ladino',7,'Sempre que você fizer um teste de habilidade que utilize uma de suas proficiências em perícias ou ferramentas, você pode considerar um resultado de 9 ou menos em um d20 como 10.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Qualquer teste de habilidade que você tenha proficiência, qualquer resultado igual a 9 ou menor será tratado com um 10.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:39:45','2026-08-30 02:39:45'),(106,8,'Lâminas da Alma','class_feature','Ladino - SubClasse',9,'Agora você pode usar os seguintes poderes com suas Lâminas Psíquicas.\n\nAtaques Teleguiados. Se você fizer uma jogada de ataque com sua Lâmina Psíquica e errar o alvo, você pode rolar um Dado de Energia Psiônica e adicionar o número rolado à jogada de ataque. Se isso fizer com que o ataque acerte, o dado é gasto.\n\nTeletransporte Psíquico. Como uma Ação Bônus , você manifesta uma Lâmina Psíquica , gasta um Dado de Energia Psiônica e rola o resultado, arremessando a lâmina em um espaço desocupado que você possa ver a uma distância de até 10 vezes o número rolado. Você então se teletransporta para esse espaço e a lâmina desaparece.',NULL,NULL,NULL,'{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Ataques Teleguiados e Teletransporte Psíquico\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:41:19','2026-08-30 02:41:19'),(107,9,'Ressurgimento Selvagem','class_feature','Druida',5,'Uma vez em cada um de seus turnos, se você não tiver mais usos de Forma Selvagem, pode recuperar um uso gastando um espaço de magia (nenhuma ação é necessária).\n\nAlém disso, você pode gastar um uso de Forma Selvagem (nenhuma ação é necessária) para recuperar um espaço de magia de 1º círculo, mas não pode fazê-lo novamente até completar um Descanso Longo.',1,1,'long_rest','{\"column\": \"right\", \"activation\": \"special\", \"quick_text\": \"Pode recuperar um uso da Forma Selvagem gastando um slot de magia.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:42:55','2026-08-30 06:28:48'),(108,8,'Véu Psíquico','class_feature','Ladino - SubClasse',13,'Você pode tecer um véu de estática psíquica para se mascarar. Como uma ação mágica , você ganha , você adquire a Invisibilidade. por 1 hora ou até dissipar esse efeito (nenhuma ação é necessária). Essa invisibilidade termina imediatamente após você causar dano a uma criatura ou forçá-la a fazer um teste de resistência.\n\nApós usar essa habilidade, você não poderá usá-la novamente até concluir um Descanso Longo, a menos que gaste um Dado de Energia Psiônica (sem necessidade de ação) para restaurar seu uso.',1,1,'long_rest','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Uma vez por Descaço Longo (ou caso gaste 1 Ponto Psíquico), usando uma ação mágica você pode ficar invisível por 1 minuto.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:43:28','2026-08-30 02:43:28'),(109,8,'Golpes Traiçoeiros','class_feature','Ladino',14,'Você praticou novas maneiras de usar seu Ataque Furtivo de forma ardilosa. Os seguintes efeitos agora estão entre suas opções de Golpe Astuto.\n\nAtordoar (Custo: 2d6). O alvo deve ser bem-sucedido em um teste de resistência de Constituição ou, em seu próximo turno, poderá fazer apenas uma das seguintes ações: mover-se, realizar uma ação ou uma Ação Bônus .\n\nNocaute (Custo: 6d6). O alvo deve ser bem-sucedido em um teste de resistência de Constituição, ou ficará Inconsciente por 1 minuto ou até sofrer qualquer dano. O alvo Inconsciente repete o teste no final de cada um de seus turnos, encerrando o efeito sobre si mesmo em caso de sucesso.\n\nObscurecer (Custo: 3d6). O alvo deve ser bem-sucedido em um teste de resistência de Destreza, ou ficará cego até o final do seu próximo turno.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Atordoar (Custo 2d6)(Constituição); Nocaute (Custo: 6d6)(Constituição); Obscurecer (Custo: 3d6)(Destreza) CD: 20\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:48:05','2026-08-30 02:48:05'),(110,8,'Dilacerar Mente','class_feature','Ladino - SubClasse',17,'Você pode varrer a mente de uma criatura com suas Lâminas Psíquicas. Quando você usa suas Lâminas Psíquicas para causar dano de Ataque Furtivo a uma criatura, você pode forçar o alvo a fazer um teste de resistência de Sabedoria (CD 8 mais seu modificador de Destreza e bônus de proficiência ) . Se o teste falhar, o alvo fica Atordoado por 1 minuto. repete o teste no final de cada um de seus turnos, encerrando o efeito sobre si mesmo em caso de sucesso.\n\nApós usar essa habilidade, você não poderá usá-la novamente até concluir um Descanso Longo, a menos que gaste três Dados de Energia Psiônica (sem necessidade de ação) para restaurar seu uso.',1,1,'long_rest','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Uma vez por Descanso Longo (ou gastando 1 Ponto psi) o usar as Lâminas Psíquicas para causar dano Furtivo o alvo a fazer um teste de SAB em caso de falha fica inconsciente por 1mim\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:52:56','2026-08-30 02:54:32'),(111,8,'Ilusivo','class_feature','Ladino',18,'Você é tão evasivo que os atacantes raramente conseguem levar vantagem contra você. Nenhuma jogada de ataque pode ter vantagem contra você, a menos que você esteja na condição Incapacitado .',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Ataques contra você não podem ter Vantagem\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:54:19','2026-08-30 02:54:19'),(112,8,'Poderes Psiônicos','class_feature','Talento - MultiClasse',20,NULL,4,0,'long_rest','{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"build\", \"recovery_custom\": null}','2026-08-30 02:57:27','2026-08-30 02:59:13'),(113,8,'Esforço Para Manter','class_feature','Talento - MultiClasse',20,'Sempre que você falhar em um teste de resistência de Constituição para manter a concentração em um ou mais poderes adquiridos por esta classe, você pode sofrer um esforço para manter todos os poderes nos quais está se concentrando ativos. Esse esforço é igual à soma da ordem desses poderes.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 02:58:19','2026-08-30 02:58:51'),(114,8,'Mão da Compreensão','class_feature','Item Mágico',1,NULL,1,1,'short_rest','{\"column\": \"right\", \"activation\": \"action\", \"quick_text\": \"Conjura o feitiço Mão da Compreensão.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 03:00:26','2026-08-30 03:00:39'),(115,9,'Passo Lunar','class_feature','Druida (Lua)',10,'Você se transporta magicamente, reaparecendo em meio a uma explosão de luar. Como uma Ação Bônus, você se teleporta até 9 metros para um espaço desocupado à sua vista e tem Vantagem na próxima jogada de ataque que realizar antes do final deste turno.\n\nVocê pode usar essa característica um número de vezes igual ao seu modificador de Sabedoria (mínimo de uma vez) e restaura todos os usos gastos ao completar um Descanso Longo. Você também pode recuperar usos gastando um espaço de magia de 2º círculo ou superior para cada uso que deseja recuperar (nenhuma ação é necessária).\n\nAo chegar ao nível 14 você ganha a seguinte habilidade:\n\nLuar Compartilhado. Sempre que usar Passo Lunar, você também pode teleportar uma criatura voluntária. Essa criatura deve estar a até 10ft de você, e você a teleporta para um espaço desocupado à sua vista a até 10ft do seu destino.',5,5,'long_rest','{\"column\": \"right\", \"activation\": \"bonus_action\", \"quick_text\": \"Teleporta até 30ft e ganha vantagem no proximo ataque.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 03:03:37','2026-08-30 06:28:43'),(116,8,'Intervenção Heroica','class_feature','Talento',NULL,'Intervenção Heroica. Quando um inimigo que você pode ver realiza uma Ação Lendária, você pode usar uma Reação para intervir, impedindo que a Ação Lendária aconteça. Você pode usar essa Reação um número de vezes igual ao seu Bônus de Proficiência e recupera todos os usos gastos ao terminar um Descanso Curto ou Longo.',6,6,'short_rest','{\"column\": \"right\", \"activation\": \"reaction\", \"quick_text\": \"Sua sua reação para cancelar a Ação Lendária de uma criatura que você possa ver.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 03:04:12','2026-08-30 03:04:12'),(117,8,'Estrela Cadente','class_feature','Item Maravilhoso',1,'Usando uma ação, você salta **300ft** para cima e imediatamente mergulhando em queda livre como uma estrela flamejante. **Você não sofre dano de queda.**\n    \n    Ao aterrissar, todas as criaturas em um raio de 15ft do ponto de impacto devem realizar um **teste de resistência de Destreza CD 17.** Em caso de falha, a criatura sofre **10d10 de dano radiante**; em caso de sucesso, sofre metade do dano.',1,1,'day','{\"column\": \"right\", \"activation\": \"passive\", \"quick_text\": \"Usando uma Ação você usar a habilidade Estrela Cadente.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 03:05:15','2026-08-30 03:05:24'),(118,9,'Ataque Primordial','class_feature','Druida',7,'O poder dos elementos flui através de você. Você recebe uma das seguintes opções à sua escolha:\n \nAtaque Primordial.. Uma vez em cada um dos seus turnos, ao atingir uma criatura com uma jogada de ataque usando uma arma ou um ataque da forma Animal em Forma Selvagem, pode causar 1d8 pontos de dano Elétrico, Gelo, Fogo, Trovejante ou Impacto (à sua escolha quando você atinge) adicional ao alvo.\n\nNo nível 15 a opção que você escolheu para Fúria Elemental fica mais poderosa, conforme detalhado abaixo:\n\nAtaque Primordial. O dano adicional de seu Ataque Primordial aumenta para 2d8.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Seu primeiro ataque no seu turno causa dano adicional (2d8).\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 06:18:58','2026-08-30 06:18:58'),(119,9,'Magias Bestiais','class_feature','Druida',18,'Ao usar Forma Selvagem, você pode conjurar magias na forma Animal, exceto magias que tenham um componente Material com um custo especificado ou que consuma seu componente Material.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Pode usar magias na Forma Selvagem.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 06:22:36','2026-08-30 06:22:36'),(120,9,'Vai uma Mãozinha?','class_feature','Paladino',1,'Seu toque abençoado pode aliviar feridas. Você tem uma reserva de poder de cura que reabastece ao completar um Descanso Longo. Com essa reserva, você pode recuperar um número total de Pontos de Vida igual a cinco vezes seu nível de Paladino. \n\nComo uma Ação Bônus, você toca uma criatura (que pode ser você mesmo) e extrair poder dessa reserva de cura para restaurar um número de Pontos de Vida para essa criatura, até o valor máximo restante na reserva. Você também pode gastar 5 Pontos de Vida dessa reserva de poder de cura para remover a condição Envenenado da criatura; esses pontos não restauram Pontos de Vida da criatura.',5,5,'long_rest','{\"column\": \"right\", \"activation\": \"bonus_action\", \"quick_text\": \"Gasta um uso para curar 1 PV.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 06:28:18','2026-08-30 06:28:33'),(122,9,'Visão no Escuro','species_trait','Meio Elfo',NULL,'Graças ao seu sangue de elfo, você tem visão superior em condições escuras e escuras. Você pode ver em luz fraca a menos de 18 metros de você como se fosse luz brilhante, e na escuridão como se fosse luz fraca. Não é possível discernir cores na escuridão, apenas tons de cinza.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Visão no escuro de 60ft\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 06:34:13','2026-08-30 06:34:13'),(123,9,'Ancestralidade Fey','species_trait','Meio Elfo',NULL,'Você tem vantagem em testes de resistência contra encanto, e a magia não pode fazer você dormir.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Vantagem em testes de resistência contra encantamento.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 06:35:18','2026-08-30 06:35:18'),(124,9,'Armaduras Médias','armor_training',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-30 06:35:46','2026-08-30 06:35:46'),(125,9,'Armaduras Leves','armor_training',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-30 06:35:47','2026-08-30 06:35:47'),(126,9,'Armas Simples','weapon_training',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-30 06:35:49','2026-08-30 06:35:49'),(127,9,'Armas Marciais','weapon_training',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-30 06:35:50','2026-08-30 06:35:50'),(128,9,'Comum','language',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-30 06:37:01','2026-08-30 06:37:01'),(129,9,'Élfico','language',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-30 06:37:02','2026-08-30 06:37:02'),(130,9,'Anão','language',NULL,20,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-30 06:37:02','2026-08-30 06:37:02'),(131,9,'Dádiva do Ataque Irresistível','feat','Epic Boon (Vencedor do Torneio do Senhor das Tempestades)',1,'Você adquire os seguintes benefícios.\n\nAumento no Valor de Atributo. Aumente seu valor de Força ou Destreza em 1, até no máximo 30.\n\nSuperar Defesas. O dano Contundente, Cortante e Perfurante que você causa sempre ignora Resistência.\n\nGolpe Devastador. Quando você tira 20 no d20 para uma jogada de ataque, pode causar dano adicional ao alvo igual ao valor do atributo aumentado por este talento. O tipo de dano adicional é o mesmo do ataque.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"O dano Perfurante, Cortante e Impacto que você causa ignoram resistência. Ao rolar critico causa um dano adicional igual a sua Destreza.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 06:41:44','2026-08-30 06:43:06'),(132,9,'Dádiva da Proficiência em Perícia','feat','Epic Boon',19,'Você adquire os seguintes benefícios.\n\nAumento no Valor de Atributo. Aumente um valor de atributo à sua escolha em 1, até no máximo 30.\n\nAssecla Completo. Você adquire proficiência em todas as perícias.\n\nExpertise. Escolha uma perícia na qual você tenha proficiência, mas não tenha Expertise. Você obtém Expertise nessa perícia.',NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Ganha proficiência em todas as pericias.\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 06:44:49','2026-08-30 06:44:49'),(133,4,'Especialista em Talento','feat','Talento',12,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": \"Recebe Expertise em Enganação e +1 em Con\", \"counter_mode\": \"spend\", \"recovery_custom\": null}','2026-08-30 09:12:19','2026-08-30 09:12:19'),(134,10,'Armas Simples','weapon_training',NULL,19,NULL,NULL,NULL,NULL,'{\"column\": \"left\", \"activation\": \"passive\", \"quick_text\": null, \"counter_mode\": \"spend\", \"roll_ability\": null, \"recovery_custom\": null}','2026-08-31 05:59:06','2026-08-31 05:59:06');
/*!40000 ALTER TABLE `character_features` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `character_items`
--

DROP TABLE IF EXISTS `character_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `character_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `character_id` bigint unsigned NOT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` int unsigned NOT NULL DEFAULT '1',
  `weight` decimal(8,2) DEFAULT NULL,
  `equipped` tinyint(1) NOT NULL DEFAULT '0',
  `is_magical` tinyint(1) NOT NULL DEFAULT '0',
  `rarity` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requires_attunement` tinyint(1) NOT NULL DEFAULT '0',
  `attuned` tinyint(1) NOT NULL DEFAULT '0',
  `is_cursed` tinyint(1) NOT NULL DEFAULT '0',
  `curse_description` text COLLATE utf8mb4_unicode_ci,
  `curse_revealed` tinyint(1) NOT NULL DEFAULT '0',
  `armor_class` int DEFAULT NULL,
  `damage` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attack_bonus` int DEFAULT NULL,
  `damage_bonus` int DEFAULT NULL,
  `ability_bonuses` json DEFAULT NULL,
  `properties` json DEFAULT NULL,
  `modifiers` json DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `character_items_character_id_type_index` (`character_id`,`type`),
  KEY `character_items_character_id_equipped_index` (`character_id`,`equipped`),
  KEY `character_items_character_id_attuned_index` (`character_id`,`attuned`),
  KEY `character_items_character_id_is_magical_index` (`character_id`,`is_magical`),
  KEY `character_items_character_id_requires_attunement_index` (`character_id`,`requires_attunement`),
  KEY `character_items_character_id_is_cursed_index` (`character_id`,`is_cursed`),
  KEY `character_items_is_magical_rarity_index` (`is_magical`,`rarity`),
  CONSTRAINT `character_items_character_id_foreign` FOREIGN KEY (`character_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `character_items`
--

LOCK TABLES `character_items` WRITE;
/*!40000 ALTER TABLE `character_items` DISABLE KEYS */;
INSERT INTO `character_items` VALUES (5,4,'Anel da Rocha Firme','wonderful','Um anel grosso feito de pedra, cheia de runas.','character-items/4/KpVLAOEDBh6jaD8fGHE7Sxi4PMOAvEajYKlMsut1.png',1,NULL,1,1,'uncommon',0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Proteção Da Pedra\", \"usage\": {\"enabled\": false}, \"description\": \"Vantagem contra ser empurrado e contra ficar deitado (Prone).\\r\\n    - Enquanto parado, recebe +1 CA.\"}, {\"title\": \"Pele De Pedra\", \"usage\": {\"max\": 1, \"current\": 1, \"enabled\": true, \"recovery\": \"day\", \"recovery_custom\": null}, \"description\": \"Após Receber dano de Impacto, você pode usar a sua reação para ganhar resistência a dano de Impacto por 1 minuto.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-26 21:54:36','2026-08-29 21:32:40'),(7,4,'Cursiva','wonderful','Esta lâmina apresenta o desenho de uma caneta-tinteiro. Sua guarda parece ser feita de um redemoinho de tinta, mas é sólida como metal ao toque.','character-items/4/QP2lQLqKImbiKOoNU0bjTacpFOGyFCsNx4MpTEvA.png',1,NULL,1,1,'legendary',1,1,0,NULL,0,NULL,'1d8',2,2,NULL,'{\"nature\": \"wonderful\", \"weapon\": {\"damage\": {\"die\": \"d8\", \"type\": \"Perfurante\", \"count\": 1, \"ability\": \"dexterity\", \"ability_custom\": null}, \"traits\": [{\"key\": \"finesse\", \"name\": \"Acuidade\", \"custom\": false, \"description\": \"Ao realizar um ataque com uma arma que possui Acuidade, você pode usar o modificador de Força ou de Destreza, à sua escolha, para as jogadas de ataque e dano. Você deve usar o mesmo modificador para ambas as jogadas.\"}, {\"key\": \"light\", \"name\": \"Leve\", \"custom\": false, \"description\": \"Quando você usa a ação Atacar no seu turno e ataca com uma arma Leve, pode fazer um ataque extra como uma Ação Bônus mais tarde no mesmo turno. Esse ataque extra deve ser feito com uma arma Leve diferente, e você não adiciona seu modificador de habilidade ao dano do ataque extra, a menos que esse modificador seja negativo.\"}], \"category\": \"martial\", \"masteries\": [{\"key\": \"vex\", \"name\": \"Vex\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma e causar dano a ela, terá Vantagem na sua próxima jogada de ataque contra essa criatura antes do fim do seu próximo turno.\"}], \"magic_bonus\": 2, \"weapon_type\": \"Rapieira\", \"extra_damage\": [{\"die\": \"d4\", \"type\": \"Ácido\", \"count\": 2}], \"category_custom\": null}, \"features\": [{\"title\": \"Escrita Ilusória.\", \"usage\": {\"enabled\": false}, \"description\": \"Você pode usar uma ação para conjurar a magia Escrita Ilusória a partir da arma (em qualquer forma), usando a ponta da caneta ou da lâmina para escrever a mensagem. Você pode ter até três mensagens escritas dessa forma simultaneamente. Se você criar uma quarta mensagem, a primeira desaparece.\"}, {\"title\": \"Símbolo Estonteante.\", \"usage\": {\"enabled\": false}, \"description\": \"Você pode gastar 1 minuto usando o florete para desenhar um símbolo no chão, duplicando os efeitos da magia símbolo (CD 17 para resistir; somente a opção Estonteante). Até que o símbolo seja dissipado, o florete deixa de causar dano ácido adicional. O símbolo é dissipado automaticamente ao final de um descanso longo. Você só pode ter um símbolo ativo desta forma por vez.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-26 22:31:55','2026-08-29 18:57:51'),(8,4,'Kit Medico','mundane',NULL,'character-items/4/LyfZEzphG0Z76seqc34IGhKJbMzm6d48xN9aiuBh.png',1,NULL,0,0,'common',0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"mundane\", \"features\": [{\"title\": \"Tratar Feridas\", \"usage\": {\"max\": 10, \"current\": 10, \"enabled\": true, \"recovery\": \"single_use\", \"recovery_custom\": null}, \"description\": \"Um Kit de Curandeiro tem dez usos. Como uma ação de Utilizar , você pode gastar um de seus usos para estabilizar uma criatura Inconsciente que tenha 0 Pontos de Vida sem precisar fazer um teste de Sabedoria ( Medicina ).\"}], \"inventory\": {\"equippable\": false}, \"custom_properties\": []}',NULL,NULL,'2026-08-26 22:55:50','2026-08-28 23:01:20'),(9,8,'Insensatez','wonderful','A Insensatez não foi forjada\r\nEla foi pensada\r\nNa fronteira da mente o desejo encontra o inevitável, uma ideia de vitória cresceu tão intensa que rompeu a abstração. \r\nEsse reflexo de vitória, incapaz de permanecer apenas como pensamento, partiu o véu da imaginação e assumiu forma.\r\nO resultado foi uma arma impossível, um fragmento de certeza que se materializou antes mesmo de ser compreendida.\r\nQuem a segura sabe que a vitória se tornou a sua próxima decisão correta.',NULL,1,NULL,1,1,'artifact',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Criação\", \"usage\": {\"enabled\": false}, \"description\": \"A Insensatez torna-se completa, uma verdade arrancada do sonho e imposta ao mundo. Você recebe +3 em testes de ataque e rolagens de dano. A arma passa a causar (+2d6) de dano Energia.\"}, {\"title\": \"Precognição\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto empunha a Insensatez, sua mente prevê instantes que ainda não aconteceram. Você passa a adicionar seu modificador de Inteligência a todos os testes de Salvamento.\"}, {\"title\": \"Brecha Na Guarda\", \"usage\": {\"enabled\": false}, \"description\": \"Ao analisar uma criatura usando Arte da Guerra, sua mente identifica a falha exata em sua defesa. Até o fim do seu próximo turno, o primeiro ataque que você realizar contra o alvo acerta automaticamente. Role o dado apenas para\\r\\ndeterminar se é crítico.\\r\\nSe você possuir Ataque Furtivo disponível no turno, pode aplicá-lo nesse ataque, mesmo sem vantagem ou aliados próximos.\"}, {\"title\": \"Corpo e Mente\", \"usage\": {\"enabled\": false}, \"description\": \"Sua consciência expande seus reflexos como se cada movimento tivesse sido decidido um instante antes de acontecer. Enquanto estiver sintonizado com Insensatez, sua Destreza aumenta em +2, até um máximo de 24.\"}, {\"title\": \"Análise Mimética\", \"usage\": {\"enabled\": false}, \"description\": \"A Insensatez observa a alma do alvo, permitindo copiar suas características. Assim que você usar Arte da Guerra para descobrir as resistências de uma criatura, você pode como ação livre copiar uma das resistências a dano do alvo. A cópia dura até o fim do seu próximo turno.\"}, {\"title\": \"Concepcionar Vitoria\", \"usage\": {\"enabled\": false}, \"description\": \"Ao usar Arte da Guerra contra uma criatura em combate e revelar uma Habilidade, Ação, Ação Bônus ou Reação, você pode copiar imediatamente aquela informação como uma ação livre. Essa Cópia fica armazenada dentro da sua Insensatez, que comporta um número de cópias igual ao seu modificador de Inteligência (mínimo de 1). A qualquer momento, você pode ativar uma ou mais das habilidades copiadas, gastando-as no processo. Assim que a informação é aprendida por você, você pode usar a opção copiada como se fosse sua pelos próximos 10 minutos.\\r\\n\\r\\nLimitações:\\r\\nA habilidade Concepcionar Vitoria não pode Copiar: Habilidades, Ações, Ações Bônus ou Reações concedidas por Artefatos. Qualquer forma de conjuração, seja magia inata, magia preparada ou efeitos equivalentes. Se houver ambiguidade sobre a possibilidade de copia, o Mestre tem a decisão final.\\r\\n\\r\\nO Preço da Vitória:\\r\\nUsar Concepcionar Vitória força sua mente a tocar o contorno da alma de outra criatura. Fazendo sua própria consciência\\r\\nse esticar além do que deveria. Quando o efeito de Concepcionar Vitória termina (após 10 minutos), você recebe 2 pontos de Exaustão por cada habilidade aprendida.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-28 01:44:21','2026-08-28 01:56:14'),(10,8,'Faixas da Dor e Compreensão','wonderful','Duas faixas negras e sutis, que se enrolam nos antebraços como se tivessem vontade própria. Em uma, costurada em fio carmesim, lê-se Infernal: “Dor”. Na outra, “Compreensão”. Juntas, elas afiam a mente - ao custo da alma.',NULL,1,NULL,1,1,'very_rare',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Lâmina Profana\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver sintonizado com as Faixas de Dor e Compreensão, Suas **Lâminas Psíquicas** são aprimoradas:\\r\\n\\r\\n- O dado de dano principal aumenta em +1 dados (ex: de 1d6 para 2d6, e o ataque bônus de 1d4 para 2d4);\\r\\n- Você recebe +2 em jogadas de ataque e de dano ao usar Lâminas Psíquicas;\\r\\n- Alvos atingidos por suas lâminas não tem desvantagem em testes de concentração, para manter feitiços.\"}, {\"title\": \"Mão da Compreensão\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver sintonizado, você pode conjurar Mão Espectral de Compreensão (descrita abaixo) uma vez por descaso Curto, sem gastar espaço de magia. Esta versão conta como um feitiço de 3°.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-28 03:23:03','2026-08-28 03:23:47'),(11,8,'Anel da Família Rodinguer','wonderful','Um dos anéis da família Rodinguer, passados para os mais velhos da família como um símbolo de amadurecimento.',NULL,1,NULL,1,1,'very_rare',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Proteção Arcana\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver usando este anel, você ganha um bônus de +2 em sua Armadura e em Testes de Salvamentos\"}, {\"title\": \"Quebra da Realidade (1/Dia)\", \"usage\": {\"max\": 1, \"current\": 1, \"enabled\": true, \"recovery\": \"day\", \"recovery_custom\": null}, \"description\": \"Você quebra as barreiras do espaço e teletransporta uma criatura por um turbilhão de locais dos confins da existência. Você pode conjurar Quebra de Realidade\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-28 03:25:45','2026-08-30 07:32:33'),(12,8,'Botas Aéreas de Rodinguer','wonderful','(Requer o Anel da Família Rodinguer)\r\nEstas botas escuras, de acabamento elegante, brilham levemente com pontos dourados que lembram estrelas distantes. Criadas por Horsea Rodinguer, mestre da Graviturgia, elas desafiam as leis naturais do movimento e da gravidade. Quando usadas, as botas emitem um leve rastro de partículas douradas ao se mover.',NULL,1,NULL,1,1,'very_rare',0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Verdadeiro Caminhante Estelar\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver usando estas botas, você pode se mover vertical ou horizontalmente pelo ar como se tivesse subindo degraus invisíveis. Você não precisa terminar seu movimento em solo firme, mas ainda cairá caso esteja incapacitado ou imobilizado.\"}, {\"title\": \"Salto sem Gravidade\", \"usage\": {\"enabled\": false}, \"description\": \"Sua distância de salto aumenta para 30 pés na vertical e 60 pés na horizontal, independente do seu modificador de Força ou deslocamento. Você não precisa de impulso para saltar.\"}, {\"title\": \"Estrela Cadente (1/Dia)\", \"usage\": {\"max\": 1, \"current\": 1, \"enabled\": true, \"recovery\": \"day\", \"recovery_custom\": null}, \"description\": \"Usando uma ação, você salta 300ft para cima e imediatamente mergulhando em queda livre como uma estrela flamejante. Você não sofre dano de queda.\\r\\n    \\r\\n    Ao aterrissar, todas as criaturas em um raio de 15ft do ponto de impacto devem realizar um teste de resistência de Destreza CD 17. Em caso de falha, a criatura sofre 10d10 de dano radiante; em caso de sucesso, sofre metade do dano.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-28 03:29:39','2026-08-28 03:35:22'),(13,8,'Óculos Prismático da Clarividência','wonderful','Esta lupa de prata possui uma borda intricada e uma lente de cristal perfeitamente polida. Ela emana uma leve aura de energia mágica quando segurada. Ao observar minunciosamente um objeto, cena ou local, alente amplifica os detalhes, revelando pistas ocultas, trilhas tênues e padrões sutis que poderiam passar despercebidos aos sentidos comuns.',NULL,1,NULL,1,1,'uncommon',0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Bônus\", \"usage\": {\"enabled\": false}, \"description\": \"- A lupa concede Vantagens Em Testes De Investigação realizados pelo usuário.\\r\\n    - Além disso, a lupa também permite ao usuário enxergar auras de magia ao examinar runas, textos, inscrições arcanas ou itens mágicos Podendo decifrar o tipo de aura que ela emana.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-28 03:32:19','2026-08-28 03:33:25'),(14,4,'Machado Do Retorno','wonderful','Uma machadinha de pedra simples com runas escritas nela','character-items/4/uMyxui64BPRzGNlG88iP5AOd2lp6PR9xdHGZqjVU.webp',1,NULL,0,1,'rare',1,0,0,NULL,0,NULL,'1d8',NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"weapon\": {\"damage\": {\"die\": \"d8\", \"type\": \"Cortante\", \"count\": 1, \"ability\": \"strength\", \"ability_custom\": null}, \"traits\": [{\"key\": \"light\", \"name\": \"Leve\", \"custom\": false, \"description\": \"Quando você usa a ação Atacar no seu turno e ataca com uma arma Leve, pode fazer um ataque extra como uma Ação Bônus mais tarde no mesmo turno. Esse ataque extra deve ser feito com uma arma Leve diferente, e você não adiciona seu modificador de habilidade ao dano do ataque extra, a menos que esse modificador seja negativo.\"}, {\"key\": \"thrown\", \"name\": \"Arremesso\", \"custom\": false, \"description\": \"Se uma arma possuir a propriedade Arremesso, você pode arremessá-la para realizar um ataque à distância e pode sacá-la como parte desse ataque. Se for uma arma corpo a corpo, use o mesmo modificador de habilidade para as jogadas de ataque e dano que usaria em um ataque corpo a corpo com essa arma.\"}], \"category\": \"martial\", \"masteries\": [{\"key\": \"vex\", \"name\": \"Vex\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma e causar dano a ela, terá Vantagem na sua próxima jogada de ataque contra essa criatura antes do fim do seu próximo turno.\"}], \"magic_bonus\": 0, \"weapon_type\": \"Machado\", \"extra_damage\": [], \"category_custom\": null}, \"features\": [{\"title\": \"Retorno\", \"usage\": {\"enabled\": false}, \"description\": \"Ao arremessar a machadinha, ela volta para a sua mão\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 10:18:14','2026-08-29 21:21:53'),(15,4,'Colar Da Devoção +3','wonderful','Um colar lindo de prata, contendo uma lua cheia e uma meia lua','character-items/4/1KR5WNU1UhTwRZlYn1e4Us06XOicE0IdEfpSQV14.png',1,NULL,1,1,'very_rare',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Devoção Lunar\", \"usage\": {\"enabled\": false}, \"description\": \"Você recebe +3 em teste de ataque magico e +3 na CD de feitiços\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 10:21:20','2026-08-29 18:57:44'),(16,4,'Escudo de Absorção Mágica','wonderful','Um escudo com uma gema azul no centro','character-items/4/creA80EDJeyQaYo3uOyow2SWvb9TL8LAHMq2ryAf.png',1,NULL,1,1,'legendary',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"shield\": {\"label\": \"Escudo\", \"ac_bonus\": 2, \"magic_bonus\": 2}, \"features\": [{\"title\": \"Resistencia Magica Extra\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver segurando este escudo, você tem Vantagem em Salvamentos contra feitiços e outros efeitos mágicos, e as jogadas de ataque mágico contra você são feitas com desvantagem.\"}, {\"title\": \"Absorção Arcana\", \"usage\": {\"max\": 3, \"current\": 3, \"enabled\": true, \"recovery\": \"day\", \"counter_mode\": \"spend\", \"recovery_custom\": null}, \"description\": \"Sempre que você for alvo de uma magia, incluindo uma magia que envolva uma jogada de ataque mágico, ou estiver dentro da área de efeito de uma magia, você pode usar sua Reação para tentar absorver a trama arcana.\\r\\n\\r\\nFaça um teste de Constituição, adicionando seu bônus de proficiência e seu modificador de Constituição, contra a CD do feitiço. Se o feitiço exigir uma jogada de ataque em vez de um teste de resistência, a CD do teste é igual ao resultado da jogada de ataque mágico.\\r\\n\\r\\nSe o resultado for igual ou maior, você absorve a energia da magia e acumula um número de cargas igual ao nível da magia. O escudo pode possuir no máximo 10 cargas.\\r\\n\\r\\nMagia direcionada. Se você for o único alvo da magia, a magia é completamente absorvida e não causa dano nem produz efeitos sobre você.\\r\\n\\r\\nÁrea de efeito. Se você estiver dentro da área de uma magia, você se torna imune aos danos e efeitos daquela instância específica da magia até o início do seu próximo turno.\\r\\n\\r\\nUma magia absorvida dessa maneira ainda é considerada lançada normalmente para outros alvos e efeitos.\"}, {\"title\": \"Campo Anti-magia\", \"usage\": {\"max\": 8, \"current\": 0, \"enabled\": true, \"recovery\": \"custom\", \"counter_mode\": \"spend\", \"recovery_custom\": \"Cargas\"}, \"description\": \"Enquanto o escudo possuir 8 ou mais cargas, você pode gastar 8 cargas e usar uma ação para liberar a energia acumulada e conjurar Campo Antimagia sem gastar espaço de magia e sem necessidade de concentração.\\r\\n\\r\\nO campo emana de você e funciona como a magia Campo Antimagia.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 10:22:50','2026-08-31 08:31:43'),(18,4,'Armadura Lunar','wonderful',NULL,NULL,1,NULL,1,1,'legendary',0,0,0,NULL,0,17,NULL,NULL,NULL,NULL,'{\"armor\": {\"base_ac\": 15, \"category\": \"medium\", \"armor_type\": \"Meia Armadura\", \"magic_bonus\": 2, \"dexterity_cap\": 2, \"dexterity_mode\": \"capped\", \"category_custom\": null, \"ability_modifiers\": []}, \"nature\": \"wonderful\", \"features\": [], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 22:25:06','2026-08-31 08:31:44'),(19,9,'Armadura da Sobremarcha Cardíaca','wonderful','Essa armadura de couro preta e revestida de peças de residuum negro nas extremidades. Enquanto você usa essa armadura você ganha os seguintes benefícios:','character-items/9/rwHPKC9IuGFoBngNEDnJXGGC172dSBFpwWnYCTFw.png',1,NULL,1,1,'legendary',1,1,0,NULL,0,14,NULL,NULL,NULL,NULL,'{\"armor\": {\"base_ac\": 14, \"category\": \"light\", \"armor_type\": \"Couro\", \"magic_bonus\": 0, \"dexterity_cap\": 2, \"dexterity_mode\": \"full\", \"category_custom\": null, \"ability_modifiers\": []}, \"nature\": \"wonderful\", \"features\": [{\"title\": \"Graça de Velocidade\", \"usage\": {\"enabled\": false}, \"description\": \"Seu deslocamento aumenta em +10 enquanto usa essa armadura.\"}, {\"title\": \"Segunda Marcha\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto você estiver sintonizado com essa armadura a sua destreza aumenta em (+2), podendo ultrapassar o limite de 20.\"}, {\"title\": \"Sobremarcha Cardíaca\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto você estiver usando está armadura você pode usar uma ação para ativar uma aceleração sobrenatural no seu corpo. Enquanto você estiver sobre o efeito dessa aceleração você os seguintes benefícios por 1 minuto.\\r\\n\\r\\n- O seu deslocamento é dobrado.\\r\\n- Você ganha +2 de bônus na Classe de Armadura.\\r\\n- Você tem vantagem em testes de Resistência e em testes de pericia com base em Destreza\\r\\n- E por fim uma Ação Padrão adicional em cada um dos turnos. Se você já usou a ação de ataque no turno, usar essa ação extra pra atacar, apenas concede 1 ataque a mais.\\r\\n\\r\\nNo final da sobremarcha, você deve fazer um salvamento de constituição CD 20, se falhar envelhece 1 ano  e fica atordoado por 1 rodada. (Esse envelhecimento não é físico, mas sim interno, representa o seu coração estando em um estado frágil devido ao uso contínuo da sobremarcha)\"}, {\"title\": \"Primeiro Estagio - Síndrome da Entropia Celular Autoimune\", \"usage\": {\"enabled\": false}, \"description\": \"Cansaço, Fraqueza, Tosse e Lentidão. CD do Salvamento da armadura sobe para 25. Você passa a precisar de 10H para um descanso longo e 3 Horas para um descanso curto.\"}, {\"title\": \"Segundo Estagio -\", \"usage\": {\"enabled\": false}, \"description\": \"1 Descanso Longo é um Descanso Curto. 3 Descanso Longo é um Descanso Longo.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 22:55:16','2026-08-30 07:05:29'),(21,12,'Capa das Nove Vidas','wonderful','Quando você encontra essa capa ela tem 1d6+3 usos restantes.',NULL,1,NULL,1,1,'very_rare',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Sorte do Gato\", \"usage\": {\"max\": 8, \"current\": 8, \"enabled\": true, \"recovery\": \"single_use\", \"counter_mode\": \"spend\", \"recovery_custom\": null}, \"description\": \"Toda vez que você for reduzido a 0 pontos de vida, ou acabe sofrendo um efeito que o mate instantaneamente, você invés disso volta com 1 ponto de vida das cargas do manto é gasta.\"}, {\"title\": \"Maldição\", \"usage\": {\"enabled\": false}, \"description\": \"Apenas um feitiço de Remover Maldição de 8º nível ou maior pode quebrar a sua sintonização com esse item. Quando a ultima carga da capa for gasta, você vira um gato, como se tivesse concentrado por toda a duração no feitiço de Polimorfia Verdadeira.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 22:58:26','2026-08-29 23:03:40'),(22,12,'Medalhão do Andarilho','wonderful','Este medalhão de prata envelhecida traz a efígie de um velho gato sorridente no centro, com inscrições antigas em sua borda representando caminhos, trilhas e cruzamentos esquecidos.',NULL,1,NULL,1,1,'very_rare',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Ventos da Agilidade (3 cargas/dia)\", \"usage\": {\"max\": 3, \"current\": 3, \"enabled\": true, \"recovery\": \"dawn\", \"counter_mode\": \"spend\", \"recovery_custom\": null}, \"description\": \"Enquanto estiver sintonizado com este medalhão, você pode gastar 1 carga como uma ação bônus para ativar os Ventos da Agilidade. Por 1 minuto, você recebe os seguintes benefícios:\\r\\n    \\r\\n    - Vantagem em todos os testes de Destreza.\\r\\n    - Vantagem em salvamentos de Destreza.\\r\\n    - Seu deslocamento aumenta em (15ft)\\r\\n    \\r\\n    O medalhão possui 3 cargas, e recupera todas as cargas ao amanhecer.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 23:03:13','2026-08-29 23:03:23'),(23,12,'Braçadeiras de Defesa','wonderful','Ao usar essas braçadeiras, você ganha um bônus de +2 na Classe de Armadura se não estiver usando armadura nem escudo.',NULL,1,NULL,1,1,'rare',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 23:04:46','2026-08-29 23:04:52'),(24,12,'+1 Bastão','wonderful','Você tem um bônus de +1 em jogadas de ataque feitas com esta arma.',NULL,1,NULL,1,1,'uncommon',0,0,0,NULL,0,NULL,'1d10',NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"weapon\": {\"damage\": {\"die\": \"d10\", \"type\": \"Impacto\", \"count\": 1, \"ability\": \"dexterity\", \"ability_custom\": null}, \"traits\": [{\"key\": \"versatile\", \"name\": \"Versátil\", \"custom\": false, \"description\": \"Uma arma Versátil pode ser usada com uma ou duas mãos. Um valor de dano alternativo aparece associado à propriedade. A arma causa esse dano quando usada com as duas mãos para realizar um ataque corpo a corpo.\"}], \"category\": \"simple\", \"masteries\": [{\"key\": \"topple\", \"name\": \"Topple\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma, pode forçá-la a realizar um teste de resistência de Constituição. A CD é igual a 8 + o modificador de habilidade usado na jogada de ataque + seu Bônus de Proficiência. Em caso de falha, a criatura fica Caída.\"}], \"magic_bonus\": 0, \"weapon_type\": \"Cajado\", \"extra_damage\": [], \"category_custom\": null}, \"features\": [], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 23:09:17','2026-08-29 23:10:55'),(25,9,'Antiga Lamina de Capim (Capim)','wonderful','A Antiga Lâmina de Capim é uma arma que carrega a benção de Melora, a Deusa da Natureza. Forjada nas profundezas de florestas ancestrais, a lâmina parece feita de um único fio de capim, mas sua resistência e poder são incomparáveis. Quando não está em uso, ela se enrola ao redor do braço do portador como uma folha, conferindo uma aparência natural e quase imperceptível. No entanto, ao ser desembainhada, a lâmina se estende com uma velocidade surpreendente, pronta para cortar qualquer inimigo que ameace a natureza.','character-items/9/qFW6MoFFxEd5cZB3Q96SuZOYF61u4pp8meOz9gev.png',1,NULL,1,1,'artifact',1,1,0,NULL,0,NULL,'2d10',3,3,NULL,'{\"nature\": \"wonderful\", \"weapon\": {\"damage\": {\"die\": \"d10\", \"type\": \"Perfurante, Contundente ou Cortante\", \"count\": 2, \"ability\": \"dexterity\", \"ability_custom\": null}, \"traits\": [{\"key\": \"light\", \"name\": \"Leve\", \"custom\": false, \"description\": \"Quando você usa a ação Atacar no seu turno e ataca com uma arma Leve, pode fazer um ataque extra como uma Ação Bônus mais tarde no mesmo turno. Esse ataque extra deve ser feito com uma arma Leve diferente, e você não adiciona seu modificador de habilidade ao dano do ataque extra, a menos que esse modificador seja negativo.\"}], \"category\": \"custom\", \"masteries\": [{\"key\": \"cleave\", \"name\": \"Cleave\", \"custom\": false, \"description\": \"Se você acertar uma criatura com uma jogada de ataque corpo a corpo usando esta arma, pode realizar uma jogada de ataque corpo a corpo com a arma contra uma segunda criatura que esteja a até 5 pés da primeira e também dentro do seu alcance. Se acertar, a segunda criatura sofre o dano da arma, mas você não adiciona seu modificador de habilidade a esse dano, a menos que o modificador seja negativo. Você só pode realizar esse ataque extra uma vez por turno.\"}, {\"key\": \"graze\", \"name\": \"Graze\", \"custom\": false, \"description\": \"Se sua jogada de ataque com esta arma errar uma criatura, você pode causar a ela dano igual ao modificador de habilidade usado para realizar a jogada de ataque. Esse dano é do mesmo tipo causado pela arma e só pode ser aumentado aumentando esse modificador de habilidade.\"}, {\"key\": \"nick\", \"name\": \"Nick\", \"custom\": false, \"description\": \"Quando você realiza o ataque extra concedido pela propriedade Leve, pode fazê-lo como parte da ação Atacar em vez de usar uma Ação Bônus. Você só pode realizar esse ataque extra uma vez por turno.\"}, {\"key\": \"push\", \"name\": \"Push\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma, pode empurrá-la até 10 pés em linha reta para longe de você, desde que ela seja de tamanho Grande ou menor.\"}, {\"key\": \"vex\", \"name\": \"Vex\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma e causar dano a ela, terá Vantagem na sua próxima jogada de ataque contra essa criatura antes do fim do seu próximo turno.\"}, {\"key\": \"topple\", \"name\": \"Topple\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma, pode forçá-la a realizar um teste de resistência de Constituição. A CD é igual a 8 + o modificador de habilidade usado na jogada de ataque + seu Bônus de Proficiência. Em caso de falha, a criatura fica Caída.\"}, {\"key\": \"sap\", \"name\": \"Sap\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma, ela terá Desvantagem na próxima jogada de ataque que realizar antes do início do seu próximo turno.\"}, {\"key\": \"slow\", \"name\": \"Slow\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma e causar dano a ela, pode reduzir o Deslocamento dela em 10 pés até o início do seu próximo turno. Se a criatura for atingida mais de uma vez por armas com esta maestria, a redução de Deslocamento não ultrapassa 10 pés.\"}], \"magic_bonus\": 3, \"weapon_type\": \"Tudo\", \"extra_damage\": [], \"category_custom\": \"Arma Exótica\"}, \"features\": [{\"title\": \"Lamina Intrinseca (Dormente)\", \"usage\": {\"enabled\": false}, \"description\": \"A lâmina pode ser desembainhada ou guardada com uma ação livre. Além disso, você pode atacar duas vezes, em vez de uma, quando realizar a ação de Ataque no seu turno. Você ignora esse benefício se já tiver um recurso, como Ataque Extra, que permite atacar mais de uma vez ao realizar a ação de Ataque no seu turno.\"}, {\"title\": \"Metamórfica (Dormente)\", \"usage\": {\"enabled\": false}, \"description\": \"Com uma ação bônus, você pode alterar a forma da espada, a transformando em qualquer objeto ou arma a sua escolha. Essa alteração não muda o dano da espada ou as suas características.\"}, {\"title\": \"Benção da Natureza (Dormente)\", \"usage\": {\"enabled\": false}, \"description\": \"A lâmina é extremamente afiada mesmo em seu estado dormente, o dado de dano dessa arma é (1d10) invés do normal, e sua lâmina é imbuída com magia, concedendo-lhe (+1) nas rolagens de ataque e dano.\"}, {\"title\": \"Amalgama de Corpo e Alma (Desperta)\", \"usage\": {\"enabled\": false}, \"description\": \"Você pode atacar Três vezes, em vez de duas, quando realizar a ação de Ataque no seu turno. Você ignora esse benefício se já tiver um recurso, como Ataque Extra, que permite atacar mais de duas vezes ao realizar a ação de Ataque no seu turno.\"}, {\"title\": \"Benção Desperta da Natureza (Desperta)\", \"usage\": {\"enabled\": false}, \"description\": \"A lâmina agora despertada começa a revelar a sua verdadeira capacidade. A lâmina agora causa 1d10 a mais de dano e possuí (+2) nas rolagens de ataque e dano.\"}, {\"title\": \"Proteção Invejosa (Desperta)\", \"usage\": {\"enabled\": false}, \"description\": \"A lâmina odeia que seu portador seja machucado. Quando você for acertado por um ataque corpo a corpo que possa ver, você pode usar a sua reação para realizar um ataque corpo a corpo contra esse alvo.\"}, {\"title\": \"Exaltação Corporal (Exaltada)\", \"usage\": {\"enabled\": false}, \"description\": \"A Lâmina de Capim deseja mais de você; em um ato de amor incondicional, ela espalha suas raízes pelo seu corpo, entrelaçando-se com seus músculos e envolvendo seu coração. Sua Destreza aumenta para 22 (+6), ultrapassando os limites mortais.\"}, {\"title\": \"Benção Exaltada da Natureza (Exaltada)\", \"usage\": {\"enabled\": false}, \"description\": \"A Lâmina de Capim revela seu poder absoluto em sua forma verdadeira. A lâmina é tão afiada que, ao ser brandida, libera rajadas de vento cortantes. Ela agora possui um alcance de 15ft e concede um bônus de +3 nas rolagens de ataque e dano.\"}, {\"title\": \"Completar o Ciclo da Natureza (Exaltada)\", \"usage\": {\"enabled\": false}, \"description\": \"Usando uma Ação Padrão, você aloja a lâmina no chão, plantando-a como uma semente. Ao fazer isso, seu braço se desprende do corpo, sacrificando uma parte de sua essência no processo. A lâmina plantada começa a crescer, formando um casulo que se abre como o botão de uma flor. Dentro do casulo, surge uma \\\"Simulacra\\\" sua, uma figura feita de mato e capim, que reflete sua forma e poder. A Criatura de Capim ira lutar por você com sua própria ficha. No final no combate a criatura está livre pra tomar suas próprias decisões.\\r\\n\\r\\nO Preço do Ciclo\\r\\nUsar essa habilidade requer que o usuário entenda que tudo na vida precisa de um fim.\\r\\n\\\"Somente quando você deixa aquilo que você mais ama ir, é que você percebe a sua real importância. Se um dia ela voltar, ela será sempre sua; se não, é porque nunca foi.\\\"\"}, {\"title\": \"Senciente\", \"usage\": {\"enabled\": false}, \"description\": \"A Lâmina é imbuída com uma consciência protetora, invejosa e temperamental que não deixará você usar nenhuma outra arma além dela. Uma vez sintonizado com essa lâmina é Impossível retirá-la.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 23:41:57','2026-08-30 07:05:49'),(27,9,'Olho de Sul Khatesh','wonderful','Um olho negro e pulsante, marcado por veias de uma cor brilhante roxa, que parecem emanar com uma luz maligna. Esse artefato é um fragmento da percepção de uma entidade demoníaca, imbuído com um poder sobrenatural que transcende os limites da visão mortal e imortal.\r\n\r\nAo substituir um de seus olhos por esse artefato, você se torna capaz de enxergar além do véu da realidade, revelando segredos ocultos e presenciando visões proibidas.','character-items/9/jI8QiMmBO9h3T0f4CQYGfIGQoVT7rdu0ibbkzCob.jpg',1,NULL,1,1,'legendary',1,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Visão na Escuridão Ampliada\", \"usage\": {\"enabled\": false}, \"description\": \"Você enxerga em escuridão total, mágica ou não, até 240ft.\"}, {\"title\": \"Visão Verdadeira (True Sight)\", \"usage\": {\"enabled\": false}, \"description\": \"Você pode enxergar através de ilusões, transmutações e metamorfoses, percebendo a verdadeira forma de qualquer criatura ou objeto ao seu alcance de visão.\"}, {\"title\": \"Percepção Arcana\", \"usage\": {\"enabled\": false}, \"description\": \"Você é capaz de identificar auras mágicas automaticamente, como se estivesse sob os efeitos permanentes de Detect Magic.\"}, {\"title\": \"Ampliação De Visão\", \"usage\": {\"enabled\": false}, \"description\": \"Você possuí vantagem em testes de percepção.\"}, {\"title\": \"Visão Imortal\", \"usage\": {\"enabled\": false}, \"description\": \"Você se torna imune a condição Cego.\"}, {\"title\": \"Olhar Através da Matéria\", \"usage\": {\"max\": 1, \"current\": 1, \"enabled\": true, \"recovery\": \"dawn\", \"counter_mode\": \"spend\", \"recovery_custom\": null}, \"description\": \"Usando uma ação, você pode ativar o poder do Olho de Sul Khatesh, concedendo-lhe visão de raio-X por 10 minutos. Durante esse tempo, você pode enxergar através de objetos sólidos em um raio de 30ft, como se fossem translúcidos.\\r\\n\\r\\nLimitação: Esta visão não pode enxergar através de chumbo, mesmo que seja uma fina camada.\"}, {\"title\": \"O Fardo da Maldição (Maldição)\", \"usage\": {\"enabled\": false}, \"description\": \"O Olho do Abismo não apenas concede conhecimento, mas também fere seus nervos oculares.\\r\\n\\r\\n- O peso de um mortal portar o olho de Sul Khatesh é gigantesco, o tempo todo você tem pesadelos enquanto acordado, sua visão de torna traiçoeira, vendo almas penadas correndo e pedindo misericórdia ao seu redor.  Você perde -25 Pontos de vida permanentemente devido a grande dor que ele causa a sua mente. Além disso você sempre sente que tem alguém te olhando, não importa o local.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-29 23:58:42','2026-08-30 07:13:09'),(28,9,'Braço Mecânico (Escudo +1)','mundane','O que antes era um escudo, agora é um braço mecânico. Feito pelo brilhante artífice Seshs para seu amigo Elkas.','character-items/9/MUNDRRtrnpROtp7HQn82TYWm3SK7zt6yCfTTtgzV.png',1,NULL,1,0,'uncommon',0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"mundane\", \"shield\": {\"label\": \"Escudo\", \"ac_bonus\": 3, \"magic_bonus\": 0}, \"features\": [], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-30 00:21:10','2026-08-30 07:01:50'),(30,9,'Brinco de Penas de Pegasus (Azul)','wonderful','Um brinco de penas azuis de Pegasus.','character-items/9/vYq8pv9DGv7kewdp7EBWDk23VJsWAIOXkC2Ik2aF.png',1,NULL,0,1,'uncommon',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Aumento em Sabedoria\", \"usage\": {\"enabled\": false}, \"description\": \"Ao sintonizar com esse brinco, sua Sabedoria aumenta para +2 podendo ir além de 20.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-30 00:28:10','2026-08-30 07:09:01'),(31,9,'Galho da Arvore do Terror','wonderful','Aqueles que se libertaram das tramas que amarram o destino deixam parte de si para trás em algo perpétuo que representa sua própria vida. A Árvore do Terror proclama o \"Despertado\", servindo como a última fagulha de esperança deixada na realidade pelas leis cósmicas da existência.',NULL,1,NULL,0,1,'artifact',0,0,0,NULL,0,NULL,'1d6',NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"weapon\": {\"damage\": {\"die\": \"d6\", \"type\": \"Perfurante\", \"count\": 1, \"ability\": \"dexterity\", \"ability_custom\": null}, \"traits\": [{\"key\": \"finesse\", \"name\": \"Acuidade\", \"custom\": false, \"description\": \"Ao realizar um ataque com uma arma que possui Acuidade, você pode usar o modificador de Força ou de Destreza, à sua escolha, para as jogadas de ataque e dano. Você deve usar o mesmo modificador para ambas as jogadas.\"}, {\"key\": \"light\", \"name\": \"Leve\", \"custom\": false, \"description\": \"Quando você usa a ação Atacar no seu turno e ataca com uma arma Leve, pode fazer um ataque extra como uma Ação Bônus mais tarde no mesmo turno. Esse ataque extra deve ser feito com uma arma Leve diferente, e você não adiciona seu modificador de habilidade ao dano do ataque extra, a menos que esse modificador seja negativo.\"}, {\"key\": \"versatile\", \"name\": \"Versátil\", \"custom\": false, \"description\": \"Uma arma Versátil pode ser usada com uma ou duas mãos. Um valor de dano alternativo aparece associado à propriedade. A arma causa esse dano quando usada com as duas mãos para realizar um ataque corpo a corpo.\"}, {\"key\": \"thrown\", \"name\": \"Arremesso\", \"custom\": false, \"description\": \"Se uma arma possuir a propriedade Arremesso, você pode arremessá-la para realizar um ataque à distância e pode sacá-la como parte desse ataque. Se for uma arma corpo a corpo, use o mesmo modificador de habilidade para as jogadas de ataque e dano que usaria em um ataque corpo a corpo com essa arma.\"}], \"category\": \"simple\", \"masteries\": [], \"magic_bonus\": 0, \"weapon_type\": \"Galho\", \"extra_damage\": [], \"category_custom\": null}, \"features\": [{\"title\": \"Lei Cósmica\", \"usage\": {\"enabled\": false}, \"description\": \"Você tem +3 em testes de ataque contra o criador da árvore do Terror. Além disso, uma vez por turno ao acertar o criador da Arvore do Terror ele perde 50 PV (100 PV se for critico).\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-30 00:33:02','2026-08-30 00:33:02'),(32,9,'Galho da Arvore do Terror','wonderful','Aqueles que se libertaram das tramas que amarram o destino deixam parte de si para trás em algo perpétuo que representa sua própria vida. A Árvore do Terror proclama o \"Despertado\", servindo como a última fagulha de esperança deixada na realidade pelas leis cósmicas da existência.',NULL,1,NULL,0,1,'artifact',0,0,0,NULL,0,NULL,'1d6',NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"weapon\": {\"damage\": {\"die\": \"d6\", \"type\": \"Perfurante\", \"count\": 1, \"ability\": \"dexterity\", \"ability_custom\": null}, \"traits\": [{\"key\": \"finesse\", \"name\": \"Acuidade\", \"custom\": false, \"description\": \"Ao realizar um ataque com uma arma que possui Acuidade, você pode usar o modificador de Força ou de Destreza, à sua escolha, para as jogadas de ataque e dano. Você deve usar o mesmo modificador para ambas as jogadas.\"}, {\"key\": \"light\", \"name\": \"Leve\", \"custom\": false, \"description\": \"Quando você usa a ação Atacar no seu turno e ataca com uma arma Leve, pode fazer um ataque extra como uma Ação Bônus mais tarde no mesmo turno. Esse ataque extra deve ser feito com uma arma Leve diferente, e você não adiciona seu modificador de habilidade ao dano do ataque extra, a menos que esse modificador seja negativo.\"}, {\"key\": \"versatile\", \"name\": \"Versátil\", \"custom\": false, \"description\": \"Uma arma Versátil pode ser usada com uma ou duas mãos. Um valor de dano alternativo aparece associado à propriedade. A arma causa esse dano quando usada com as duas mãos para realizar um ataque corpo a corpo.\"}, {\"key\": \"thrown\", \"name\": \"Arremesso\", \"custom\": false, \"description\": \"Se uma arma possuir a propriedade Arremesso, você pode arremessá-la para realizar um ataque à distância e pode sacá-la como parte desse ataque. Se for uma arma corpo a corpo, use o mesmo modificador de habilidade para as jogadas de ataque e dano que usaria em um ataque corpo a corpo com essa arma.\"}], \"category\": \"simple\", \"masteries\": [], \"magic_bonus\": 0, \"weapon_type\": \"Galho\", \"extra_damage\": [], \"category_custom\": null}, \"features\": [{\"title\": \"Lei Cósmica\", \"usage\": {\"enabled\": false}, \"description\": \"Você tem +3 em testes de ataque contra o criador da árvore do Terror. Além disso, uma vez por turno ao acertar o criador da Arvore do Terror ele perde 50 PV (100 PV se for critico).\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-08-30 00:33:06','2026-08-30 00:33:06'),(34,10,'Manto do Arquimago','wonderful','Um fino roupão elegante feito de um tecido branco e caro, com detalhes em dourado. Enquanto você usa esse roupão, você ganha os seguintes benefícios:',NULL,1,NULL,1,1,'legendary',1,1,0,NULL,0,15,NULL,NULL,NULL,NULL,'{\"armor\": {\"base_ac\": 15, \"category\": \"custom\", \"armor_type\": \"Manto Magico\", \"magic_bonus\": 0, \"dexterity_cap\": 2, \"dexterity_mode\": \"full\", \"category_custom\": \"Manto\", \"ability_modifiers\": []}, \"nature\": \"wonderful\", \"features\": [{\"title\": \"Armadura\", \"usage\": {\"enabled\": false}, \"description\": \"Se você não estiver usando armadura, a sua classe de armadura é (15 + Destreza)\"}, {\"title\": \"Resistencia a Magia\", \"usage\": {\"enabled\": false}, \"description\": \"Você tem vantagem em salvamento contra magias e outros efeitos mágicos.\"}, {\"title\": \"Mago de Guerra\", \"usage\": {\"enabled\": false}, \"description\": \"Você ganha +2 nos testes de ataque e na CD de suas magias.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 05:26:21','2026-09-01 05:26:44'),(35,10,'Grimorio Porlain','wonderful','Este tomo antigo, de capa de couro vermelho e encadernado em tiras de platina escura, foi passado por gerações da linhagem Porlain, contendo conhecimentos arcanos anteriores a calamidade. Sussurros de magias perdidas ecoam por suas páginas, e sua lombada pulsa com luz residual das sombras.',NULL,1,NULL,1,1,'legendary',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Canalizador de Feitiços\", \"usage\": {\"enabled\": false}, \"description\": \"Você recebe um bônus de +3 nas jogadas de ataque com magias e na +3 CD para resistir às suas magias de mago. Além disso Você pode usar este livro como livro de magias e foco de conjuração.\"}, {\"title\": \"Reservatório de Conhecimento\", \"usage\": {\"enabled\": false}, \"description\": \"Você pode preparar 3 magias adicionais de mago por dia. Além disso quando usa recuperação arcana recupere 3 nível adicional de espaço de magia.\"}, {\"title\": \"Troca Equivalente\", \"usage\": {\"enabled\": false}, \"description\": \"Como ação bônus, você pode gastar um número de Dados de Vida igual ao dobro do nível do espaço de magia que deseja recuperar. Você recupera o espaço de magia imediatamente.\\r\\n\\r\\nExemplo: para recuperar um espaço de magia de 6º nível, você deve gastar 12 Dados de Vida. Esses dados são gastos e não podem ser usados para curar até o próximo descanso longo.\"}, {\"title\": \"Criação Dos Porlain\", \"usage\": {\"enabled\": false}, \"description\": \"Você sempre tem esses feitiços preparados, e eles não contam para o limite de feitiços que você pode preparar.\\r\\n- Porlain’s Falange De Sangue\\r\\n- Porlain’s Fortalecimento Bestial\\r\\n- Porlain’s Armadura De Sangue\\r\\n- Porlain’s Estrela Escarlate\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 05:48:20','2026-09-01 05:48:30'),(36,10,'Brinco de Penas Negras de Pegasus','wonderful','Um brinco de penas negras de Pegasus.',NULL,1,NULL,1,1,'uncommon',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Aumento em Inteligência\", \"usage\": {\"enabled\": false}, \"description\": \"Ao sintonizar com esse brinco, sua Inteligência aumenta para +2 podendo ir além de 20.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 05:49:19','2026-09-01 05:51:29'),(37,10,'Anel da Inteligência do Quebra Cabeça','wonderful','Este anel de ouro tem uma pedra de fluorita e é encantado para aguçar a mente de quem o usa.',NULL,1,NULL,1,1,'uncommon',0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Vantagem em Testes de Inteligência\", \"usage\": {\"max\": 3, \"current\": 3, \"enabled\": true, \"recovery\": \"dawn\", \"counter_mode\": \"spend\", \"recovery_custom\": null}, \"description\": \"O anel tem 3 cargas e recarrega 1d4 - 1 usos diários gastos ao amanhecer. Ao fazer um teste de Inteligência, você pode se dar vantagem gastando uma carga\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 06:10:15','2026-09-01 06:10:33'),(39,10,'Botas do Vigilante','wonderful','Botas velhas e confortáveis magicas.',NULL,1,NULL,0,1,'uncommon',0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Ajudinha na Iniciativa\", \"usage\": {\"max\": 1, \"current\": 1, \"enabled\": true, \"recovery\": \"dawn\", \"counter_mode\": \"spend\", \"recovery_custom\": null}, \"description\": \"Enquanto você calça essas botas, você sente o perigo constante. Após rolar iniciativa, você pode escolher rolar um d8 e adicionar ao valor total da sua rolagem. Uma vez usada, essa habilidade só poderá ser utilizada novamente após o proximo amanhecer.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 06:16:46','2026-09-01 18:43:51'),(40,10,'Olhos de Águia','wonderful','O que antes era um óculos, agora são lentes de contato magicas graças a incrível Agatha Velhart.',NULL,1,NULL,1,1,'uncommon',0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Visão de Águia\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto usa essas lentes, você tem vantagem em testes de Sabedoria (Percepção) que sejam sobre visão.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 06:26:25','2026-09-01 06:26:28'),(41,11,'Armadura de Placas Fortalecidas','wonderful','Armadura de placas que se adapta ao corpo do usuário.',NULL,1,NULL,1,1,'very_rare',1,1,0,NULL,0,20,NULL,NULL,NULL,NULL,'{\"armor\": {\"base_ac\": 18, \"category\": \"heavy\", \"armor_type\": \"Placas Fortalecidas\", \"magic_bonus\": 2, \"dexterity_cap\": 2, \"dexterity_mode\": \"none\", \"category_custom\": null, \"ability_modifiers\": []}, \"nature\": \"wonderful\", \"features\": [{\"title\": \"Placas Encantadas\", \"usage\": {\"enabled\": false}, \"description\": \"Esta armadura é encantada e fornece +2 na Classe de Armadura.\"}, {\"title\": \"Fortalecimento Físico\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver sintonizado com esta armadura, sua Força passa a ser 24 (+7).\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 07:00:44','2026-09-01 07:00:50'),(42,11,'Yamato','wonderful','Katana feita para os descendentes de Sul Khatesh, após a morte de Vincent Jagentoth, a Yamato despertou sua verdadeira forma.',NULL,1,NULL,1,1,'artifact',1,1,0,NULL,0,NULL,'1d10',3,3,NULL,'{\"nature\": \"wonderful\", \"weapon\": {\"damage\": {\"die\": \"d10\", \"type\": \"Cortante\", \"count\": 1, \"ability\": \"dexterity\", \"ability_custom\": null}, \"traits\": [{\"key\": \"finesse\", \"name\": \"Acuidade\", \"custom\": false, \"description\": \"Ao realizar um ataque com uma arma que possui Acuidade, você pode usar o modificador de Força ou de Destreza, à sua escolha, para as jogadas de ataque e dano. Você deve usar o mesmo modificador para ambas as jogadas.\"}], \"category\": \"martial\", \"masteries\": [{\"key\": \"push\", \"name\": \"Push\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma, pode empurrá-la até 10 pés em linha reta para longe de você, desde que ela seja de tamanho Grande ou menor.\"}, {\"key\": \"sap\", \"name\": \"Sap\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma, ela terá Desvantagem na próxima jogada de ataque que realizar antes do início do seu próximo turno.\"}, {\"key\": \"slow\", \"name\": \"Slow\", \"custom\": false, \"description\": \"Se você acertar uma criatura com esta arma e causar dano a ela, pode reduzir o Deslocamento dela em 10 pés até o início do seu próximo turno. Se a criatura for atingida mais de uma vez por armas com esta maestria, a redução de Deslocamento não ultrapassa 10 pés.\"}], \"magic_bonus\": 3, \"weapon_type\": \"Espada Longa\", \"extra_damage\": [], \"category_custom\": null}, \"features\": [{\"title\": \"Lamina Dormente (Dormente)\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto esta arma estiver no estado Dormente, ela é considerada mágica e concede um bônus de +1 nas jogadas de ataque e dano.\"}, {\"title\": \"Conjurar Espadas Espectrais (Dormente)\", \"usage\": {\"enabled\": false}, \"description\": \"Usando uma ação mágica, você conjura Quatro lâminas de energia pura que orbitam sua cabeça. As lâminas duram por 10 minuto ou até serem lançadas.\\r\\n\\r\\nCom uma ação bônus, você pode lançar uma das lâminas contra uma criatura que possa ver a até 60 pés. Faça uma jogada de ataque à distância usando o mesmo modificador de ataque da Yamato. Em caso de acerto, o alvo sofre 1d6 + 1 de dano de energia.\"}, {\"title\": \"Lamina Desperta (Desperta)\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver no estado Desperto, Yamato pulsa com o poder do vazio e concede um bônus de +2 nas jogadas de ataque e dano.\"}, {\"title\": \"Afiada Como uma Lamina (Desperta)\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver sintonizado com a Yamato em seu estado Dormente, seus sentidos e reflexos são aguçados por sua conexão com o vazio cortante. Sua Destreza aumenta em +2, até um máximo de 22.\"}, {\"title\": \"Gatilho Demoníaco (Desperta)\", \"usage\": {\"enabled\": false}, \"description\": \"Você desperta sua forma demoníaca, tornando-se um ser envolto por energia demoníaca pura. Essa transformação dura 10 minutos e requer concentração, como se estivesse mantendo uma magia.\\r\\n\\r\\nVocê ativa essa habilidade como uma Ação Bônus. Enquanto estiver transformado, você recebe os seguintes\\r\\nbenefícios:\\r\\n- Seu deslocamento aumenta em +3 metros (10ft).\\r\\n- Você ganha um deslocamento de voo igual ao seu deslocamento padrão.\\r\\n- Sua Classe de Armadura aumenta em +2.\\r\\n- Você ganha resistência a dano cortante, perfurante e de impacto não mágico.\\r\\n- Você se torna imune a dano de fogo e veneno.\\r\\n- O seu primeiro ataque no seu turno causa um dano extra de 2d6 fogo.\\r\\n\\r\\nO Preço\\r\\nUsar essa transformação esgota completamente o seu lado humano. Caso a transformação acabe mais cedo, ou o tempo dela se esgote, você ganha 2 ponto de exaustão. Caso você ative novamente o gatilho demoníaco enquanto ainda tiver os pontos de exaustão, eles são suprimidos enquanto a forma estiver ativa.\"}, {\"title\": \"Lamina Exaltada (Exaltada)\", \"usage\": {\"enabled\": false}, \"description\": \"Enquanto estiver no estado Exaltada, Yamato revela sua verdadeira forma e concede um bônus de +3 nas jogadas de ataque e dano.\"}, {\"title\": \"Dilacerar o Véu da Realidade (Exaltada)\", \"usage\": {\"max\": 2, \"current\": 2, \"enabled\": true, \"recovery\": \"day\", \"counter_mode\": \"spend\", \"recovery_custom\": null}, \"description\": \"Usando uma Ação Mágica, você corta o tecido das realidades em até 7 pontos diferentes, permitindo que você e até 7 criaturas voluntárias a até 60 ft de você sejam transplanadas para qualquer plano de existência que você conheça. Você pode especificar o destino em termos gerais (como Cidade Do Panteão no Monte Celestia), surgindo exatamente no local ou o mais próximo possível dele.\"}, {\"title\": \"Gatilho Demoníaco: Modo Pecado Abyssal (Exaltada)\", \"usage\": {\"enabled\": false}, \"description\": \"No início do seu turno, enquanto mantém a concentração no Gatilho Demoníaco, você pode escolher se entregar por  completo ao seu sangue demoníaco. Fazer isso, ativa o Modo Pecado Abissal:\\r\\n- A duração do gatilho demoníaco se torna 2d4 + 1 rodadas e você não precisa mais se concentrar nela enquanto o\\r\\nModo Pecado estiver ativo.\\r\\n- Pela duração do gatilho demoníaco a sua ficha é trocada pela ficha do Pecado Abyssal, todos os seus itens ficam inertes e você não pode usar habilidades de classe ou subclasse.\\r\\n- Você permanece nesta forma até que o tempo se esgote ou que os Pontos de Vida da ficha cheguem a 0.\\r\\n\\r\\nQuando você retorna a sua forma original, você fica com 5 pontos de Exaustão e 1 Ponto de Vida Atual e Máximo (Os pontos de vida máximos são restaurados ao terminar um descanso longo).\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 07:33:56','2026-09-01 07:34:03'),(43,11,'Manto da Proteção','wonderful','Um manto negro feito para Veronika Jagentoth.',NULL,1,NULL,1,1,'uncommon',1,1,0,NULL,0,NULL,NULL,NULL,NULL,NULL,'{\"nature\": \"wonderful\", \"features\": [{\"title\": \"Proteção\", \"usage\": {\"enabled\": false}, \"description\": \"Ao usar esta capa você ganha +1 de bonus na sua CA e em seus Testes de Salvamentos.\"}], \"inventory\": {\"equippable\": true}, \"custom_properties\": []}',NULL,NULL,'2026-09-01 07:36:57','2026-09-01 07:37:01');
