INSERT INTO `character_party_notes` VALUES (1,1,4,NULL,'[{\"id\": \"11be72a2-821d-4980-8fef-6b87678fa69c\", \"seen\": true, \"emoji\": \"💀\", \"message\": \"Seu inventário já tem herdeiro?\", \"seen_at\": \"2026-09-01T16:14:00.610518Z\", \"created_at\": \"2026-09-01T16:13:54.780741Z\", \"from_character_id\": 11, \"from_character_name\": \"Veronika Jagentoth\"}, {\"id\": \"d9866590-beb1-4b48-b899-7e4d62260b86\", \"seen\": true, \"emoji\": \"👉\", \"message\": \"Tô falando com você!\", \"seen_at\": \"2026-09-01T16:14:10.010348Z\", \"created_at\": \"2026-09-01T16:14:08.962468Z\", \"from_character_id\": 11, \"from_character_name\": \"Veronika Jagentoth\"}, {\"id\": \"ee2b2566-2a2f-4bbc-b85b-c8045e8b85e8\", \"seen\": true, \"emoji\": \"❤️\", \"message\": \"Mais um turno. Você consegue.\", \"seen_at\": \"2026-09-01T16:14:29.997214Z\", \"created_at\": \"2026-09-01T16:14:28.147511Z\", \"from_character_id\": 11, \"from_character_name\": \"Veronika Jagentoth\"}, {\"id\": \"60ede46b-e9f5-497a-b0f1-f9e80c561bd9\", \"seen\": true, \"emoji\": \"🔥\", \"message\": \"Cinema.\", \"seen_at\": \"2026-09-01T16:14:37.996321Z\", \"created_at\": \"2026-09-01T16:14:37.760967Z\", \"from_character_id\": 11, \"from_character_name\": \"Veronika Jagentoth\"}, {\"id\": \"e4fdd2fa-d995-4d7f-823e-7fd2e94de7ac\", \"seen\": true, \"emoji\": \"👀\", \"message\": \"Dois olhos. Zero confiança.\", \"seen_at\": \"2026-09-01T16:16:27.555229Z\", \"created_at\": \"2026-09-01T16:16:17.748159Z\", \"from_character_id\": 11, \"from_character_name\": \"Veronika Jagentoth\"}, {\"id\": \"e477bd89-41d1-49c8-9297-7858524a4c7c\", \"seen\": true, \"emoji\": \"🔥\", \"message\": \"Irado!\", \"seen_at\": \"2026-09-01T16:16:27.555325Z\", \"created_at\": \"2026-09-01T16:16:24.942287Z\", \"from_character_id\": 11, \"from_character_name\": \"Veronika Jagentoth\"}, {\"id\": \"55c17de7-01bc-4012-a7de-2eb47aa281f0\", \"seen\": true, \"emoji\": \"👉\", \"message\": \"Psiu!\", \"seen_at\": \"2026-09-01T16:16:47.235295Z\", \"created_a