INSERT INTO `npc_builder_drafts` VALUES (10,2,'{\"speed\": {\"fly\": 0, \"swim\": 0, \"walk\": 55, \"climb\": 0, \"hover\": false, \"burrow\": 0, \"hasJumps\": true, \"jumpVerticalBonus\": 5, \"jumpHorizontalBonus\": 15}, \"combat\": {\"senses\": {\"truesight\": 0, \"blindsight\": 0, \"darkvision\": 120, \"tremorsense\": 0}, \"ac_base\": 19, \"ac_type\": null, \"hit_die\": \"d10\", \"hp_mode\": \"average\", \"ac_bonus\": 0, \"custom_hp\": 10, \"languages\": [], \"immunities\": [], \"resistances\": [\"fire\", \"Impacto, Cortante e perfurante de armas não Mágicas ou de prata.\"], \"customSenses\": [], \"hp_mod_extra\": 122, \"hit_dice_count\": 25, \"vulnerabilities\": [], \"conditionImmunities\": [\"charmed\", \"frightened\"], \"passivePerceptionBonus\": 0}, \"format\": \"npc-builder\", \"header\": {\"name\": \"Domingos Semanas\", \"size\": \"large\", \"types\": [\"humanoid\", \"dragon\"], \"languages\": [\"common\", \"draconic\"], \"alignments\": [\"chaotic_neutral\"], \"languageCustom\": null, \"challengeRating\": \"22\"}, \"skills\": [{\"key\": \"acrobatics\", \"bonus\": 0, \"label\": \"Acrobacia\", \"ability\": \"dex\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"animalHandling\", \"bonus\": 0, \"label\": \"Adestrar Animais\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"arcana\", \"bonus\": 0, \"label\": \"Arcanismo\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"athletics\", \"bonus\": 0, \"label\": \"Atletismo\", \"ability\": \"str\", \"enabled\": false, \"expertise\": false, \"proficient\": true}, {\"key\": \"deception\", \"bonus\": 0, \"label\": \"Enganação\", \"ability\": \"cha\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"history\", \"bonus\": 0, \"label\": \"História\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": true}, {\"key\": \"insight\", \"bonus\": 0, \"label\": \"Intuição\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"intimidation\", \"bonus\": 0, \"label\": \"Intimidação\", \"ability\": \"cha\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"investigation\", \"bonus\": 0, \"label\": \"Investigação\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": true}, {\"key\": \"medicine\", \"bonus\": 0, \"label\": \"Medicina\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"nature\", \"bonus\": 0, \"label\": \"Natureza\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"perception\", \"bonus\": 0, \"label\": \"Percepção\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": true}, {\"key\": \"performance\", \"bonus\": 0, \"label\": \"Performance\", \"ability\": \"cha\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"initiative\", \"bonus\": 0, \"label\": \"Iniciativa\", \"ability\": \"dex\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"persuasion\", \"bonus\": 0, \"label\": \"Persuasão\", \"ability\": \"cha\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"religion\", \"bonus\": 0, \"label\": \"Religião\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"sleightOfHand\", \"bonus\": 0, \"label\": \"Prestidigitação\", \"ability\": \"dex\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"stealth\", \"bonus\": 0, \"label\": \"Furtividade\", \"ability\": \"dex\", \"enabled\": false, \"expertise\": false, \"proficient\": true}, {\"key\": \"survival\", \"bonus\": 0, \"label\": \"Sobrevivência\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": true}], \"actions\": [{\"id\": \"1787063637107-da2eef2067c16\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Maldição do Lycan: O Uivo\", \"content\": \"<p>Domingos solta um uivo amaldiçoado e ensurdecedor que reverbera nos ossos e mentes das criaturas. Todas as criaturas em um raio de <strong>60 ft </strong>que possam ouvi-lo devem realizar um Salvamento de Sabedoria <strong>(CD 21). </strong>Em caso de falha, a criatura fica Assustado por <strong>1 Minuto</strong>. Caso o alvo falhe por <strong>4 </strong>ou mais, o alvo fica <strong>Atordoado </strong>e <strong>Assustado</strong>. Os alvos podem repetir o salvamento no final de cada um de seus turnos, encerrando o efeito em si mesma em caso de sucesso.</p>\", \"tracker\": {\"max\": 6, \"min\": 5, \"uses\": 0, \"reset\": \"recharge\", \"title\": null, \"enabled\": true, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"attacks\": [{\"id\": \"1787063873119-cd60d48f0bd82\", \"mode\": \"text\", \"title\": \"Garras de Lycan\", \"builder\": {\"range\": \"melee\", \"reach\": 5, \"damages\": [{\"id\": \"1787063873119-50dffc1c5c5b28\", \"die\": \"d6\", \"type\": \"slashing\", \"count\": 1, \"extra\": 0, \"ability\": \"str\"}], \"effects\": [], \"targets\": \"Um alvo\", \"attackType\": \"weapon\", \"proficiency\": true, \"attackAbility\": \"str\", \"extraHitBonus\": 0}, \"content\": \"<p>Ataque Desarmado: <strong>+19&nbsp;</strong>Acerto, Alcance <strong>5 ft</strong>. Dano: <strong>22 (2d8+13) </strong>Cortante + 10 (2d8) Psíquico, Se na <strong>Segunda forma </strong>+ 15 (3d8) Fogo e fica <strong>Queimando</strong>. Após acertar um alvo Domingos pode escolher aplicar um dos seguintes efeitos:&nbsp;</p><p>&nbsp; &nbsp;<strong>Derrubar:</strong> O alvo deve ser bem sucedido em um Salvamento de Força <strong>(CD23)</strong>. Em caso de falha cai Deitado <strong><em>(Prone)</em></strong>.</p><p>&nbsp;<strong>&nbsp; Agarrar: </strong>Domingos faz um teste contestado de <strong>Atletismo </strong>contra <strong>Atletismo/Acrobacia </strong>do alvo. Se Domingos ganhar, o alvo fica agarrado.</p><p>&nbsp; &nbsp;<strong>Maldição Do Predador: </strong>Domingos pode escolher Amaldiçoar o alvo, ele só pode ter um alvo Amaldiçoado por vez. A maldição dura até ser dissipada <strong>(Dispel = CD19).</strong></p>\"}], \"version\": 1, \"features\": [{\"id\": \"1787063032122-f5189684b0703\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Ampulheta\", \"content\": null, \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 7, \"reset\": null, \"title\": null, \"enabled\": true, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063053147-419b563f8453e8\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Força de Lobisomen\", \"content\": \"<p>Domingos tem vantagem em todos os <strong>Testes </strong>e <strong>Salvamentos</strong> de Força.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063074435-216b17a7a9c428\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Maldição do Predador\", \"content\": \"<p>Uma criatura amaldiçoada por Domingos sofre as seguintes penalidades:&nbsp;<br><strong>&nbsp; &nbsp; &nbsp;Punição Psíquica: </strong>Se a criatura causar dano a Domingos enquanto estiver a até <strong>30 ft</strong> dele, o alvo recebe <strong>10 </strong>de dano Psíquico para cada ataque ou feitiço desferido.&nbsp;<br><strong>&nbsp; &nbsp; &nbsp;/Foco Predatório: </strong>Domingos possui <strong>Vantagem </strong>em todos os testes de ataque contra a criatura amaldiçoada.&nbsp;<br><strong>&nbsp; &nbsp; &nbsp;Presa Encurralada: </strong>Se a criatura tentar realizar a ação de <strong>Disparada, Desengajar </strong>ou tentar <strong>Teletransportar </strong>de qualquer maneira, ela sofre primeiro <strong>13 (4d6) </strong>de dano Psíquico e deve realizar um Salvamento de Sabedoria <strong>(CD 20)</strong>. Em caso de falha, a ação é desperdiçada, o teletransporte falha e o deslocamento do alvo é reduzido a <strong>0 </strong>até o início do seu próximo turno.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063311036-0ef8b9fd2a0e58\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Mestre do Sangue\", \"content\": \"<p>Sempre que Domingos realizar um <strong>acerto critico</strong>, ele recupera um uso de uma de suas seguintes habilidades: <strong>Maldição Do Sem Olhos</strong> ou Maldição Do Lycan: <strong>O Uivo.</strong></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063375594-a1f82dfd977548\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Predador Agarrador\", \"content\": \"<p>Domingos não sofre penalidades em seu deslocamento por carregar<strong> criaturas agarradas</strong>, movendo-se livremente pelo campo de batalha. Além disso, ele possui <strong>Vantagem</strong> em todos os testes de ataque contra criaturas que estejam agarradas por ele.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063422780-ab4cf27f66f53\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Regeneração Lycan (217PV ou Menos)\", \"content\": \"<p>Enquanto estiver abaixo da metade de seus pontos de vida máximos <strong><em>(sangrando)</em></strong>, Domingos regenera <strong>26 PV</strong> no início de cada um de seus turnos. Essa regeneração é interrompida até o final do próximo turno dele caso Domingos sofra dano de uma arma de <strong>Prata Pura</strong>, sendo esta a única forma de cessar sua recuperação vital..</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063442127-1719dc3bcd7fb8\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Resistencia Lendária\", \"content\": \"<p>Domingos pode escolher passar em qualquer salvamento feito.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 6, \"reset\": null, \"title\": null, \"enabled\": true, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063476441-a142e4ff37ba7\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Sede de Sangue\", \"content\": \"<p>Sempre que Domingos iniciar o turno com menos da metade dos seus pontos de vida ele deve ser bem sucedido em um salvamento de Sabedoria CD 10, Domingos tem vantagem para realizar esse salvamento, no caso de falha nesse turno domingos só irar usar a ação atacar na criatura mais proxima dele.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063495905-35d95e485c8ae\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Segunda Forma\", \"content\": \"<p>Quando seu Domingos chegar a 217 pontos de vida ou menos ele engole a ampulheta e explode em chamas ativando os efeitos, <strong>Auge Efêmero,</strong>&nbsp;<strong>Churrascos de Domingo e Forma Espectral do Gigante, </strong>utilizando a habilidade <strong>Uivo</strong>&nbsp;e junto emitindo uma&nbsp;explosão de fogo em uma área de 18m salvamento de <strong>DEX CD 17 </strong>Metade do dano quem passar <strong>8d6 de dano de fogo</strong>:<br>Enquanto em chamas recebe os seguintes efeitos:<br>+2 de CA.<br>A Distancia do seu pulo é dobrada.<br></p><p>Imunidade a dano de Fogo e Frio.</p><p>Visão as Cegas de 9m.<br>Todo dano de fogo direcionado a você é reduzido a metade e convertido em cura.<br>Todos seus ataques dão 3d8 de dano de fogo adicional e deixam a criatura <strong>Queimando</strong>.&nbsp;<br>a Criatura <strong>Queimando </strong>sofre 1d8 de dano de fogo no inicio do seu turno, usar uma ação para apagar o fogo.<br>Qualquer criatura que Iniciar o turno a<strong> 6m</strong> dele sofre <strong>10 de dano de fogo</strong>.<br>Todo inicio de turno Domingos cura&nbsp;<strong>1d10 de dano de fogo</strong> que não pode ser reduzido.<br>O fogo é Mágico e só pode ser dissipado por uma magia de 9° nivel ou maior.</p><p>Criaturas que te atacarem corpo-a -corpo devem ser bem sucedidos em um salvamento de Dex CD 18 ou sofre 2d12 de dano de fogo, metade se tiver sucesso.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063618201-a197d3e25de84\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Sentidos Aguçados\", \"content\": \"<p>Domingos tem vantagem em todos os testes de Percepção para ouvir ou farejar.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"sections\": [], \"abilities\": {\"cha\": 10, \"con\": 24, \"dex\": 20, \"int\": 20, \"str\": 25, \"wis\": 14}, \"reactions\": [{\"id\": \"1787064032288-c506baf36084\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Maldição de Sangue dos Sem Olhos\", \"content\": \"<p>Quando uma criatura a até 60 ft realiza um teste de ataque contra Domingos, ele solta um latido aterrorizante que estremece os olhos do agressor dentro do crânio. O alvo sofre uma penalidade de -1d10 em todos os seus testes de ataque até o início do próximo turno de Domingos.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 3, \"reset\": null, \"title\": null, \"enabled\": true, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787064048009-934cbc8e8efd2\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Resistencia Cromática\", \"content\": \"<p>Ao sofrer dano, Domingos pode escolher ganhar Resistência ao tipo de dano recebido (Fogo, Gelo, Ácido, Veneno, Elétrico ou Trovão). Esta resistência permanece ativa até o início de seu próximo turno.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"lairActions\": [{\"id\": \"1787064329747-edd453d24541b\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa até 2 ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Trombeta de Combate 1/\", \"content\": \"<p><strong>JoanesBurgo </strong>usa <strong>O Chifre de Valhala, Ferro</strong> e invoca <strong>5 Berserks</strong> dentro de 60ft, eles permanecem por 1h ou até serem reduzidos a 0 pontos de vida, são imunes a Amedrontado e Encantado e precisam respirar.</p><p></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787064440895-cc79862ea641e8\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Conselheiro Divino 1/\", \"content\": \"<p>Joanes Burgo se aproxima de domingos curando 100 pontos de vida e fazendo seu domingos retomar o controle da <strong>Sede de Sangue.</strong></p><ul><li><p></p></li></ul><p></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787064469847-f470c19ae2a41\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Restauração Divina 2/\", \"content\": \"<p>JoanesBurgo lança a magia <strong>Restauração Maior </strong>em Seu domingos.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787065473830-73f51496311fa\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Enxames de NecroCorvos 5/\", \"content\": \"<p><br><strong>Flecha da Senhora dos Corvos.</strong> Dois Enxame de Corvos disparam em direção a uma criatura dentro de 120ft, o alvo deve ser bem sucedido em um <strong>salvamento de Constituição (CD 22)</strong> ou sofre<strong> 22 (4d10) de dano necrótico</strong> e torna-se vulnerável a um dos seguintes tipos de dano à sua escolha: ácido, frio, fogo, relâmpago, necrótico, radiante ou trovão <strong>(Custo 2 Uso).</strong><br><strong>Consumir Magia.</strong> Os Corvos neutralizam um Efeito Mágico dentro da área, funciona como um <strong>Dispel Magi</strong>c, +7 se for necessário teste para dissipar, </p><p></p><p></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787066240842-9471014bd98a4\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"By Your Side 2/\", \"content\": \"<p>JoanesBurgo se move ao lado de seu domingos aguardando o momento certo para agir.<br><strong>Divine Smite 5° Nivel. </strong>JoanesBurgo conjura <strong>Divine Smite de 5° Nivel</strong> junto ao ataque de Domingos causando <strong>36(8d8) dano Radiante Adicional - 2</strong>. <br><strong>Golpe Supremo.</strong> JoanesBurgo conjura <strong>Supremal Smite de 5°Nivel </strong>junto ao ataque de Domingos causando <strong>18(5d6) dano de Força</strong> e <strong>Dissipando todas magias de 4°Nível ou inferior </strong>que estão no alvo, para cada <strong>magia de 5° Nível ou Maior</strong> deve ser feito uma rolagem de d20+5, a CD para dissipar a magia é 10 + o nivel da magia.<br></p><p></p><p></p><p></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787070536410-06d205f45bec\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Ao seu Lado\", \"content\": \"<p>JoanesBurgo se move ao lado de seu domingos aguardando o momento certo para agir.<br><strong>Divine Smite 3° Nivel.</strong> JoanesBurgo conjura <strong>Divine Smite de 3° Nivel</strong> junto ao ataque de Domingos causando <strong>22(5d8) dano Radiante Adicional</strong><br><strong>Proteção. </strong>JoanesBurgo<strong> </strong>da <strong>50 de PV temporário</strong> para seu Domingos até o inicio do proximo turno.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"bonusActions\": [{\"id\": \"1787063796174-4ee4cd299441f8\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Maldição de Sangue da Mente Confusa\", \"content\": \"<p>Você amaldiçoa uma criatura dentro de 9m: A criatura amaldiçoada tem desvantagem em todos os testes de resistência de Constituição feitos para manter a concentração até o final do seu próximo turno.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787063816755-7bf3df5dd56b88\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Robusto\", \"content\": \"<p>Domingos se concentra em se curar de suas feridas. Ele regenera imediatamente <strong>26 (1d10+21) </strong>pontos de vida.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 25, \"reset\": null, \"title\": null, \"enabled\": true, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"multiAttacks\": [{\"id\": \"1787064077673-5b4dfc2dd64d38\", \"mode\": \"custom\", \"title\": \"Multiataque\", \"entries\": [], \"customText\": \"Domingos Semanas faz 3 ataques com Garras de Lycan. se estiver na Segunda Forma ele ataca 4 Vezes.\"}], \"savingThrows\": {\"cha\": {\"bonus\": 1, \"enabled\": false, \"proficient\": false}, \"con\": {\"bonus\": 6, \"enabled\": false, \"proficient\": false}, \"dex\": {\"bonus\": 4, \"enabled\": false, \"proficient\": true}, \"int\": {\"bonus\": 0, \"enabled\": false, \"proficient\": true}, \"str\": {\"bonus\": 7, \"enabled\": false, \"proficient\": false}, \"wis\": {\"bonus\": 7, \"enabled\": false, \"proficient\": false}}, \"mythicActions\": [], \"legendaryActions\": [{\"id\": \"1787064149227-0a08bbb61cb65\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Ataque Predatório\", \"content\": \"<p>Domingos se move até <strong>55ft e então realiza Dois (2) </strong>ataques usando Garras De Lycan.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"Domingos possui 2+1 por resistência lendária restante de ações lendárias, podendo usar uma delas no final do turno de uma criatura.\", \"enabled\": false, \"totalActions\": 2}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787064212544-56999a1ccf328\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Devorar\", \"content\": \"<p>Domingos morde um alvo adjacente com um ataque de <strong>+19&nbsp;</strong>para acertar e alcance de <strong>5 ft</strong>, causando <strong>35 (5d8 + 13)</strong> de dano perfurante. Domingos recupera uma quantidade de pontos de vida igual a metade do dano total causado por esse ataque.</p><p><br></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": null, \"title\": null, \"enabled\": false, \"customReset\": null}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787064250973-2527002210045\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Dilacerar (Custa 2 Ações)\", \"content\": \"<p>Domingos avança <strong>55ft </strong>em direção a uma criatura caí­da <strong>(prone)</strong> e, se terminar o movimento adjacente a ela, desfere um golpe de misericórdia usando <strong>Garras De Lycan </strong>com margem de Crí­tico <strong>(17-20)</strong>. Em caso de acerto, o alvo deve ser bem-sucedido em um Salvamento de Constituição <strong>(CD 20) </strong>ou será <strong><em>Estripado</em></strong>, sofrendo imediatame