INSERT INTO `npcs` VALUES (1,1,8,'Lily Verhart','','humanoid','Medium','',21,22.00,85,'{\"AC\": 21, \"CR\": 22, \"HP\": {\"HD\": 19, \"type\": 4, \"modifier\": 38}, \"name\": \"Lily Verhart\", \"size\": \"Medium\", \"type\": \"humanoid\", \"saves\": {\"CHA\": {\"override\": false, \"proficient\": true, \"overrideValue\": 0}, \"CON\": {\"override\": false, \"proficient\": false, \"overrideValue\": 0}, \"DEX\": {\"override\": false, \"proficient\": false, \"overrideValue\": 0}, \"INT\": {\"override\": false, \"proficient\": true, \"overrideValue\": 0}, \"STR\": {\"override\": false, \"proficient\": false, \"overrideValue\": 0}, \"WIS\": {\"override\": false, \"proficient\": true, \"overrideValue\": 0}}, \"stats\": {\"CHA\": 23, \"CON\": 15, \"DEX\": 18, \"INT\": 20, \"STR\": 9, \"WIS\": 9}, \"ACType\": \"\", \"lairCr\": -1, \"senses\": {\"truesight\": 60, \"blindsight\": 0, \"darkvision\": 120, \"tremorsense\": 0}, \"skills\": [{\"key\": \"ARCANA\", \"skill\": {\"stat\": \"INT\", \"label\": \"Arcana\"}, \"override\": false, \"expertise\": true, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"DECEPTION\", \"skill\": {\"stat\": \"CHA\", \"label\": \"Deception\"}, \"override\": false, \"expertise\": false, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"HISTORY\", \"skill\": {\"stat\": \"INT\", \"label\": \"History\"}, \"override\": false, \"expertise\": false, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"INTIMIDATION\", \"skill\": {\"stat\": \"CHA\", \"label\": \"Intimidation\"}, \"override\": false, \"expertise\": false, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"MEDICINE\", \"skill\": {\"stat\": \"WIS\", \"label\": \"Medicine\"}, \"override\": false, \"expertise\": false, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"NATURE\", \"skill\": {\"stat\": \"INT\", \"label\": \"Nature\"}, \"override\": false, \"expertise\": false, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"SLIGHT_OF_HAND\", \"skill\": {\"stat\": \"DEX\", \"label\": \"Sleight of Hand\"}, \"override\": false, \"expertise\": false, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"STEALTH\", \"skill\": {\"stat\": \"DEX\", \"label\": \"Stealth\"}, \"override\": false, \"expertise\": true, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"SURVIVAL\", \"skill\": {\"stat\": \"WIS\", \"label\": \"Survival\"}, \"override\": false, \"expertise\": false, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"RELIGION\", \"skill\": {\"stat\": \"INT\", \"label\": \"Religion\"}, \"override\": false, \"expertise\": true, \"proficient\": true, \"overrideValue\": 0}, {\"key\": \"INVESTIGATION\", \"skill\": {\"stat\": \"INT\", \"label\": \"Investigation\"}, \"override\": false, \"expertise\": true, \"proficient\": true, \"overrideValue\": 0}], \"speeds\": [{\"id\": \"bb8fced8-522a-4f3d-8741-8b909b165422\", \"note\": \"\", \"type\": \"walk\", \"speed\": 30}], \"traits\": [{\"id\": \"8e7f3903-2c62-4d6f-9ac0-0d767bf2c7c3\", \"name\": \"Pacto Das Fadas\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Lily não pode dormir, invés disso ela deve fazer atividades leves por <b>4</b> horas para ganhar o benefício de um descanso longo. Além disso ela não fica desacordada quando está morrendo, podendo agir normalmente.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"abc157c1-cb12-4a53-ba86-eb2326a53790\", \"name\": \"Destruição Mística ____4\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Após acertar um ataque com Óxidos, Lily pode desferir uma explosão de energia no golpe que causa <b>22 (5d8) </b>de Energia. Além disso o alvo deve ser bem sucedido em um salvamento de Força <b>(CD23)</b> ou cai deitado.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}], \"actions\": [{\"id\": \"1a52be38-f6bb-49a9-a21b-dafd2c793f62\", \"name\": \"Conjuração (Pacto Do Abysmo)\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": false, \"description\": \"Lily pode conjurar um dos seguintes feitiços usando <b>Carisma</b> como canalização (<b>+15</b>&nbsp;para acertar, <b>CD 23</b>):<div><br></div><div><b>À Vontade:</b> Ilusão Menor, Invisibilidade.</div><div><b>5º Nível (3/Dia)____ :</b> Escalada de Aranha, Sugestão, Contra Feitiço.</div><div><b>6º Nível (1/Dia)____ :</b> Life Drain.</div><div><b>7º Nível (1/Dia)____ :</b>&nbsp;Teletransplanar.</div><div><b>8º Nível (1/Dia)____ :</b> Abi-Dalzim\'s Horrid Wilting.</div><div><b>9º Nível (1/Dia)____ :</b> Blade Of Disaster.</div>\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}, {\"id\": \"83b8ee47-3bc2-4d31-97f5-82a802de5e2b\", \"name\": \"Vociferar Pragas ____3\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"description\": \"Um alvo que Lily possa ver em até <b>120ft </b>é amaldiçoado por <b>1 </b>Hora. Enquanto estiver amaldiçoado dessa forma, Lily ganha os seguintes benefícios contra o alvo:&nbsp;&nbsp;<div><br></div><div><i>*A margem de critico contra ele vira <b>19/20</b>.</i></div><div><i>*Caso o alvo morra, Lily recupera <b>30PV </b>e a maldição passa para outra criatura em até <b>120ft</b>.</i></div><div><i>*Lily causa <b>+5</b> de dano no alvo em cada ataque.</i></div><div><i>*Você pode usar as Habilidades <b>Armadura De Maldições </b>e <b>Sussurros Infernais</b></i></div><div><br></div><div>Lily pode ter vários alvos amaldiçoados ao mesmo tempo.</div>\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}, {\"id\": \"a8a7bf41-ec9a-4a3e-88dd-a52245812bcf\", \"name\": \"Sussurros Infernais\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"description\": \"Todos os alvos amaldiçoados devem ser bem sucedidos em um salvamento de Inteligência <b>(CD23). </b>Em caso de falha recebem <b>21 </b>(<b>6d6)&nbsp;</b>Dano Psíquico e caem deitados. Se passarem recebem apenas metade desse dano <b>(10).&nbsp;</b>\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}], \"attacks\": [{\"id\": \"afae2094-94a8-4f04-861d-7674ef22e8e8\", \"kind\": \"WEAPON\", \"name\": \"Óxidos\", \"save\": 0, \"range\": {\"long\": 60, \"reach\": 5, \"standard\": 20}, \"damage\": {\"dice\": 8, \"type\": \"Necrotic\", \"count\": 4, \"modifier\": {\"stat\": \"CHA\", \"override\": true, \"overrideValue\": 10}}, \"targets\": 1, \"distance\": \"MELEE\", \"modifier\": {\"stat\": \"CHA\", \"override\": true, \"proficient\": true, \"overrideValue\": 15}, \"description\": \"\", \"legendaryOnly\": false, \"customRenderer\": \"<b>Óxidos.</b> Ataque com arma corpo a corpo: <b>+15 </b>Acerto, Alcance <b>5 ft</b>., Um alvo. Dano: <b>28</b> <b>(4d8+10) </b>Necrótico. Após acertar o golpe, Lily recupera <b>9 (2d8) </b>pontos de vida.\", \"alternateDamage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 1, \"active\": false, \"modifier\": {\"stat\": \"STR\", \"override\": false, \"overrideValue\": 0}, \"condition\": \"\"}, \"additionalDamage\": [], \"useCustomRenderer\": true}, {\"id\": \"110fe861-b759-499b-b9f6-355bfd52d6d2\", \"kind\": \"SPELL\", \"name\": \"Raio Místico\", \"save\": 0, \"range\": {\"long\": 120, \"reach\": 5, \"standard\": 120}, \"damage\": {\"dice\": 10, \"type\": \"slashing\", \"count\": 1, \"modifier\": {\"stat\": \"CHA\", \"override\": false, \"overrideValue\": 0}}, \"targets\": 1, \"distance\": \"RANGED\", \"modifier\": {\"stat\": \"CHA\", \"override\": false, \"proficient\": true, \"overrideValue\": 0}, \"description\": \"\", \"legendaryOnly\": false, \"customRenderer\": \"<b>Raio Místico</b>. Ataque Mágico a Distancia: +15 Acerto, Alcance <b>120 ft</b>., Um alvo. Acerto: <b>11 (1d10+6)</b> Energia. Após acertar um raio, Lily pode empurrar ou puxar a criatura <b>10ft.</b>\", \"alternateDamage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 1, \"active\": false, \"modifier\": {\"stat\": \"STR\", \"override\": false, \"overrideValue\": 0}, \"condition\": \"\"}, \"additionalDamage\": [], \"useCustomRenderer\": true}], \"nickname\": \"\", \"alignment\": \"\", \"inventory\": \": Óxidos\", \"languages\": \"Comum, Celestial, Infernal, Abyssal.\", \"reactions\": [{\"id\": \"d6e3b212-976c-419c-b600-ef5af63973b7\", \"name\": \"Armadura De Maldições\", \"trigger\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Se um alvo amaldiçoado por Lily realizar um ataque contra ela, role <b>1d6</b> em um resultado <b>2/6</b> o ataque erra.\"}], \"conditions\": [\"Unconscious\", \"Sleep\", \"Incapacitated\"], \"crOverride\": \"\", \"immunities\": [], \"lairCrNote\": \"in lair\", \"alphaTraits\": true, \"lairActions\": [], \"proficiency\": 6, \"resistances\": [\"Fogo, Gelo, Necrótico e Radiante \"], \"saveVersio