30}], \"traits\": [{\"id\": \"ea60d0a9-5346-4ea6-a32d-18661d1ac11c\", \"name\": \"Imediato\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Orly soma <b>+15</b> em todos os seus testes feitos para navegar embarcações.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}], \"actions\": [{\"id\": \"98df6cc7-e0a1-4c41-ae18-dd554916c2e1\", \"name\": \"Canção Dos Mares ____/2\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"description\": \"Orly inicia um coral pirata. Todas as criaturas à sua escolha que puderem ouvi-lo em um raio de <b>60 ft,</b>&nbsp;podem usar sua <b>Reação </b>para cantarolar junto o seguinte verso:<div><br></div><div>&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <i>\\\"Pelas ondas que partem, pro destino que vem, Onde o ouro reluz mas a morte também! Heyy, eu brindo o mar, e sorte também.\\\"</i>&nbsp;<div><br></div><div><br></div><div>Todas as criaturas que participarem do coral ganham <b>4 Inspirações Marítimas</b>. Durante os próximos 10 minutos, o alvo pode gastar uma Inspiração Marítima para adicionar <b>1d6 </b>a qualquer rolagem de <b>d20</b> que realizar.</div></div>\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}, {\"id\": \"f0129a74-bb9e-4f25-8354-e57b6e6a8970\", \"name\": \"Conjuração\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusActio