Save\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"0a3932c4-03a0-4a95-a093-c6cc09e1aadd\", \"name\": \"Aura De Azar\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Nenhuma criatura consegue ter vantagem em testes de ataque contra Xandis. Além disso, qualquer critico acertado contra Xandis é anulado.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"9fa63700-761d-424c-a398-42485f1b7e95\", \"name\": \"Mestre Duelista\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Após acertar um alvo com um ataque corpo a corpo, aquela criatura não pode realizar ataques de oportunidades contra Xandis até o final do turno.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"7c380d6e-3f0b-4cb9-bdc8-85c7b8734874\", \"name\": \"Capitão Da Prata e Aço\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Xandis tem vantagem em testes para pilotar qualquer tipo de embarcações.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}], \"actions\": [{\"id\": \"452a9f42-2cdd-4583-b8b4-3911ad4606b1\", \"name\": \"Areia De Bolso\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"descriptio