": 0}}], \"attacks\": [{\"id\": \"1787013342251-722a324facac7\", \"mode\": \"builder\", \"title\": \"Garras da Tentação\", \"builder\": {\"range\": \"melee\", \"reach\": 5, \"damages\": [{\"id\": \"1787013342251-510e97dcb297a\", \"die\": \"d8\", \"type\": \"psychic\", \"count\": 3, \"extra\": 0, \"ability\": \"none\"}, {\"id\": \"1787013461491-379ced322b449\", \"die\": \"d8\", \"type\": \"necrotic\", \"count\": 3, \"extra\": 0, \"ability\": \"none\"}], \"effects\": [{\"id\": \"1787013584500-17aa153c47dd6\", \"content\": \"<p>Se o alvo estiver <strong>Encantado </strong>por Lilith, sofre mais 36 (6d8) de dano psíquico.</p>\"}], \"targets\": \"Um alvo\", \"attackType\": \"feature\", \"proficiency\": true, \"attackAbility\": \"dex\", \"extraHitBonus\": 0}, \"content\": \"\"}], \"version\": 1, \"features\": [{\"id\": \"1787012470618-152851f1bbcf58\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Resistência Mágica\", \"content\": \"<p>Lilith tem vantagem em testes de resistência contra magias e outros efeitos mágicos.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787012846946-a17c7c1595f92\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Presença Irresistível\", \"content\": \"<p>Uma criatura que comece seu turno a até 9 metros de Lilith deve realizar um teste de resistência de Sabedoria CD 26.</p><p>Em caso de falha, fica <strong>Encantada</strong> por ela até o início do próximo turno.</p><p>Uma criatura que passe no teste fica imune a este efeito por 24 horas.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787013176497-18640585b1d3c\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Senhora dos Desejos\", \"content\": \"<p>Criaturas Encantadas por Lilith:</p><ul><li><p>Não podem atacá-la voluntariamente;</p></li><li><p>Possuem desvantagem em testes para detectar suas mentiras;</p></li><li><p>Consideram Lilith uma aliada confiável.</p></li></ul><p></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787013230809-0e37b6ca0ef6d\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Golpe da Paixão Fatal\", \"content\": \"<p>Quando Lilith atinge uma criatura Encantada por ela com um ataque corpo a corpo:</p><ul><li><p>o ataque é automaticamente um acerto crítico;</p></li><li><p>a criatura não pode usar Reação contra este ataque;</p></li><li><p>a criatura não pode usar habilidades que sejam ativadas \\\"Quando for atingida\\\".</p></li></ul><p></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787013272379-c9c68c005922f\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Sedução Infernal\", \"content\": \"<p>Sempre que uma criatura falhar contra um efeito de Encantamento de Lilith, ela recupera 15 pontos de vida.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"sections\": [], \"abilities\": {\"cha\": 28, \"con\": 20, \"dex\": 22, \"int\": 18, \"str\": 12, \"wis\": 18}, \"reactions\": [], \"lairActions\": [{\"id\": \"1787020531160-07de57eb223eb8\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Correntes do  desejo \", \"content\": \"<p>Correntes do  desejo surgem do chão; uma criatura faz um salvamento de Sabedoria CD 19 ou fic Restrita, enquanto restritas por essas correntes as criaturas estão vivendo outra realidade elas ficam, incapacitadas..</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787022987490-861fc0cf206ac8\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Encantamento Doloroso \", \"content\": \"<p>Todas as criatura Encantada por ela sofre 22 (4d10) dano psíquico.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787023978638-9ff7a93a2362f8\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Viagem entre os Véus\", \"content\": \"<p>Lilith se teleporta para qualquer ponto do covil que possa ver e fica invisível até o final do seu turno ou até atacar uma criatura.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\