hpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"3acf46b2-4c81-46a4-aac7-5a666bc0856b\", \"name\": \"Nascida De Ixrattu\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Os Estacas compartilham o Rito de Ascenção da mãe deles, o tornando imunes aos malefícios do vampirismo e dos Mortos Vivos. Porém, cada um carrega uma fraqueza própria.<div><b><i>No caso da Sete De Espadas, se ela tiver uma de suas espadas retiradas da suas costas, ele perde:</i></b></div><div><b><i>---</i></b></div><div><b>*&nbsp;<i>30 PV (Não pode ficar a abaixo de 1 PV).</i></b></div><div><b><i>* Um dos pecados da (Escolhido de forma aleatória).</i></b></div><div><b>* Sua Regeneração até o final do próximo turno dela .</b></div><div><b>--</b></div><div><b><i>(Tirar a espada exige um teste de Atletismo contra o dela ou similar.)</i></b></div>\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"06a9255f-d9ee-4280-a566-ef1495270150\", \"name\": \"Regeneração\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"A Sete regenera&nbsp;<b>50PV&nbsp;</b>no inicio dos seus turnos.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"8b1ee49d-0662-49a9-90b5-1fdfe47e8cf4\", \"name\": \"Imortalidade\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Caso a Sete seja reduzido a&nbsp;<b>0</b>&nbsp;pontos de vida, seu corpo vira cinzas e ele renasce no começo do outro dia ao lado de sua Mãe. A Sete só pode ser morta quando todas as suas Espadas forem retiradas de suas costas e uma estaca feita da Árvore do Terror seja enfiada em seu coração enquanto ele estiver com&nbsp;<b>30PV&nbsp;</b>ou menos.&nbsp;<i>(Ao fazer isso, a estaca e seu corpo são destruídos)</i>\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"ceeb56ca-0e51-4deb-b0ce-8e7eb30e3b66\", \"name\": \"Bolsa De Sombras\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"A Sete de Espadas pode usar uma ação livre para guardar ou retirar itens das sombras solidas. Um item guardado nas sombras vai para um local secreto no plano das sombras.&nbsp;\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"96bf2e37-b0ab-4c42-8eba-14bf697ee299\", \"name\": \"Evasão\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Caso a Sete seja submetida a um salvamento de Destreza para receber metade do dano. Ela não toma nada se passar e metade se falhar.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}], \"actions\": [{\"id\": \"c7f2a7bd-d774-4554-b0d1-a3bc90592f35\", \"name\": \"Teleportar em Sombras\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"description\": \"A Sete teleporta até um ponto que ela possa ver em até <b>60ft. </b>E então realiza um ataque usando <b>Laminas Dos Pecados</b>.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}, {\"id\": \"970c9f55-a5c8-477d-811b-0089de802080\", \"name\": \"Ação Astuta\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"description\": \"A Sete pode usar a ação esconder-se, Disparar e Desengajar.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}], \"attacks\": [{\"id\": \"a5ece108-fb6f-4928-83ff-92b0928f9bb9\", \"kind\": \"WEAPON\", \"name\": \"Laminas Dos Pecados\", \"save\": 0, \"range\": {\"long\": 60, \"reach\": 5, \"standard\": 20}, \"damage\": {\"dice\": 12, \"type\": \"slashing\", \"count\": 2, \"modifier\": {\"stat\": \"DEX\", \"override\": true, \"overrideValue\": 15}}, \"targets\": 1, \"distance\": \"BOTH\", \"modifier\": {\"stat\": \"DEX\", \"override\": false, \"proficient\": true, \"overrideValue\": 0}, \"description\": \"\", \"legendaryOnly\": false, \"customRenderer\": \"<b>Laminas Dos Pecados. </b>Ataque corpo a corpo:&nbsp;<b>+18</b>&nbsp;Acerto,&nbsp;<b>5 ft </b>Alcance,<b>&nbsp;</b>um alvo; Dano: <b>34&nbsp;(3d12+15) </b>Cortante. Para cada ataque acertado, role <b>1d8</b>. Se a espada sorteada já tiver sido removida, o efeito desce para o próximo pecado disponível.<div><div><br></div><div>--&nbsp;</div><div><div><i><b>&nbsp; (1)</b> </i><b>Ganancia. </b>O alvo deve ser bem sucedido em um Salvamento de Destreza <b>(CD 26). </b>Em caso de falha,&nbsp;ficará Cego até o final do seu próximo turno. Além disso, a Sete pode roubar um item na posse do alvo <i>(exceto sintonizados)</i>.&nbsp;</div><div><br></div><div><i><b>&nbsp; (2)</b></i> <b>Orgulho. </b>O alvo deve ser bem sucedido em um Salvamento de Sabedoria <b>(CD 26). </b>Em caso se falha, até o final do próximo seu turno,&nbsp;todo o dano causado na Sete é reduzido a <b>0</b>.<b>&nbsp;</b></div><div><b><br></b></div><div><i><b>&nbsp; (3)</b></i> <b>Preguiça.&nbsp;</b>O alvo deve ser bem sucedido em um Salvamento de Constituição <b>(CD 26). </b>Em caso de falha&nbsp;ficará <i>Preguiçoso</i> até o final do seu próximo turno. Um ser <i>Preguiçoso </i>tem <b><i>-5 CA</i></b>, <b><i>Velocidade reduzida pra 15ft</i></b>, <b><i>Apenas um ataque por ação de ataque e só pode usar uma Ação, Ação Bônus ou Movimento, não ambas. Se conjurar um feitiço, role 1d20 (1a15 o feitiço falha)</i></b></div><div><b><i><br></i></b></div><div><b>&nbsp; (4)</b> <b>Luxuria. </b>O alvo deve ser bem sucedido em um salvamento de Sabedoria <b>(CD 26). </b>Em caso de falha ficará sobre o efeito de Dominar Monstro até o final do seu próximo turno <i>(efeito de charm)</i><b>.</b></div><div><br></div><div><i><b>&nbsp; (5)</b></i> <b>Inveja.</b>&nbsp;O alvo deve ser bem sucedido em um salvamento de Carisma <b>(CD 26)</b>. Em caso de falha, o alvo perde todas as Resistências e Invulnerabilidades, e a Sete ganha elas até o final do seu próximo turno.</div><div><br></div><div><i><b>&nbsp; (6)</b>&nbsp;</i><b>Gula.&nbsp;</b>O alvo deve ser bem sucedido em um Salvamento de Constituição&nbsp;<b>(CD 26)</b>. Em caso de falha o alvo recebe&nbsp;<b>23</b>&nbsp;<b>(7d6)</b>&nbsp;Necrótico. E a Sete recupera o dobro disso em pontos de vida&nbsp;<b>(46).</b>&nbsp;<br><div><br></div></div><div><i><b>&nbsp; (7)</b></i>&nbsp;<b>Ira.</b> A sete realiza outro ataque contra o mesmo alvo com vantagem e critico em <b>12/20</b>.</div><div><br></div><div><i><b>&nbsp; (8) Os 7 Pecados Capitais. </b>A Sete escolhe <b>2</b> Pecados para tomarem efeito. (Se o pecado já tiver sido retirado, A Sete pode replicar ele mesmo assim.)</i><div><br></div></div></div></div>\", \"alternateDamage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 1, \"active\": false, \"modifier\": {\"stat\": \"STR\", \"override\": false, \"overrideValue\": 0}, \"condition\": \"\"}, \"additionalDamage\": [], \"useCustomRenderer\": true}], \"nickname\": \"\", \"alignment\": \"\", \"inventory\": \"\", \"languages\": \"Todas\", \"reactions\": [{\"id\": \"b4fd9527-0d1c-46b0-b602-16f514576649\", \"name\": \"Esquivar\", \"trigger\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Sete pode escolher esquivar de um ataque feito contra ela. Não recebendo dano nenhum no processo.\"}], \"conditions\": [\"Encantada, Assustada, Envenenada, Exausta e Inconciente.\"], \"crOverride\": \"\", \"immunities\": [\"Necrótico e Veneno \"], \"lairCrNote\": \"in lair\", \"alphaTraits\": true, \"lairActions\": [], \"proficiency\": 7, \"resistances\": [\"Corte, Impacto e Perfurante\"], \"saveVersion\": 11, \"sensesNotes\": \"\", \"multiattacks\": [{\"id\": \"77cd4133-15d4-43cc-a0d1-2735f26088d4\", \"actions\": [], \"attacks\": [\"a5ece108-fb6f-4928-83ff-92b0928f9bb9\", \"a5ece108-fb6f-4928-83ff-92b0928f9bb9\", \"a5ece108-fb6f-4928-83ff-92b0928f9bb9\"]}], \"spellcasting\": {\"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"INT\", \"level\": 1, \"notes\": \"\", \"slots\": [0, 0, 0, 0, 0, 0, 0, 0, 0], \"atWill\": [], \"attack\": {\"override\": false, \"overrideValue\": 0}, \"modifier\": {\"override\": false, \"overrideValue\": 0}, \"standard\": [], \"atWillNotes\": \"\", \"customClassPreamble\": \"\", \"customInnatePreamble\": \"\", \"useCustomClassPreamble\": false, \"useCustomInnatePreamble\": false}, \"mythicActions\": {\"actions\": [], \"preamble\": \"If {NAME}\'s mythic trait is active, it can use the options below as legendary actions.\", \"triggerName\": \"\", \"triggerRecharge\": \"Recharges after a Short or Long Rest\", \"triggerDescription\": \"If {NAME} would be reduced to 0 hit points, its current hit point total instead resets to {monster.hp} hit points. Additionally, the {NAME} can now use the options in the \\\"Mythic Actions\\\" section for 1 hour. Award a party an additional [x]XP ([x] XP total) for defeating the {}NAME} after this trait activates.\"}, \"regionalEffects\": [], \"vulnerabilities\": [], \"legendaryActions\": {\"count\": 3, \"actions\": [], \"customPreamble\": \"<b><i>A Sete de Espadas possui Três (3) Ações lendárias e pode usar uma dela no final do turno de uma criatura.</i></b><div><b><br></b></div><div><b>Teleporte Assassino.</b> A Sete teleporta até <b>60ft, </b>e então realiza um Ataque usando Laminas Dos Pecados.&nbsp;</div><div><br></div><div><b>Disparo Sombrio.</b> Ataque com Arma a Distancia: <b>+16</b>&nbsp;Acerto, <b>60 ft</b> Alcance, Um alvo. Dano <b>(4d12)&nbsp;</b>Necrótico, o alvo deve ser bem sucedido em um Salvamento de Sabedoria <b>(CD25).&nbsp;</b>Em caso de falha, a Sete fica invisível para ele até o final do seu próximo turno.</div><div><br></div><div><b>Afiar Mente. </b>Sete recupera um uso de sua <b>Reação </b>e regenera <b>50PV</b>.</div>\", \"useCustomPreamble\": true}, \"hpDieTypeOverride\": true, \"passivePerception\": {\"override\": false, \"overrideValue\": 0}, \"useArticleInToken\": false, \"hpModifierOverride\": false, \"lairActionPreamble\": \"\", \"multiattackOptions\": {\"postscript\": \"\", \"useCustomRenderer\": true, \"customMultiattackRenderer\": \"<b><i>Multiataque. A Sete de Espadas realiza Três (3) ataques usando Laminas Do Pecado</i></b>\"}, \"proficiencyOverride\": false, \"useCrDisplayOverride\": false, \"autoEstimateDefenseCr\": true, \"regionalEffectDescription\": \"\", \"useCustomLairActionPreamble\": false}','npcs/AdlsRTGzZeZgtpuMt6MJH18j7SocoSBYJt1EVwys.png',NULL,NULL,'2026-08-27 01:01:18','2026-08-27 20:41:45'),(113,1,NULL,'Expositores','','humanoid','Medium','',20,20.00,195,'{\"AC\": 20, \"CR\": 20, \"HP\": {\"HD\": 26, \"type\": 8, \"modifier\": 78}, \"name\": \"Expositores\", \"size\": \"Medium\", \"type\": \"humanoid\", \"saves\": {\"CHA\": {\"override\": false, \"proficient\": false, \"overrideValue\": 0}, 