": \"DECEPTION\", \"skill\": {\"stat\": \"CHA\", \"label\": \"Deception\"}, \"override\": false, \"expertise\": false, \"proficient\": true, \"overrideValue\": 0}], \"speeds\": [{\"id\": \"7b8f8d80-7322-482c-bb99-d95175aa61d5\", \"note\": \"\", \"type\": \"walk\", \"speed\": 50}, {\"id\": \"b377922c-42bd-4b63-aeb1-f9a98f8a4fc7\", \"note\": \"\", \"type\": \"climb\", \"speed\": 50}], \"traits\": [{\"id\": \"39f220ca-a0fc-4823-8894-7055af501216\", \"name\": \"Olhos Para Pistas\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"O Expositor possui uma mente analítica aguçada, recebendo <b>Vantagem</b> em todos os testes de Inteligência (Investigação) e Sabedoria (Percepção).\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"728da026-96cf-4819-8380-567754fddb1a\", \"name\": \"Mestre Em Parkour\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"O Expositor ignora terreno difícil enquanto estiver correndo ou escalando. Além disso, ele pode saltar até <b>30 ft </b>horizontalmente ou <b>15 ft </b>verticalmente sem corrida prévia.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"ca0a1c7b-fd3a-4900-a24a-3d5fcda2b1b7\", \"name\": \"Camaleão Furtivo\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"O Expositor possui treinamento avançado em ocultação, garantindo Vantagem em todos os testes de Destreza<b> (Furtividade)</b>.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"9f31d070-fd30-410b-b06e-b81c5103bc0a\", \"name\": \"Ataque Furtivo Perfeito\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Uma vez por turno, ao atingir uma criatura com um ataque no qual possua <b>Vantagem</b>, o Expositor pode desferir um golpe preciso em áreas vitais, causando <b>35 (10d6)</b> de dano extra. Se o alvo for um <b>Humanoide</b>, ele deve realizar um Salvamento de Constituição <b>(CD 22)</b>. Em caso de falha, o Expositor pode escolher um dos seguintes efeitos:<div><br></div><div><br></div><div><b>&nbsp; &nbsp; &nbsp;* Execução Cirúrgica ____/2: </b>O Expositor atinge um ponto vital. O alvo é reduzido a <b>0 </b>pontos de vida instantaneamente.</div><div><br></div><div><b>&nbsp; &nbsp; &nbsp;* Silenciar Vocal (Silenciar):</b> As cordas vocais ou canais de respiração do alvo são temporariamente bloqueados. O alvo fica Silenciado e não pode emitir sons ou conjurar magias com componentes verbais até o final do próximo turno do Expositor.</div><div><br></div><div><b>&nbsp; &nbsp; &nbsp;* Trauma Neural (Nocautear):</b> O golpe acerta o sistema nervoso do alvo. A criatura fica Inconsciente por <b>1 Hora</b>. O efeito encerra prematuramente se o alvo sofrer qualquer dano ou se outra criatura usar uma Ação para sacudi-lo.</div>\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": false, \"maxDamage\": 35, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"bb14279d-15d5-4b72-89e0-e855c872dbaa\", \"name\": \"Evasão\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Quando o Expositor é alvo de um efeito que exige um Salvamento de Destreza para sofrer apenas metade do dano, ele não sofre dano algum se passar, e apenas metade se falhar.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"b817ce9b-bf94-425b-a2ed-706e868ee985\", \"name\": \"Talento Infalível\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"O Expositor não pode rolar abaixo de <b>10</b> em testes de habilidade que ele possua proficiência.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}], \"actions\": [{\"id\": \"1b499d78-a001-4428-881d-3533eef0c3a3\", \"name\": \"Ação Astuta\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"description\": \"O Expositor pode <b>Disparar</b>, <b>Desengajar </b>ou <b>Esconder-se </b>como ação bônus.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}], \"attacks\": [{\"id\": \"dd34e8cd-faab-49ea-a2c9-1cdacb4ccb79\", \"kind\": \"WEAPON\", \"name\": \"Golpes\", \"save\": 0, \"range\": {\"long\": 60, \"reach\": 5, \"standard\": 20}, \"damage\": {\"dice\": 4, \"type\": \"slashing\", \"count\": 3, \"modifier\": {\"stat\": \"DEX\", \"override\": true, \"overrideValue\": 8}}, \"targets\": 1, \"distance\": \"MELEE\", \"modifier\": {\"stat\": \"DEX\", \"override\": true, \"proficient\": true, \"overrideValue\": 15}, \"description\": \"\", \"legendaryOnly\": false, \"customRenderer\": \"<b>Golpes.</b> Ataque Desarmado: <b>+15</b>&nbsp;Acerto. Alcance <b>5ft</b>. Dano: <b>15 (3d4 + 7) </b>Impacto. Ao atingir uma criatura, o Expositor utiliza técnicas de combate avançados, garantindo vantagem no próximo teste de ataque que ele realizar contra o mesmo alvo até o fim do seu turno atual.\", \"alternateDamage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 1, \"active\": false, \"modifier\": {\"stat\": \"STR\", \"override\": false, \"overrideValue\": 0}, \"condition\": \"\"}, \"additionalDamage\": [], \"useCustomRenderer\": true}, {\"id\": \"03b266e6-2fd8-4644-ba52-b7219d579c34\", \"kind\": \"WEAPON\", \"name\": \"Lamina Oculta\", \"save\": 0, \"range\": {\"long\": 60, \"reach\": 5, \"standard\": 20}, \"damage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 4, \"modifier\": {\"stat\": \"DEX\", \"override\": true, \"overrideValue\": 7}}, \"targets\": 1, \"distance\": \"MELEE\", \"modifier\": {\"stat\": \"STR\", \"override\": false, \"proficient\": true, \"overrideValue\": 0}, \"description\": \"\", \"legendaryOnly\": false, \"customRenderer\": \"<b>Lamina Oculta. </b>Ataque Corpo a Corpo: <b>+13 </b>Acerto. Alcance <b>5ft. </b>Dano: <b>21 (3d6+7) </b>Perfurante. Caso o Expositor possua vantagem na jogada de ataque, a margem de acerto crítico para este golpe é reduzida para <b>16–20</b>.\", \"alternateDamage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 1, \"active\": false, \"modifier\": {\"stat\": \"STR\", \"override\": false, \"overrideValue\": 0}, \"condition\": \"\"}, \"additionalDamage\": [], \"useCustomRenderer\": true}, {\"id\": \"1752ed81-617b-4a6b-8cc2-59d3cebc0fbd\", \"kind\": \"WEAPON\", \"name\": \"Disparo Oculto\", \"save\": 0, \"range\": {\"long\": 60, \"reach\": 5, \"standard\": 20}, \"damage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 1, \"modifier\": {\"stat\": \"DEX\", \"override\": true, \"overrideValue\": 7}}, \"targets\": 1, \"distance\": \"MELEE\", \"modifier\": {\"stat\": \"STR\", \"override\": false, \"proficient\": true, \"overrideValue\": 0}, \"description\": \"\", \"legendaryOnly\": false, \"customRenderer\": \"<b>Disparo Oculto.</b> Ataque Com Arma a Distancia: +13 Acerto. Alcance: <b>60/90ft. </b>Dano: <b>10 (1d6+7)&nbsp;</b>Perfurante e <b>21 (6d6) </b>Veneno. O alvo deve ser bem-sucedido em um Salvamento de Constituição <b>(CD 21)</b> ou ficará <b>Envenenado</b> até o fim do seu próximo turno. Enquanto estiver <b>Envenenado </b>dessa forma, ele só pode realizar um tipo de Ação <i>(Se mover, Ação Padrão ou Ação Bônus)</i>.&nbsp;\", \"alternateDamage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 1, \"active\": false, \"modifier\": {\"stat\": \"STR\", \"override\": false, \"overrideValue\": 0}, \"condition\": \"\"}, \"additionalDamage\": [{\"id\": \"9b46e65e-8178-4deb-be72-fe3e9f67a958\", \"dice\": 6, \"note\": \"\", \"type\": \"\", \"count\": 6}], \"useCustomRenderer\": true}], \"nickname\": \"\", \"alignment\": \"\", \"inventory\": \"Disparo Oculto +2, Lamina Escondida +2\", \"languages\": \"Comum\", \"reactions\": [{\"id\": \"56e196ba-190b-4565-8f1f-f3c0cb5b03e2\", \"name\": \"Manobra de Esquiva\", \"trigger\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Ao ser atacado, o Expositor faz um teste de <b>Acrobacia</b> contra o resultado do ataque. Se vencer, ele não sofre dano e se move <b>25 ft</b> sem provocar oportunidades. Se falhar, ele recebe apenas metade do dano.\"}, {\"id\": \"18719ebe-c0c9-48e4-99f8-d45b7443981e\", \"name\": \"Amortecer Queda\", \"trigger\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"O Expositor pode usar a sua reação para amortecer a sua queda, ele ignora até<b> 50</b> Pontos de dano de queda.\"}], \"conditions\": [], \"crOverride\": \"\", \"immunities\": [], \"lairCrNote\": \"in lair\", \"alphaTraits\": true, \"lairActions\": [], \"proficiency\": 6, \"resistances\": [\"Psíquico\"], \"saveVersion\": 11, \"sensesNotes\": \"\", \"multiattacks\": [{\"id\": \"0172b23b-ea7b-4036-bb61-e1524b42249d\", \"actions\": [], \"attacks\": [\"03b266e6-2fd8-4644-ba52-b7219d579c34\", \"03b266e6-2fd8-4644-ba52-b7219d579c34\", \"03b266e6-2fd8-4644-ba52-b7219d579c34\", \"03b266e6-2fd8-4644-ba52-b7219d579c34\"]}], \"spellcasting\": {\"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"INT\", \"level\": 1, \"notes\": \"\", \"slots\": [0, 0, 0, 0, 0, 0, 0, 0, 0], \"atWill\": [], \"attack\": {\"override\": false, \"overrideValue\": 0}, \"modifier\": {\"override\": false, \"overrideValue\": 0}, \"standard\": [], \"atWillNotes\": \"\", \"customClassPreamble\": \"\", \"customInnatePreamble\": \"\", \"useCustomClassPreamble\": false, \"useCustomInnatePreamble\": false}, \"mythicActions\": {\"actions\": [], \"preamble\": \"If {NAME}\'s mythic trait is active, it can use the options below as legendary actions.\", \"triggerName\": \"\", \"triggerRecharge\": \"Recharges after a Short or Long Rest\", \"triggerDescription\": \"If {NAME} would be reduced to 0 hit points, its current hit point total instead resets to {monster.hp} hit points. Additionally, the {NAME} can now use the options in the \\\"Mythic Actions\\\" section for 1 hour. Award a party an additional [x]XP ([x] XP total) for defeating the {}NAME} after this trait activates.\"}, \"regionalEffects\": [], \"vulnerabilities\": [], \"legendaryActions\": {\"count\": 3, \"actions\": [], \"customPreamble\": \"<b><i>O Expositor possui Três (3) ações lendárias podendo usar uma delas no final do turno de uma criatura.</i></b><div><br></div><div><b>Especialista Corpo a Corpo.&nbsp;</b>O Expositor realiza Dois (2) ataques usando <b>Golpes</b>. Devido à sua velocidade, ele pode se mover até metade do seu deslocamento entre esses dois ataques sem provocar ataques de oportunidade.</div><div><br></div><div><b>Analisar e Preparar.</b>&nbsp;O Expositor realiza um teste de Inteligência (Investigação) contra um alvo a até <b>60 ft </b>que ele possa ver. A dificuldade (CD) é igual a 10 + Nível ou CR do alvo. Em caso de sucesso, o Expositor identifica uma falha fatal na guarda da criatura. O próximo ataque do Expositor contra este alvo terá <b>Vantagem </b>e, se atingir, será automaticamente considerado um <b>Acerto Crítico</b>.</div><div><br></div><div><b>Cortina de Fumaça.&nbsp;</b>O Expositor lança uma bomba de fumaça em um ponto a até <b>60 ft</b>, criando uma nuvem de fumaça densa em um raio de <b>20 ft</b>. A área é considerada <b>Fortemente Obscurecida </b>para todas as criaturas. A fumaça se dissipa no final do próximo turno do Expositor ou se for dispersada por um vento forte. O Expositor pode realizar a Ação de <b>Esconder-se</b> como parte desta ação lendária.</div>\", \"useCustomPreamble\": true}, \"hpDieTypeOverride\": false, \"passivePerception\": {\"override\": true, \"overrideValue\": 30}, \"useArticleInToken\": false, \"hpModifierOverride\": false, \"lairActionPreamble\": \"\", \"multiattackOptions\": {\"postscript\": \"\", \"useCustomRenderer\": true, \"customMultiattackRenderer\": \"<b><i>Multiataque. O Expostitor realiza Quatro (4) ataques usando Golpes, Lamina Oculta ou Disparo Oculto em qualquer combinação.</i></b>\"}, \"proficiencyOverride\": false, \"useCrDisplayOverride\": false, \"autoEstimateDefenseCr\": true, \"regionalEffectDescription\": \"\", \"useCustomLairActionPreamble\": false}','npcs/JXy4WcecrEK0kmqx2fxAwMcLZ3oYHwO5VxwEJhzP.png',NULL,NULL,'2026-08-27 01:03:42','2026-08-27 01:03:42'),(114,1,NULL,'Nina Greymore (A Rainha De Bassuras)','','humanoid','Medium','',22,25.00,310,'{\"AC\": 22, \"CR\": 25, \"HP\": {\"HD\": 20, \"type\": 12, \"modifier\": 180}, \"name\": \"Nina Greymore (A Rainha De Bassuras)\", \"size\": \"Medium\", \"type\": \"humanoid\", \"saves\": {\"CHA\": {\"override\": false, \"proficient\": false, \"overrideValue\": 0}, \"CON\": {\"override\": false, \"proficient\": true, \"overrideValue\": 0}, \"DEX\": {\"override\": false, \"proficient\": false, \"overrideValue\": 0}, \"INT\": {\"override\": false, \"proficient\": false, \"overrideValue\": 0}, \"STR\": {\"override\": false, \"proficient\": true, \"overrideValue\": 0}, \"WIS\": {\"override\": false, \"proficient\": false, \"overrideValue\": 0}}, \"stats\": {\"CHA\": 14, \"CON\": 25, \"DEX\": 19, \"INT\