cModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"9eb619b5-e016-4fa9-a4d0-d21018996712\", \"name\": \"Ataque Imprudente\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Nina pode escolher atacar com <b>vantagem </b>até o começo do seu próximo turno. Ao fazer isso, todos os ataques contra ela também são feitos com <b>vantagem</b>.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"70996f27-cf7b-4171-aa06-bf00a76b0167\", \"name\": \"Descendente Da Tormenta ____/1\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Caso Nina seja reduzida a <b>0</b> pontos de vida, ela não cai; em vez disso, sua linhagem desperta, fazendo-a recuperar imediatamente<b> 165 PV, </b>restaurar o uso de sua habilidade Turbilhão de Raios e a usar imediatamente em uma explosão de Furia.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"209cb2c3-b47c-438e-bc6c-740a2da6978d\", \"name\": \"Surto De Fúria ____/1\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Nina se enfurece ainda mais, ela pode escolher realizar uma ação padrão extra <i>(exceto ação mágica)</i>\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"customPreamble\": false}, {\"id\": \"31fb94c1-3ee6-4e4c-ae78-b14b9f536149\", \"name\": \"Tempestuosa (Requer \\\"Fúria Da Rainha\\\" Ativada)\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"description\": \"Enquanto estiver em fúria, Nina emana eletricidade constante. Quando uma criatura inimiga inicia o seu turno em até <b>30ft </b>da Nina, ela sofre <b>10 (3d6) </b>de dano Elétrico.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": false, \"maxDamage\": 10, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": true, \"ehpMultiplier\": 1}, \"customPreamble\": false}], \"actions\": [{\"id\": \"9a4b6159-7e5a-4164-80b0-7f8fbfde0916\", \"name\": \"Lindinha\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"description\": \"Ataque Mágico a Distancia. <b>+17 </b>Acerto, Alcance <b>120ft. </b>Dano:<b>&nbsp;37 (5d6+20) </b>Elétrico, Após acertar o alvo, ele perde a sua&nbsp;<b><i>Reação&nbsp;</i></b>é movido <b>30ft</b>&nbsp;em uma direção à escolha de Nina.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}, {\"id\": \"3a2c73db-e8ee-484f-b27b-d44f3d9aec52\", \"name\": \"Turbilhão De Raios (Recarga 5/6)\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": false, \"description\": \"Nina convoca a fúria do Senhor das Tempestades. Cada criatura em um raio de <b>30 ft</b>&nbsp;ao redor dela deve ser bem-sucedido em um Salvamento de Destreza <b>(CD 25). </b>Em caso de falha, o alvo recebe&nbsp;<b>55 (10d8+10) </b>Elétrico, perdendo a sua <b>Reação </b>e ficando <b>Atordoado </b>até o final do seu próximo turno. Se passar, recebe apenas metade do dano.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}, {\"id\": \"df902841-2334-48de-9d7e-a78f6e170b29\", \"name\": \"Fúria Da Rainha\", \"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"none\", \"range\": \"\", \"effects\": [], \"recharge\": \"\", \"limitedUse\": {\"rate\": \"DAY\", \"count\": 0}, \"bonusAction\": true, \"description\": \"Nina entra em um estado de frenesi que dura <b>10 Minutos</b>. Enquanto estiver em fúria, ela possui resistência a danos físicos e ativa suas características especiais.\", \"crAnnotation\": {\"include\": true, \"maxSave\": 0, \"automatic\": true, \"maxDamage\": 0, \"acModifier\": 0, \"ehpModifier\": 0, \"maxModifier\": 0, \"multitarget\": false, \"ehpMultiplier\": 1}, \"legendaryOnly\": false, \"customPreamble\": false}], \"attacks\": [{\"id\": \"8e9759f1-0e37-4325-9925-f360b1ea407c\", \"kind\": \"WEAPON\", \"name\": \"Chacina\", \"save\": 0, \"range\": {\"long\": 60, \"reach\": 5, \"standard\": 20}, \"damage\": {\"dice\": 12, \"type\": \"slashing\", \"count\": 2, \"modifier\": {\"stat\": \"STR\", \"override\": true, \"overrideValue\": 35}}, \"targets\": 1, \"distance\": \"MELEE\", \"modifier\": {\"stat\": \"STR\", \"override\": true, \"proficient\": true, \"overrideValue\": 20}, \"description\": \"\", \"legendaryOnly\": false, \"customRenderer\": \"<b>Chacina. </b>Ataque Corpo a Corpo: <b>+20</b> Acerto, alcance <b>5 ft</b>. Dano: <b>48 (2d12+35)</b>&nbsp;Corte/Energia. O alvo deve ser bem-sucedido em um Salvamento de Constituição <b>(CD 25)</b> ou ficará <b>Sangrando</b>. Uma criatura <b>Sangrando </b>perde <b>1d6 PV </b>no início de cada um de seus turnos. O efeito acumula a cada golpe e dura <b>1 Minuto </b>ou até que o alvo recupere <b>30 PV</b>.\", \"alternateDamage\": {\"dice\": 6, \"type\": \"slashing\", \"count\": 1, \"active\": false, \"modifier\": {\"stat\": \"STR\", \"override\": false, \"overrideValue\": 0}, \"condition\": \"\"}, \"additionalDamage\": [], \"useCustomRenderer\": true}], \"nickname\": \"\", \"alignment\": \"\", \"inventory\": \"Chacina, Cinto Da Tormenta\", \"languages\": \"Comum, Marquisiano, Gigante\", \"reactions\": [], \"conditions\": [\"Assustado\"], \"crOverride\": \"\", \"immunities\": [\"Trovão e Eletrico\"], \"lairCrNote\": \"in lair\", \"alphaTraits\": true, \"lairActions\": [], \"proficiency\": 7, \"resistances\": [\"Corte, Impacto e Perfurante (apenas após ativar Fúria Da Rainha)\"], \"saveVersion\": 11, \"sensesNotes\": \"\", \"multiattacks\": [{\"id\": \"417cbaac-b14a-42b7-af12-1cce31adb54b\", \"actions\": [], \"attacks\": [\"8e9759f1-0e37-4325-9925-f360b1ea407c\", \"8e9759f1-0e37-4325-9925-f360b1ea407c\"]}], \"spellcasting\": {\"save\": {\"override\": false, \"overrideValue\": 0}, \"stat\": \"INT\", \"level\": 1, \"notes\": \"\", \"slots\": [0, 0, 0, 0, 0, 0, 0, 0, 0], \"atWill\": [], \"attack\": {\"override\": false, \"overrideValue\": 0}, \"modifier\": {\"override\": false, \"overrideValue\": 0}, \"standard\": [], \"atWillNotes\": \"\", \"customClassPreamble\": \"\", \"customInnatePreamble\": \"\", \"useCustomClassPreamble\": false, \"useCustomInnatePreamble\": false}, \"mythicActions\": {\"actions\": [], \"preamble\": \"If {NAME}\'s mythic trait is active, it can use the options below as legendary actions.\", \"triggerName\": \"\", \"triggerRecharge\": \"Recharges after a Short or Long Rest\", \"triggerDescription\": \"If {NAME} would be reduced to 0 hit points, its current hit point total instead resets to {monster.hp} hit points. Additionally, the {NAME} can now use the options in the \\\"Mythic Actions\\\" section for 1 hour. Award a party an additional [x]XP ([x] XP total) for defeating the {}NAME} after this trait activates.\"}, \"regionalEffects\": [], \"vulnerabilities\": [], \"legendaryActions\": {\"count\": 3, \"actions\": [], \"customPreamble\": \"<b><i>Nina possui Três (3) ações lendárias e pode usar uma delas no final do turno de uma criatura.</i></b><div><br></div><div><b>Hora Da Chacina. </b>Nina avança <b>50ft</b> e então realiza <b>Um (1)</b> ataque usando <b>Chacina.</b></div><div><br></div><div><b>Afiar Machado. </b>O próximo ataque que Nina fizer usando <b>Chacina </b>tem a sua margem de critico reduzida para <b>16 a 20.</b></div><div><b><br></b></div><div><b>Grito De Comando (2 Ações). </b>Nina e todos os seus aliados em até <b>60ft </b>ganham 20 pontos de vida temporários e ganham vantagem em todos os testes de ataque, até o final do seus turnos.</div>\", \"useCustomPreamble\": true}, \"hpDieTypeOverride\": true, \"passivePerception\": {\"override\": false, \"overrideValue\": 0}, \"useArticleInToken\": false, \"hpModifierOverride\": true, \"lairActionPreamble\": \"\", \"multiattackOptions\": {\"postscript\": \"\", \"useCustomRenderer\": true, \"customMultiattackRenderer\": \"<b><i>Multiataque. Nina realiza Dois (2) ataques usando Chacina.</i></b>\"}, \"proficiencyOverride\": false, \"useCrDisplayOverride\": false, \"autoEstimateDefenseCr\": true, \"regionalEffectDescription\": \"\", \"useCustomLairActionPreamble\": false}','npcs/0MnGpDIYXDjxAZ73GgDAD6Zf7adEUYrpIeg0uMn6.png',NULL,NULL,'2026-08-27 01:04:46','2026-08-27 01:04:46'),(116,3,16,'Abel Inclemendélius',NULL,'humanoid','medium','true_neutral',12,16.00,1,'{\"speed\": {\"fly\": 0, \"swim\": 0, \"walk\": 30, \"climb\": 30, \"hover\": false, \"burrow\": 0, \"hasJumps\": false, \"jumpVerticalBonus\": 0, \"jumpHorizontalBonus\": 0}, \"combat\": {\"senses\": {\"truesight\": 0, \"blindsight\": 0, \"darkvision\": 0, \"tremorsense\": 0}, \"ac_base\": 10, \"ac_type\": \"\", \"hit_die\": \"d8\", \"hp_mode\": \"average\", \"ac_bonus\": 2, \"custom_hp\": 10, \"languages\": [], \"immunities\": [], \"resistances\": [], \"customSenses\": [], \"hp_mod_extra\": 0, \"hit_dice_count\": 20, \"vulnerabilities\": [], \"conditionImmunities\": [], \"passivePerceptionBonus\": 0}, \"format\": \"npc-builder\", \"header\": {\"name\": \"Abel Inclemendélius\", \"size\": \"medium\", \"types\": [\"humanoid\"], \"languages\": [\"common\"], \"alignments\": [\"true_neutral\"], \"languageCustom\": \"\", \"challengeRating\": \"16\"}, \"skills\": [{\"key\": \"acrobatics\", \"bonus\": 0, \"label\": \"Acrobacia\", \"ability\": \"dex\", \"enabled\": false, \"expertise\": true, \"proficient\": true}, {\"key\": \"animalHandling\", \"bonus\": 0, \"label\": \"Adestrar Animais\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"arcana\", \"bonus\": 0, \"label\": \"Arcanismo\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"athletics\", \"bonus\": 0, \"label\": \"Atletismo\", \"ability\": \"str\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"deception\", \"bonus\": 0, \"label\": \"Enganação\", \"ability\": \"cha\", \"enabled\": false, \"expertise\": true, \"proficient\": true}, {\"key\": \"history\", \"bonus\": 0, \"label\": \"História\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"insight\", \"bonus\": 0, \"label\": \"Intuição\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": true}, {\"key\": \"intimidation\", \"bonus\": 0, \"label\": \"Intimidação\", \"ability\": \"cha\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"investigation\", \"bonus\": 0, \"label\": \"Investigação\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"medicine\", \"bonus\": 0, \"label\": \"Medicina\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"nature\", \"bonus\": 0, \"label\": \"Natureza\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"perception\", \"bonus\": 0, \"label\": \"Percepção\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": true, \"proficient\": true}, {\"key\": \"performance\", \"bonus\": 0, \"label\": \"Performance\", \"ability\": \"cha\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"initiative\", \"bonus\": 0, \"label\": \"Iniciativa\", \"ability\": \"dex\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"persuasion\", \"bonus\": 0, \"label\": \"Persuasão\", \"ability\": \"cha\", \"enabled\": false, \"expertise\": true, \"proficient\": true}, {\"key\": \"religion\", \"bonus\": 0, \"label\": \"Religião\", \"ability\": \"int\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"sleightOfHand\", \"bonus\": 0, \"label\": \"Prestidigitação\", \"ability\": \"dex\", \"enabled\": false, \"expertise\": false, \"proficient\": false}, {\"key\": \"stealth\", \"bonus\": 0, \"label\": \"Furtividade\", \"ability\": \"dex\", \"enabled\": false, \"expertise\": true, \"proficient\": true}, {\"key\": \"survival\", \"bonus\": 0, \"label\": \"Sobrevivência\", \"ability\": \"wis\", \"enabled\": false, \"expertise\": false, \"proficient\": true}], \"actions\": [{\"id\": \"1787880738829-d9341107f804f8\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Como uma 2º Mãe\", \"content\": \"<p>Abel utiliza sua presença e lábia para manipular o estado emocional de uma criatura a até 30ft. ela deve escolher uma das seguintes abordagens:</p><ul><li><p>*Persuasão: Abel profere palavras de conforto e suporte. Ela realiza um teste de Persuasão e o resultado total torna-se pontos de vida temporários para o alvo. Apenas uma criatura por vez pode possuir este bônus; se Abel usar esta habilidade novamente, os pontos de anteriores desaparecem.</p></li><li><p>*Enganação: Abel manipula o alvo para que ele acredite em suas boas intenções. A criatura deve realizar um teste de Intuição contra a Enganação de Abel. Em caso de falha, o alvo fica Encantado (efeito de charm) por ela durante 1 Hora. Enquanto estiver encantado, Abel possui Vantagem em seus ataques contra ele, e obtendo crítico em (18/20). Por fim, seu primeiro Ataque Furtivo bem-sucedido causa +21 (6d6) de dano adicional.</p></li></ul><p></p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"attacks\": [{\"id\": \"1787880154818-937398ef4a1f\", \"mode\": \"builder\", \"title\": \"Sniper\", \"builder\": {\"range\": \"ranged\", \"reach\": 600, \"damages\": [{\"id\": \"1787880154818-4cb8d9b348a5a\", \"die\": \"d12\", \"type\": \"piercing\", \"count\": 2, \"extra\": 5, \"ability\": \"dex\"}], \"effects\": [], \"targets\": \"Um alvo\", \"attackType\": \"weapon\", \"proficiency\": true, \"attackAbility\": \"dex\", \"extraHitBonus\": 2}, \"content\": \"\"}, {\"id\": \"1787880421715-9f3e0c7d8e6958\", \"mode\": \"builder\", \"title\": \"Adaga\", \"builder\": {\"range\": \"melee\", \"reach\": 5, \"damages\": [{\"id\": \"1787880421716-2e29bfd007b64\", \"die\": \"d4\", \"type\": \"slashing\", \"count\": 2, \"extra\": 5, \"ability\": \"str\"}], \"effects\": [], \"targets\": \"Um alvo\", \"attackType\": \"weapon\", \"proficiency\": true, \"attackAbility\": \"dex\", \"extraHitBonus\": 1}, \"content\": \"\"}], \"version\": 1, \"features\": [{\"id\": \"1787882164369-e5c86ef2ddb398\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Ataque Furtivo\", \"content\": \"<p>Uma vez por turno, Abel causa 28 (8d6) de dano extra a uma criatura que atingir com um ataque, desde que tenha Vantagem na Jogada ou que um aliado de Abel esteja a até 5ft do alvo.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787882366112-1eb2ab070ccd7\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"*Canção De Ninar \", \"content\": \"<p>Caso o alvo esteja Encantado por Abel através de habilidade Como uma 2º Mãe, sua precisão se torna letal: todos os dados do dano extra tornam-se d8, totalizando 36 (8d8) de dano adicional.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787882502916-3c468bbe46533\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Mira Afiada\", \"content\": \"<p>Abel possui um conhecimento técnico profundo sobre balística avançada. Ela soma seu modificador de Inteligência em todas as rolagens de dano realizadas com armas de fogo à distância. Além disso, sua margem de acerto crítico com essas armas é expandida ocorrendo em resultados (19/20) no dado.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787882681940-0b8fa0aea0e028\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Furtividade Absoluta\", \"content\": \"<p>Abel Possui Vantagem em todos os testes de Furtividade. Enquanto estiver utilizando suas \\\"Roupas Do Trampo\\\", ela recebe um bônus de +5 em testes para se disfarçar, enganar ou passar despercebida em multidões e ambientes urbanos. Além disso, se Abel realizar um ataque à distância enquanto estiver escondida e errar o tiro, ela não revela sua posição, permanecendo furtiva para o alvo.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"sections\": [], \"abilities\": {\"cha\": 18, \"con\": 12, \"dex\": 20, \"int\": 16, \"str\": 11, \"wis\": 20}, \"reactions\": [], \"lairActions\": [{\"id\": \"1787883175940-4bf82cce676fa\", \"lair\": {\"intro\": \"Os Inclemendélius são mais que mercenários; são uma família ligada por um vínculo inquebrável. Enquanto estiverem lutando juntos eles recebem benefícios baseados no números de membros ativos no combate:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Vinculo Familiar\", \"content\": \"<p>Enquanto estiverem a até 60ft de uma familiar consciente, cada membro recebe +2 na CA. Além disso, dependendo de quantos membros principais da família estão em pé, todos recebem os seguintes bônus cumulativos em suas jogadas:</p><p>*4 Membros: +5 em todos os testes de d20.</p><p>*3 Membros: +3 em todos os testes de d20.</p><p>*2 Membros: +2 em todos os testes de d20.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}, {\"id\": \"1787883633685-548857ed281c3\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Legado Inclemendélius\", \"content\": \"<p>Caso reste apenas um único membro da família em combate, ele herda a vontade de seus irmão caídos. Este membro recebe Vantagem em todos os testes de d20 e um bônus de +5 e todos os testes de d20 até o fim do encontro.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"bonusActions\": [{\"id\": \"1787882913743-c3bd6aca54078\", \"lair\": {\"intro\": \"No valor de iniciativa 20 (perdendo empates de iniciativa), a criatura executa uma ação de covil para gerar um dos seguintes efeitos:\", \"enabled\": false}, \"type\": \"normal\", \"title\": \"Atiradora De Elite\", \"content\": \"<p>Abel estabiliza sua mira para garantir precisão absoluta. Ela recebe Vantagem em seu próximo ataque a distância, desde que não tenha se movido neste turno. Abel pode escolher permanecer imóvel até o início do seu próximo turno, Abel foca sua concentração e passa a jogar 3 dados, selecionando o melhor valor entre eles.</p>\", \"tracker\": {\"max\": 6, \"min\": 4, \"uses\": 0, \"reset\": \"\", \"title\": \"\", \"enabled\": false, \"customReset\": \"\"}, \"legendary\": {\"intro\": \"possui Três (3) Ações Lendárias e pode usar uma delas ao final do turno de outra criatura.\", \"enabled\": false, \"totalActions\": 3}, \"spellcasting\": {\"slots\": [], \"ability\": \"cha\", \"enabled\": false, \"casterLevel\": 1, \"saveDCExtra\": 0, \"attackBonusExtra\": 0}}], \"multiAttacks\": [{\"id\": \"1787880151443-332dba14cac88\", \"mode\": \"custom\", \"title\": \"Multiataque\", \"entries\": [{\"id\": \"1787880411632-fa7528f13f5d5\", \"source\": \"attack\", \"quantity\": 1, \"sourceId\": \"1787880154818-937398ef4a1f\"}, {\"id\": \"1787880543443-567a6fe9dea768\", \"source\": \"attack\", \"quantity\": 1, \"sourceId\": \"1787880421715-9f3e0c7d8e6958\"}], \"customText\": \"Abel realiza Dois (2) ataques usando Sniper ou Adaga, em qualquer combinação.\"}], \"savingThrows\": {\"cha\": {\"bonus\": 0, \"enabled\": false, \"proficient\": false}, \"con\": {\"bonus\": 0, \"enabled\": false, \"proficient\": false}, \"dex\": {\"bonus\": 0, \"enabled\": false, \"proficient\": true}, \"int\": {\"bonus\": 0, \"enabled\": false, \"proficient\": true}, \"str\": {\"bonus\": 0, \"enabled\": false, \"proficient\": false}, \"wis\": {\"bonus\": 0, \"enabled\": false, \"proficient\": false}}, \"mythicActions\": [], \"legendaryActions\": []}','npcs/A3fltSDUOHVoIoXNAncDwBsh4XAss2vCCPDjOnG7.png',NULL,NULL,'2026-08-28 05:25:22','2026-08-30 07:37:38');
